-- ################ GRADE 7 ################
SET NAMES utf8mb4;

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Kuwentong-bayan', m.description = 'Mga salaysay na nagpasalin-salin sa bibig ng mga tao at nagpapakita ng kultura ng isang pook.', m.content = '<p>Bago pa nagkaroon ng aklat at paaralan, ikinukuwento na ng ating mga ninuno ang mga salaysay tungkol sa kanilang buhay, paniniwala, at karanasan. Ipinapasa ang mga kuwentong ito mula sa magulang patungo sa anak, kaya umabot ang mga ito hanggang sa ating panahon.</p><p>Sa modyul na ito, pag-aaralan mo ang kuwentong-bayan, ang mga katangian nito, at kung bakit mahalaga pa rin ito sa atin bilang mga Pilipino.</p><h3>Ano ang kuwentong-bayan?</h3><ul><li><strong>Kuwentong-bayan</strong>: Ito ay salaysay na nagmula sa isang tiyak na pook at nagpasalin-salin sa bibig ng mga tao. Walang tiyak na may-akda ang karamihan sa mga ito dahil maraming tao ang nagkuwento at nagdagdag dito sa paglipas ng panahon. Dahil dito, maaaring magkakaiba ang bersyon ng iisang kuwento sa iba''t ibang lugar.</li><li><strong>Pasalindila</strong>: Tumutukoy ito sa paraan ng pagpapasa ng kuwento sa pamamagitan ng pagsasalaysay, hindi pagsusulat. Ito ang pangunahing paraan ng pagpapanatili ng kaalaman noong wala pang palimbagan. Ito rin ang dahilan kung bakit madaling tandaan ang mga kuwentong-bayan: payak ang mga pangyayari at malinaw ang aral.</li></ul><h3>Mga katangian ng kuwentong-bayan</h3><ul><li><strong>Tauhan</strong>: Karaniwang tao, hayop, o nilalang na may kapangyarihan ang mga tauhan. Madalas na may tauhang kumakatawan sa kabutihan at tauhang kumakatawan sa kasamaan, gaya ng tapat at sakim. Sa pamamagitan ng kanilang mga ginagawa, nakikita ng mambabasa kung ano ang dapat at hindi dapat tularan.</li><li><strong>Tagpuan</strong>: Karaniwang nasa isang nayon, gubat, bundok, o tabing-dagat ang tagpuan, na pamilyar sa mga taong nagkukuwento. Ipinapakita nito ang uri ng pamumuhay sa pook na pinagmulan ng kuwento.</li><li><strong>Banghay</strong>: Payak at madaling sundan ang pagkakasunod-sunod ng mga pangyayari. May simula, gitna, at wakas, at kadalasang nagtatapos sa gantimpala para sa mabuti at parusa para sa masama.</li><li><strong>Aral</strong>: Ito ang pinakamahalagang bahagi ng kuwentong-bayan. Itinuturo nito ang mabubuting asal gaya ng sipag, katapatan, pagtulong sa kapwa, at paggalang sa nakatatanda.</li></ul><h3>Kuwentong-bayan bilang salamin ng kultura</h3><p>Ang kultura ay ang kabuuang paraan ng pamumuhay ng isang pangkat ng tao: ang kanilang paniniwala, kaugalian, pagkain, at hanapbuhay. Makikita ang kultura sa kuwentong-bayan sa iba''t ibang paraan.</p><ul><li>Ipinapakita nito ang hanapbuhay ng mga tao, gaya ng pagsasaka, pangingisda, at pangangaso.</li><li>Ipinapakita nito ang paniniwala sa mga diwata, engkanto, at iba pang nilalang na nagbabantay sa kalikasan.</li><li>Ipinapakita nito ang mga pagpapahalaga ng pamayanan, gaya ng pagtutulungan at paggalang sa magulang.</li></ul><p>Halimbawa, sa maraming kuwento mula sa Mindanao, gaya ng sa mga Maranao at Manobo, makikita ang pagpapahalaga sa angkan, sa lupa, at sa mga ritwal ng pamayanan.</p><h3>Halimbawa: Si Juan Tamad</h3><table><thead><tr><th>Bahagi</th><th>Paliwanag</th></tr></thead><tbody><tr><td>Tauhan</td><td>Si Juan, isang batang ubod ng tamad</td></tr><tr><td>Pangyayari</td><td>Naghintay si Juan sa ilalim ng puno na kusang malaglag ang bunga sa kanyang bibig sa halip na pitasin ito</td></tr><tr><td>Bunga</td><td>Wala siyang nakain at napagtawanan ng mga tao</td></tr><tr><td>Aral</td><td>Hindi darating ang biyaya kung hindi kikilos; kailangan ang sipag upang makamit ang gusto</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng pasalindila?</li><li>Bakit walang tiyak na may-akda ang karamihan sa kuwentong-bayan?</li><li>Paano naipapakita ng kuwentong-bayan ang kultura ng isang pook?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pagpapasa ng kuwento sa pamamagitan ng pagsasalaysay, hindi pagsusulat.</li><li>Dahil maraming tao ang nagkuwento at nagdagdag dito sa paglipas ng panahon.</li><li>Sa pamamagitan ng hanapbuhay, paniniwala, at pagpapahalagang makikita sa kuwento.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-FIL' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Kuwentong-bayan', 'Mga salaysay na nagpasalin-salin sa bibig ng mga tao at nagpapakita ng kultura ng isang pook.', '<p>Bago pa nagkaroon ng aklat at paaralan, ikinukuwento na ng ating mga ninuno ang mga salaysay tungkol sa kanilang buhay, paniniwala, at karanasan. Ipinapasa ang mga kuwentong ito mula sa magulang patungo sa anak, kaya umabot ang mga ito hanggang sa ating panahon.</p><p>Sa modyul na ito, pag-aaralan mo ang kuwentong-bayan, ang mga katangian nito, at kung bakit mahalaga pa rin ito sa atin bilang mga Pilipino.</p><h3>Ano ang kuwentong-bayan?</h3><ul><li><strong>Kuwentong-bayan</strong>: Ito ay salaysay na nagmula sa isang tiyak na pook at nagpasalin-salin sa bibig ng mga tao. Walang tiyak na may-akda ang karamihan sa mga ito dahil maraming tao ang nagkuwento at nagdagdag dito sa paglipas ng panahon. Dahil dito, maaaring magkakaiba ang bersyon ng iisang kuwento sa iba''t ibang lugar.</li><li><strong>Pasalindila</strong>: Tumutukoy ito sa paraan ng pagpapasa ng kuwento sa pamamagitan ng pagsasalaysay, hindi pagsusulat. Ito ang pangunahing paraan ng pagpapanatili ng kaalaman noong wala pang palimbagan. Ito rin ang dahilan kung bakit madaling tandaan ang mga kuwentong-bayan: payak ang mga pangyayari at malinaw ang aral.</li></ul><h3>Mga katangian ng kuwentong-bayan</h3><ul><li><strong>Tauhan</strong>: Karaniwang tao, hayop, o nilalang na may kapangyarihan ang mga tauhan. Madalas na may tauhang kumakatawan sa kabutihan at tauhang kumakatawan sa kasamaan, gaya ng tapat at sakim. Sa pamamagitan ng kanilang mga ginagawa, nakikita ng mambabasa kung ano ang dapat at hindi dapat tularan.</li><li><strong>Tagpuan</strong>: Karaniwang nasa isang nayon, gubat, bundok, o tabing-dagat ang tagpuan, na pamilyar sa mga taong nagkukuwento. Ipinapakita nito ang uri ng pamumuhay sa pook na pinagmulan ng kuwento.</li><li><strong>Banghay</strong>: Payak at madaling sundan ang pagkakasunod-sunod ng mga pangyayari. May simula, gitna, at wakas, at kadalasang nagtatapos sa gantimpala para sa mabuti at parusa para sa masama.</li><li><strong>Aral</strong>: Ito ang pinakamahalagang bahagi ng kuwentong-bayan. Itinuturo nito ang mabubuting asal gaya ng sipag, katapatan, pagtulong sa kapwa, at paggalang sa nakatatanda.</li></ul><h3>Kuwentong-bayan bilang salamin ng kultura</h3><p>Ang kultura ay ang kabuuang paraan ng pamumuhay ng isang pangkat ng tao: ang kanilang paniniwala, kaugalian, pagkain, at hanapbuhay. Makikita ang kultura sa kuwentong-bayan sa iba''t ibang paraan.</p><ul><li>Ipinapakita nito ang hanapbuhay ng mga tao, gaya ng pagsasaka, pangingisda, at pangangaso.</li><li>Ipinapakita nito ang paniniwala sa mga diwata, engkanto, at iba pang nilalang na nagbabantay sa kalikasan.</li><li>Ipinapakita nito ang mga pagpapahalaga ng pamayanan, gaya ng pagtutulungan at paggalang sa magulang.</li></ul><p>Halimbawa, sa maraming kuwento mula sa Mindanao, gaya ng sa mga Maranao at Manobo, makikita ang pagpapahalaga sa angkan, sa lupa, at sa mga ritwal ng pamayanan.</p><h3>Halimbawa: Si Juan Tamad</h3><table><thead><tr><th>Bahagi</th><th>Paliwanag</th></tr></thead><tbody><tr><td>Tauhan</td><td>Si Juan, isang batang ubod ng tamad</td></tr><tr><td>Pangyayari</td><td>Naghintay si Juan sa ilalim ng puno na kusang malaglag ang bunga sa kanyang bibig sa halip na pitasin ito</td></tr><tr><td>Bunga</td><td>Wala siyang nakain at napagtawanan ng mga tao</td></tr><tr><td>Aral</td><td>Hindi darating ang biyaya kung hindi kikilos; kailangan ang sipag upang makamit ang gusto</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng pasalindila?</li><li>Bakit walang tiyak na may-akda ang karamihan sa kuwentong-bayan?</li><li>Paano naipapakita ng kuwentong-bayan ang kultura ng isang pook?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pagpapasa ng kuwento sa pamamagitan ng pagsasalaysay, hindi pagsusulat.</li><li>Dahil maraming tao ang nagkuwento at nagdagdag dito sa paglipas ng panahon.</li><li>Sa pamamagitan ng hanapbuhay, paniniwala, at pagpapahalagang makikita sa kuwento.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Pabula at Alamat', m.description = 'Dalawang anyo ng maikling kuwento na nagtuturo ng aral at nagpapaliwanag ng pinagmulan ng mga bagay.', m.content = '<p>Ang pabula at alamat ay kabilang sa mga pinakamatandang anyo ng panitikan. Pareho silang maikli, madaling tandaan, at may aral. Gayunman, magkaiba ang kanilang mga tauhan at ang layunin ng kanilang pagkukuwento.</p><p>Sa modyul na ito, kikilalanin mo ang bawat isa, ang kanilang mga elemento, at kung paano sila suriin.</p><h3>Ang pabula</h3><ul><li><strong>Kahulugan</strong>: Ang pabula ay maikling kuwento na ang mga tauhan ay hayop na kumikilos, nag-iisip, at nagsasalita na parang tao. Sa pamamagitan ng mga hayop, naipapakita ng kuwento ang ugali ng tao nang hindi tuwirang pinupuna ang sinuman.</li><li><strong>Simbolismo ng mga hayop</strong>: Karaniwang kumakatawan ang bawat hayop sa isang katangian. Halimbawa, ang matsing ay madalas na tuso, ang pagong ay mabagal ngunit matiyaga, at ang leon ay makapangyarihan. Dahil dito, madaling maunawaan ng mambabasa ang mensahe.</li><li><strong>Moral o aral</strong>: Laging may malinaw na aral ang pabula, at kung minsan ay tuwiran itong isinusulat sa dulo ng kuwento. Kilala sa daigdig ang mga pabula ni Aesop, isang manunulat mula sa sinaunang Gresya.</li></ul><h3>Ang alamat</h3><ul><li><strong>Kahulugan</strong>: Ang alamat ay kuwentong nagsasalaysay ng pinagmulan ng isang bagay, lugar, halaman, hayop, o pangalan. Sinasagot nito ang tanong na "Paano ito nagsimula?" sa paraang kawili-wili at kadalasang may halong hiwaga.</li><li><strong>Mga elemento</strong>: Tulad ng ibang kuwento, may tauhan, tagpuan, at banghay ang alamat. Ang kaibahan ay nagtatapos ito sa pagsilang o pagkakaroon ng isang bagay na kilala natin ngayon, gaya ng prutas o pangalan ng isang bayan.</li><li><strong>Aral sa alamat</strong>: Bagaman nagpapaliwanag ito ng pinagmulan, may aral din ang alamat. Madalas na itinuturo nito ang pagsunod sa magulang, ang pagiging masipag, at ang masamang bunga ng kasakiman.</li></ul><h3>Paano suriin ang pabula at alamat</h3><ul><li>Tukuyin ang mga tauhan at ang katangiang kinakatawan ng bawat isa.</li><li>Isulat ang mahahalagang pangyayari ayon sa pagkakasunod-sunod.</li><li>Alamin kung ano ang ipinaliliwanag ng kuwento (para sa alamat) o anong ugali ang pinupuna nito (para sa pabula).</li><li>Bumuo ng aral sa isang buong pangungusap at iugnay ito sa tunay na buhay.</li></ul><h3>Paghahambing ng pabula at alamat</h3><table><thead><tr><th></th><th>Pabula</th><th>Alamat</th></tr></thead><tbody><tr><td>Tauhan</td><td>Hayop na kumikilos na parang tao</td><td>Tao, diwata, o iba pang nilalang</td></tr><tr><td>Layunin</td><td>Magturo ng aral tungkol sa ugali</td><td>Ipaliwanag ang pinagmulan ng isang bagay</td></tr><tr><td>Halimbawa</td><td>Ang Pagong at ang Matsing</td><td>Alamat ng Pinya</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng tauhan sa pabula at sa alamat?</li><li>Anong tanong ang sinasagot ng alamat?</li><li>Sino ang kilalang manunulat ng pabula mula sa sinaunang Gresya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Hayop ang tauhan sa pabula; tao o iba pang nilalang ang karaniwang tauhan sa alamat.</li><li>Paano o saan nagsimula ang isang bagay?</li><li>Aesop</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-FIL' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Pabula at Alamat', 'Dalawang anyo ng maikling kuwento na nagtuturo ng aral at nagpapaliwanag ng pinagmulan ng mga bagay.', '<p>Ang pabula at alamat ay kabilang sa mga pinakamatandang anyo ng panitikan. Pareho silang maikli, madaling tandaan, at may aral. Gayunman, magkaiba ang kanilang mga tauhan at ang layunin ng kanilang pagkukuwento.</p><p>Sa modyul na ito, kikilalanin mo ang bawat isa, ang kanilang mga elemento, at kung paano sila suriin.</p><h3>Ang pabula</h3><ul><li><strong>Kahulugan</strong>: Ang pabula ay maikling kuwento na ang mga tauhan ay hayop na kumikilos, nag-iisip, at nagsasalita na parang tao. Sa pamamagitan ng mga hayop, naipapakita ng kuwento ang ugali ng tao nang hindi tuwirang pinupuna ang sinuman.</li><li><strong>Simbolismo ng mga hayop</strong>: Karaniwang kumakatawan ang bawat hayop sa isang katangian. Halimbawa, ang matsing ay madalas na tuso, ang pagong ay mabagal ngunit matiyaga, at ang leon ay makapangyarihan. Dahil dito, madaling maunawaan ng mambabasa ang mensahe.</li><li><strong>Moral o aral</strong>: Laging may malinaw na aral ang pabula, at kung minsan ay tuwiran itong isinusulat sa dulo ng kuwento. Kilala sa daigdig ang mga pabula ni Aesop, isang manunulat mula sa sinaunang Gresya.</li></ul><h3>Ang alamat</h3><ul><li><strong>Kahulugan</strong>: Ang alamat ay kuwentong nagsasalaysay ng pinagmulan ng isang bagay, lugar, halaman, hayop, o pangalan. Sinasagot nito ang tanong na "Paano ito nagsimula?" sa paraang kawili-wili at kadalasang may halong hiwaga.</li><li><strong>Mga elemento</strong>: Tulad ng ibang kuwento, may tauhan, tagpuan, at banghay ang alamat. Ang kaibahan ay nagtatapos ito sa pagsilang o pagkakaroon ng isang bagay na kilala natin ngayon, gaya ng prutas o pangalan ng isang bayan.</li><li><strong>Aral sa alamat</strong>: Bagaman nagpapaliwanag ito ng pinagmulan, may aral din ang alamat. Madalas na itinuturo nito ang pagsunod sa magulang, ang pagiging masipag, at ang masamang bunga ng kasakiman.</li></ul><h3>Paano suriin ang pabula at alamat</h3><ul><li>Tukuyin ang mga tauhan at ang katangiang kinakatawan ng bawat isa.</li><li>Isulat ang mahahalagang pangyayari ayon sa pagkakasunod-sunod.</li><li>Alamin kung ano ang ipinaliliwanag ng kuwento (para sa alamat) o anong ugali ang pinupuna nito (para sa pabula).</li><li>Bumuo ng aral sa isang buong pangungusap at iugnay ito sa tunay na buhay.</li></ul><h3>Paghahambing ng pabula at alamat</h3><table><thead><tr><th></th><th>Pabula</th><th>Alamat</th></tr></thead><tbody><tr><td>Tauhan</td><td>Hayop na kumikilos na parang tao</td><td>Tao, diwata, o iba pang nilalang</td></tr><tr><td>Layunin</td><td>Magturo ng aral tungkol sa ugali</td><td>Ipaliwanag ang pinagmulan ng isang bagay</td></tr><tr><td>Halimbawa</td><td>Ang Pagong at ang Matsing</td><td>Alamat ng Pinya</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng tauhan sa pabula at sa alamat?</li><li>Anong tanong ang sinasagot ng alamat?</li><li>Sino ang kilalang manunulat ng pabula mula sa sinaunang Gresya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Hayop ang tauhan sa pabula; tao o iba pang nilalang ang karaniwang tauhan sa alamat.</li><li>Paano o saan nagsimula ang isang bagay?</li><li>Aesop</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Philippine Folk Literature', m.description = 'The stories, sayings, and songs our ancestors passed down by word of mouth.', m.content = '<p>Long before Filipinos had printed books, they already had a rich literature. Stories, songs, riddles, and sayings were shared aloud around the fire, in the fields, and during celebrations. This body of work is called folk literature, and it remains an important part of our identity.</p><p>In this module, you will learn the main forms of Philippine folk literature and what each form tells us about the people who created it.</p><h3>What is folk literature?</h3><ul><li><strong>Folk literature</strong>: Folk literature is the collection of stories, songs, and sayings created by ordinary people and passed down orally from one generation to the next. Because it was spoken rather than written, a single story can have many versions depending on the region or the storyteller.</li><li><strong>Oral tradition</strong>: Oral tradition is the practice of preserving knowledge through speech. Our ancestors used it to teach history, values, and practical skills. Repetition, rhythm, and simple plots made these works easy to remember and retell.</li></ul><h3>Forms of folk literature</h3><ul><li><strong>Myths</strong>: Myths are stories about gods, goddesses, and supernatural beings. They often explain how the world, people, or natural events came to be. Many Tagalog myths, for example, name Bathala as the creator of the world.</li><li><strong>Legends</strong>: Legends explain the origin of a place, plant, animal, or name. They are usually set in a real location and may include real people mixed with magical events. The legend of Maria Makiling tells of a kind spirit who protects Mount Makiling in Laguna.</li><li><strong>Folk tales</strong>: Folk tales are simple stories about ordinary people or animals that usually teach a lesson. Characters are often clearly good or bad, and the ending rewards kindness and punishes greed or laziness.</li><li><strong>Epics</strong>: Epics are long narrative poems about heroes who perform great deeds. They were chanted or sung during important gatherings. Examples include Biag ni Lam-ang of the Ilocanos and the Hudhud of the Ifugao.</li><li><strong>Riddles and proverbs</strong>: Riddles (bugtong) are puzzles that describe something in a clever, hidden way. Proverbs (salawikain) are short sayings that express wisdom about life, such as advice on hard work or respect.</li></ul><h3>Why folk literature matters</h3><ul><li>It preserves the history and beliefs of our ancestors.</li><li>It teaches values such as respect for elders, hard work, and honesty.</li><li>It shows how different regions of the Philippines see the world.</li></ul><p>When you read folk literature, you are hearing the voices of Filipinos who lived hundreds of years ago.</p><h3>Summary of forms</h3><table><thead><tr><th>Form</th><th>Main purpose</th><th>Example</th></tr></thead><tbody><tr><td>Myth</td><td>Explains creation and nature through gods</td><td>Bathala creating the world</td></tr><tr><td>Legend</td><td>Explains the origin of a place or thing</td><td>Maria Makiling</td></tr><tr><td>Folk tale</td><td>Teaches a lesson through a simple story</td><td>Juan Tamad</td></tr><tr><td>Epic</td><td>Celebrates the deeds of a hero</td><td>Biag ni Lam-ang</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is oral tradition?</li><li>How is a legend different from a myth?</li><li>Give one Philippine epic.</li></ol><details><summary>Show answers</summary><ol><li>The practice of preserving knowledge and stories through speech.</li><li>A legend explains the origin of a place or thing; a myth is about gods and creation.</li><li>Any one: Biag ni Lam-ang, Hudhud</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-ENGLISH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Philippine Folk Literature', 'The stories, sayings, and songs our ancestors passed down by word of mouth.', '<p>Long before Filipinos had printed books, they already had a rich literature. Stories, songs, riddles, and sayings were shared aloud around the fire, in the fields, and during celebrations. This body of work is called folk literature, and it remains an important part of our identity.</p><p>In this module, you will learn the main forms of Philippine folk literature and what each form tells us about the people who created it.</p><h3>What is folk literature?</h3><ul><li><strong>Folk literature</strong>: Folk literature is the collection of stories, songs, and sayings created by ordinary people and passed down orally from one generation to the next. Because it was spoken rather than written, a single story can have many versions depending on the region or the storyteller.</li><li><strong>Oral tradition</strong>: Oral tradition is the practice of preserving knowledge through speech. Our ancestors used it to teach history, values, and practical skills. Repetition, rhythm, and simple plots made these works easy to remember and retell.</li></ul><h3>Forms of folk literature</h3><ul><li><strong>Myths</strong>: Myths are stories about gods, goddesses, and supernatural beings. They often explain how the world, people, or natural events came to be. Many Tagalog myths, for example, name Bathala as the creator of the world.</li><li><strong>Legends</strong>: Legends explain the origin of a place, plant, animal, or name. They are usually set in a real location and may include real people mixed with magical events. The legend of Maria Makiling tells of a kind spirit who protects Mount Makiling in Laguna.</li><li><strong>Folk tales</strong>: Folk tales are simple stories about ordinary people or animals that usually teach a lesson. Characters are often clearly good or bad, and the ending rewards kindness and punishes greed or laziness.</li><li><strong>Epics</strong>: Epics are long narrative poems about heroes who perform great deeds. They were chanted or sung during important gatherings. Examples include Biag ni Lam-ang of the Ilocanos and the Hudhud of the Ifugao.</li><li><strong>Riddles and proverbs</strong>: Riddles (bugtong) are puzzles that describe something in a clever, hidden way. Proverbs (salawikain) are short sayings that express wisdom about life, such as advice on hard work or respect.</li></ul><h3>Why folk literature matters</h3><ul><li>It preserves the history and beliefs of our ancestors.</li><li>It teaches values such as respect for elders, hard work, and honesty.</li><li>It shows how different regions of the Philippines see the world.</li></ul><p>When you read folk literature, you are hearing the voices of Filipinos who lived hundreds of years ago.</p><h3>Summary of forms</h3><table><thead><tr><th>Form</th><th>Main purpose</th><th>Example</th></tr></thead><tbody><tr><td>Myth</td><td>Explains creation and nature through gods</td><td>Bathala creating the world</td></tr><tr><td>Legend</td><td>Explains the origin of a place or thing</td><td>Maria Makiling</td></tr><tr><td>Folk tale</td><td>Teaches a lesson through a simple story</td><td>Juan Tamad</td></tr><tr><td>Epic</td><td>Celebrates the deeds of a hero</td><td>Biag ni Lam-ang</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is oral tradition?</li><li>How is a legend different from a myth?</li><li>Give one Philippine epic.</li></ol><details><summary>Show answers</summary><ol><li>The practice of preserving knowledge and stories through speech.</li><li>A legend explains the origin of a place or thing; a myth is about gods and creation.</li><li>Any one: Biag ni Lam-ang, Hudhud</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Parts of Speech', m.description = 'The eight kinds of words and the job each one does in a sentence.', m.content = '<p>Every word in a sentence has a job. Some words name things, some show action, and some connect ideas. These jobs are called the parts of speech. Knowing them helps you build correct sentences and understand grammar rules more easily.</p><p>English has eight parts of speech. In this module, you will learn what each one does and how to identify it.</p><h3>Words that name and replace</h3><ul><li><strong>Noun</strong>: A noun names a person, place, thing, or idea. Common nouns are general, like teacher or city, while proper nouns name specific ones and begin with a capital letter, like Mrs. Santos or Cebu. Nouns can also name things you cannot touch, such as honesty or happiness.</li><li><strong>Pronoun</strong>: A pronoun takes the place of a noun so we do not repeat the same word. Instead of saying "Ana said Ana is tired," we say "Ana said she is tired." Common pronouns include I, you, he, she, it, we, and they.</li></ul><h3>Words that show action and describe</h3><ul><li><strong>Verb</strong>: A verb shows an action (run, write, eat) or a state of being (is, am, are, was). Every complete sentence needs at least one verb. Verbs also change form to show time, such as walk, walked, and will walk.</li><li><strong>Adjective</strong>: An adjective describes a noun or pronoun. It answers questions like which one, what kind, or how many. In "three tall trees," both three and tall are adjectives.</li><li><strong>Adverb</strong>: An adverb describes a verb, an adjective, or another adverb. It answers how, when, where, or to what extent. Many adverbs end in -ly, such as quickly and carefully, but words like very, often, and here are also adverbs.</li></ul><h3>Words that connect and express</h3><ul><li><strong>Preposition</strong>: A preposition shows the relationship between a noun and another word, often about place or time. Examples are in, on, under, before, and between, as in "The book is on the table."</li><li><strong>Conjunction</strong>: A conjunction joins words, phrases, or sentences. The most common ones are and, but, or, and so. For example: "I wanted to go, but it was raining."</li><li><strong>Interjection</strong>: An interjection is a word that expresses strong feeling or surprise. It is often followed by an exclamation point, as in "Wow!" or "Ouch!"</li></ul><h3>Identifying parts of speech</h3><table><thead><tr><th>Word in "Wow, the tall boy quickly ran to the gate."</th><th>Part of speech</th></tr></thead><tbody><tr><td>Wow</td><td>Interjection</td></tr><tr><td>tall</td><td>Adjective</td></tr><tr><td>boy</td><td>Noun</td></tr><tr><td>quickly</td><td>Adverb</td></tr><tr><td>ran</td><td>Verb</td></tr><tr><td>to</td><td>Preposition</td></tr><tr><td>gate</td><td>Noun</td></tr></tbody></table><h3>Quick check</h3><ol><li>What part of speech replaces a noun?</li><li>In "She sings beautifully," what part of speech is beautifully?</li><li>What is the difference between a common noun and a proper noun?</li></ol><details><summary>Show answers</summary><ol><li>Pronoun</li><li>Adverb</li><li>A common noun is general; a proper noun names a specific person, place, or thing and is capitalized.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-ENGLISH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Parts of Speech', 'The eight kinds of words and the job each one does in a sentence.', '<p>Every word in a sentence has a job. Some words name things, some show action, and some connect ideas. These jobs are called the parts of speech. Knowing them helps you build correct sentences and understand grammar rules more easily.</p><p>English has eight parts of speech. In this module, you will learn what each one does and how to identify it.</p><h3>Words that name and replace</h3><ul><li><strong>Noun</strong>: A noun names a person, place, thing, or idea. Common nouns are general, like teacher or city, while proper nouns name specific ones and begin with a capital letter, like Mrs. Santos or Cebu. Nouns can also name things you cannot touch, such as honesty or happiness.</li><li><strong>Pronoun</strong>: A pronoun takes the place of a noun so we do not repeat the same word. Instead of saying "Ana said Ana is tired," we say "Ana said she is tired." Common pronouns include I, you, he, she, it, we, and they.</li></ul><h3>Words that show action and describe</h3><ul><li><strong>Verb</strong>: A verb shows an action (run, write, eat) or a state of being (is, am, are, was). Every complete sentence needs at least one verb. Verbs also change form to show time, such as walk, walked, and will walk.</li><li><strong>Adjective</strong>: An adjective describes a noun or pronoun. It answers questions like which one, what kind, or how many. In "three tall trees," both three and tall are adjectives.</li><li><strong>Adverb</strong>: An adverb describes a verb, an adjective, or another adverb. It answers how, when, where, or to what extent. Many adverbs end in -ly, such as quickly and carefully, but words like very, often, and here are also adverbs.</li></ul><h3>Words that connect and express</h3><ul><li><strong>Preposition</strong>: A preposition shows the relationship between a noun and another word, often about place or time. Examples are in, on, under, before, and between, as in "The book is on the table."</li><li><strong>Conjunction</strong>: A conjunction joins words, phrases, or sentences. The most common ones are and, but, or, and so. For example: "I wanted to go, but it was raining."</li><li><strong>Interjection</strong>: An interjection is a word that expresses strong feeling or surprise. It is often followed by an exclamation point, as in "Wow!" or "Ouch!"</li></ul><h3>Identifying parts of speech</h3><table><thead><tr><th>Word in "Wow, the tall boy quickly ran to the gate."</th><th>Part of speech</th></tr></thead><tbody><tr><td>Wow</td><td>Interjection</td></tr><tr><td>tall</td><td>Adjective</td></tr><tr><td>boy</td><td>Noun</td></tr><tr><td>quickly</td><td>Adverb</td></tr><tr><td>ran</td><td>Verb</td></tr><tr><td>to</td><td>Preposition</td></tr><tr><td>gate</td><td>Noun</td></tr></tbody></table><h3>Quick check</h3><ol><li>What part of speech replaces a noun?</li><li>In "She sings beautifully," what part of speech is beautifully?</li><li>What is the difference between a common noun and a proper noun?</li></ol><details><summary>Show answers</summary><ol><li>Pronoun</li><li>Adverb</li><li>A common noun is general; a proper noun names a specific person, place, or thing and is capitalized.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Sets', m.description = 'Collections of objects, how to describe them, and how to combine them.', m.content = '<p>We group things all the time: school supplies in a bag, classmates in a section, or songs in a playlist. In mathematics, a well-defined group of objects is called a set. Sets give us a clear language for describing and comparing groups.</p><p>In this module, you will learn how to write sets, the different kinds of sets, and the basic operations on them.</p><h3>Basic ideas</h3><ul><li><strong>Set</strong>: A set is a well-defined collection of objects. "Well-defined" means it is always clear whether an object belongs to the set or not. "The vowels in the English alphabet" is a set, but "the beautiful flowers" is not, because people may disagree on which flowers are beautiful.</li><li><strong>Element</strong>: An element is an object that belongs to a set. We use the symbol ∈ to mean "is an element of." If A = {1, 2, 3}, then 2 ∈ A, while 5 ∉ A.</li><li><strong>Ways of writing sets</strong>: In roster form, we list the elements inside braces: V = {a, e, i, o, u}. In rule form, we describe the elements: V = {x | x is a vowel in the English alphabet}.</li></ul><h3>Kinds of sets</h3><ul><li><strong>Empty set</strong>: A set with no elements, written { } or ∅. For example, the set of months with 32 days is empty.</li><li><strong>Finite and infinite sets</strong>: A finite set has a countable number of elements, like the days of the week. An infinite set goes on forever, like the set of counting numbers {1, 2, 3, …}.</li><li><strong>Subset</strong>: Set A is a subset of set B if every element of A is also in B, written A ⊆ B. For example, {2, 4} ⊆ {1, 2, 3, 4}.</li><li><strong>Universal set</strong>: The universal set, U, contains all the elements being considered in a problem. Every other set in the problem is a subset of U.</li></ul><h3>Operations on sets</h3><ul><li><strong>Union (A ∪ B)</strong>: The union of two sets contains all elements that are in A, in B, or in both. Each element is listed only once.</li><li><strong>Intersection (A ∩ B)</strong>: The intersection contains only the elements that are in both A and B. If two sets have no common element, their intersection is the empty set.</li><li><strong>Complement (A′)</strong>: The complement of A contains all elements of the universal set that are not in A.</li></ul><p>Venn diagrams use overlapping circles inside a rectangle to show these operations. The overlap of two circles represents the intersection.</p><h3>Worked example: U = {1, 2, 3, 4, 5, 6}, A = {1, 2, 3, 4}, B = {3, 4, 5}</h3><table><thead><tr><th>Operation</th><th>Result</th></tr></thead><tbody><tr><td>A ∪ B</td><td>{1, 2, 3, 4, 5}</td></tr><tr><td>A ∩ B</td><td>{3, 4}</td></tr><tr><td>A′</td><td>{5, 6}</td></tr><tr><td>B′</td><td>{1, 2, 6}</td></tr></tbody></table><h3>Quick check</h3><ol><li>Is "the set of tall students" well-defined? Why?</li><li>If A = {a, b, c} and B = {b, c, d}, find A ∩ B.</li><li>Is {1, 5} a subset of {1, 2, 3, 4}?</li></ol><details><summary>Show answers</summary><ol><li>No. People may disagree on who is tall.</li><li>{b, c}</li><li>No, because 5 is not in the second set.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-MATH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Sets', 'Collections of objects, how to describe them, and how to combine them.', '<p>We group things all the time: school supplies in a bag, classmates in a section, or songs in a playlist. In mathematics, a well-defined group of objects is called a set. Sets give us a clear language for describing and comparing groups.</p><p>In this module, you will learn how to write sets, the different kinds of sets, and the basic operations on them.</p><h3>Basic ideas</h3><ul><li><strong>Set</strong>: A set is a well-defined collection of objects. "Well-defined" means it is always clear whether an object belongs to the set or not. "The vowels in the English alphabet" is a set, but "the beautiful flowers" is not, because people may disagree on which flowers are beautiful.</li><li><strong>Element</strong>: An element is an object that belongs to a set. We use the symbol ∈ to mean "is an element of." If A = {1, 2, 3}, then 2 ∈ A, while 5 ∉ A.</li><li><strong>Ways of writing sets</strong>: In roster form, we list the elements inside braces: V = {a, e, i, o, u}. In rule form, we describe the elements: V = {x | x is a vowel in the English alphabet}.</li></ul><h3>Kinds of sets</h3><ul><li><strong>Empty set</strong>: A set with no elements, written { } or ∅. For example, the set of months with 32 days is empty.</li><li><strong>Finite and infinite sets</strong>: A finite set has a countable number of elements, like the days of the week. An infinite set goes on forever, like the set of counting numbers {1, 2, 3, …}.</li><li><strong>Subset</strong>: Set A is a subset of set B if every element of A is also in B, written A ⊆ B. For example, {2, 4} ⊆ {1, 2, 3, 4}.</li><li><strong>Universal set</strong>: The universal set, U, contains all the elements being considered in a problem. Every other set in the problem is a subset of U.</li></ul><h3>Operations on sets</h3><ul><li><strong>Union (A ∪ B)</strong>: The union of two sets contains all elements that are in A, in B, or in both. Each element is listed only once.</li><li><strong>Intersection (A ∩ B)</strong>: The intersection contains only the elements that are in both A and B. If two sets have no common element, their intersection is the empty set.</li><li><strong>Complement (A′)</strong>: The complement of A contains all elements of the universal set that are not in A.</li></ul><p>Venn diagrams use overlapping circles inside a rectangle to show these operations. The overlap of two circles represents the intersection.</p><h3>Worked example: U = {1, 2, 3, 4, 5, 6}, A = {1, 2, 3, 4}, B = {3, 4, 5}</h3><table><thead><tr><th>Operation</th><th>Result</th></tr></thead><tbody><tr><td>A ∪ B</td><td>{1, 2, 3, 4, 5}</td></tr><tr><td>A ∩ B</td><td>{3, 4}</td></tr><tr><td>A′</td><td>{5, 6}</td></tr><tr><td>B′</td><td>{1, 2, 6}</td></tr></tbody></table><h3>Quick check</h3><ol><li>Is "the set of tall students" well-defined? Why?</li><li>If A = {a, b, c} and B = {b, c, d}, find A ∩ B.</li><li>Is {1, 5} a subset of {1, 2, 3, 4}?</li></ol><details><summary>Show answers</summary><ol><li>No. People may disagree on who is tall.</li><li>{b, c}</li><li>No, because 5 is not in the second set.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Integers', m.description = 'Positive and negative whole numbers, absolute value, and the four operations.', m.content = '<p>A temperature of 3 degrees below zero, a basement floor, or a debt of ₱50 are all situations that need numbers less than zero. Integers let us describe amounts both above and below a starting point.</p><p>In this module, you will learn what integers are, how to compare them, and how to add, subtract, multiply, and divide them.</p><h3>Understanding integers</h3><ul><li><strong>Integers</strong>: Integers are the whole numbers and their opposites: …, −3, −2, −1, 0, 1, 2, 3, … They do not include fractions or decimals. Zero is an integer that is neither positive nor negative.</li><li><strong>Number line</strong>: On a number line, positive integers are to the right of zero and negative integers are to the left. A number farther to the right is always greater, so −2 is greater than −5.</li><li><strong>Opposites</strong>: Two numbers are opposites if they are the same distance from zero on opposite sides, such as 7 and −7. The sum of a number and its opposite is always zero.</li><li><strong>Absolute value</strong>: The absolute value of a number is its distance from zero, written |x|. Distance is never negative, so |−8| = 8 and |8| = 8.</li></ul><h3>Adding and subtracting</h3><ul><li><strong>Same signs</strong>: Add the absolute values and keep the common sign. For example, (−6) + (−4) = −10.</li><li><strong>Different signs</strong>: Subtract the smaller absolute value from the larger one, then use the sign of the number with the larger absolute value. For example, (−9) + 5 = −4.</li><li><strong>Subtraction</strong>: To subtract an integer, add its opposite. For example, 3 − (−5) becomes 3 + 5 = 8.</li></ul><h3>Multiplying and dividing</h3><ul><li><strong>Same signs</strong>: The product or quotient is positive. For example, (−4) × (−5) = 20 and (−18) ÷ (−3) = 6.</li><li><strong>Different signs</strong>: The product or quotient is negative. For example, 6 × (−3) = −18 and 20 ÷ (−4) = −5.</li></ul><p>A helpful way to remember: a negative times a negative is positive, just as removing a debt improves your situation.</p><h3>Rules at a glance</h3><table><thead><tr><th>Operation</th><th>Same signs</th><th>Different signs</th></tr></thead><tbody><tr><td>Addition</td><td>Add, keep the sign</td><td>Subtract, use the sign of the larger absolute value</td></tr><tr><td>Subtraction</td><td>Add the opposite, then follow addition rules</td><td>Add the opposite, then follow addition rules</td></tr><tr><td>Multiplication / Division</td><td>Positive</td><td>Negative</td></tr></tbody></table><h3>Quick check</h3><ol><li>Which is greater, −3 or −10?</li><li>Solve: (−7) + 12</li><li>Solve: 4 − (−6)</li><li>Solve: (−36) ÷ 9</li></ol><details><summary>Show answers</summary><ol><li>−3</li><li>5</li><li>10</li><li>−4</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-MATH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Integers', 'Positive and negative whole numbers, absolute value, and the four operations.', '<p>A temperature of 3 degrees below zero, a basement floor, or a debt of ₱50 are all situations that need numbers less than zero. Integers let us describe amounts both above and below a starting point.</p><p>In this module, you will learn what integers are, how to compare them, and how to add, subtract, multiply, and divide them.</p><h3>Understanding integers</h3><ul><li><strong>Integers</strong>: Integers are the whole numbers and their opposites: …, −3, −2, −1, 0, 1, 2, 3, … They do not include fractions or decimals. Zero is an integer that is neither positive nor negative.</li><li><strong>Number line</strong>: On a number line, positive integers are to the right of zero and negative integers are to the left. A number farther to the right is always greater, so −2 is greater than −5.</li><li><strong>Opposites</strong>: Two numbers are opposites if they are the same distance from zero on opposite sides, such as 7 and −7. The sum of a number and its opposite is always zero.</li><li><strong>Absolute value</strong>: The absolute value of a number is its distance from zero, written |x|. Distance is never negative, so |−8| = 8 and |8| = 8.</li></ul><h3>Adding and subtracting</h3><ul><li><strong>Same signs</strong>: Add the absolute values and keep the common sign. For example, (−6) + (−4) = −10.</li><li><strong>Different signs</strong>: Subtract the smaller absolute value from the larger one, then use the sign of the number with the larger absolute value. For example, (−9) + 5 = −4.</li><li><strong>Subtraction</strong>: To subtract an integer, add its opposite. For example, 3 − (−5) becomes 3 + 5 = 8.</li></ul><h3>Multiplying and dividing</h3><ul><li><strong>Same signs</strong>: The product or quotient is positive. For example, (−4) × (−5) = 20 and (−18) ÷ (−3) = 6.</li><li><strong>Different signs</strong>: The product or quotient is negative. For example, 6 × (−3) = −18 and 20 ÷ (−4) = −5.</li></ul><p>A helpful way to remember: a negative times a negative is positive, just as removing a debt improves your situation.</p><h3>Rules at a glance</h3><table><thead><tr><th>Operation</th><th>Same signs</th><th>Different signs</th></tr></thead><tbody><tr><td>Addition</td><td>Add, keep the sign</td><td>Subtract, use the sign of the larger absolute value</td></tr><tr><td>Subtraction</td><td>Add the opposite, then follow addition rules</td><td>Add the opposite, then follow addition rules</td></tr><tr><td>Multiplication / Division</td><td>Positive</td><td>Negative</td></tr></tbody></table><h3>Quick check</h3><ol><li>Which is greater, −3 or −10?</li><li>Solve: (−7) + 12</li><li>Solve: 4 − (−6)</li><li>Solve: (−36) ÷ 9</li></ol><details><summary>Show answers</summary><ol><li>−3</li><li>5</li><li>10</li><li>−4</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'The Scientific Method', m.description = 'The organized process scientists use to find reliable answers.', m.content = '<p>Science is not just a collection of facts. It is a way of finding answers to questions about the natural world. Scientists follow an organized process so that their answers are reliable and can be checked by others. This process is called the scientific method.</p><p>In this module, you will learn each step and the important ideas behind it.</p><h3>Steps of the scientific method</h3><ul><li><strong>Observation</strong>: Every investigation begins when someone notices something using the five senses. For example, you might notice that the plants beside your window are taller than the ones in the corner of the room. Good observations are careful and accurate, and scientists often write them down.</li><li><strong>Question</strong>: After observing, a scientist asks a question that can be answered through investigation. "Why are plants beautiful?" is hard to test, but "Does sunlight affect how tall a plant grows?" can be answered with an experiment.</li><li><strong>Hypothesis</strong>: A hypothesis is an educated guess that answers the question. It is often written as an "if…then" statement, such as "If a plant receives more sunlight, then it will grow taller." A hypothesis does not have to be correct; its purpose is to be tested.</li><li><strong>Experiment</strong>: An experiment is a planned test to check whether the hypothesis is true. Only one thing is changed at a time so that the cause of the result is clear. Experiments are repeated several times to make sure the results are not just luck.</li><li><strong>Data and analysis</strong>: Data are the measurements and observations collected during the experiment. Scientists organize data in tables and graphs so patterns are easier to see, then study them to find out what they show.</li><li><strong>Conclusion</strong>: The conclusion states whether the results support the hypothesis. If they do not, the scientist has still learned something and may form a new hypothesis. Conclusions are shared so others can check and repeat the work.</li></ul><h3>Variables in an experiment</h3><p>A variable is any factor that can change in an experiment. A fair experiment controls its variables carefully.</p><ul><li><strong>Independent variable</strong>: The factor the scientist changes on purpose. In the plant experiment, this is the amount of sunlight.</li><li><strong>Dependent variable</strong>: The factor that is measured to see the effect. In the plant experiment, this is the height of the plant.</li><li><strong>Controlled variables</strong>: The factors kept the same so they do not affect the result, such as the type of plant, the amount of water, and the kind of soil.</li></ul><h3>The plant experiment, step by step</h3><table><thead><tr><th>Step</th><th>Example</th></tr></thead><tbody><tr><td>Observation</td><td>Plants near the window are taller.</td></tr><tr><td>Question</td><td>Does sunlight affect plant height?</td></tr><tr><td>Hypothesis</td><td>If a plant gets more sunlight, then it will grow taller.</td></tr><tr><td>Experiment</td><td>Two identical plants: one by the window, one in a dark cabinet, with the same water and soil.</td></tr><tr><td>Data</td><td>Measure both plants every day for two weeks.</td></tr><tr><td>Conclusion</td><td>The plant in sunlight grew taller, so the hypothesis is supported.</td></tr></tbody></table><h3>Quick check</h3><ol><li>Why must a hypothesis be testable?</li><li>In an experiment on how salt affects how fast ice melts, what is the independent variable?</li><li>What should a scientist do if the results do not support the hypothesis?</li></ol><details><summary>Show answers</summary><ol><li>So it can be checked through an experiment.</li><li>The amount of salt.</li><li>Accept the result, then form and test a new hypothesis.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-SCI' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'The Scientific Method', 'The organized process scientists use to find reliable answers.', '<p>Science is not just a collection of facts. It is a way of finding answers to questions about the natural world. Scientists follow an organized process so that their answers are reliable and can be checked by others. This process is called the scientific method.</p><p>In this module, you will learn each step and the important ideas behind it.</p><h3>Steps of the scientific method</h3><ul><li><strong>Observation</strong>: Every investigation begins when someone notices something using the five senses. For example, you might notice that the plants beside your window are taller than the ones in the corner of the room. Good observations are careful and accurate, and scientists often write them down.</li><li><strong>Question</strong>: After observing, a scientist asks a question that can be answered through investigation. "Why are plants beautiful?" is hard to test, but "Does sunlight affect how tall a plant grows?" can be answered with an experiment.</li><li><strong>Hypothesis</strong>: A hypothesis is an educated guess that answers the question. It is often written as an "if…then" statement, such as "If a plant receives more sunlight, then it will grow taller." A hypothesis does not have to be correct; its purpose is to be tested.</li><li><strong>Experiment</strong>: An experiment is a planned test to check whether the hypothesis is true. Only one thing is changed at a time so that the cause of the result is clear. Experiments are repeated several times to make sure the results are not just luck.</li><li><strong>Data and analysis</strong>: Data are the measurements and observations collected during the experiment. Scientists organize data in tables and graphs so patterns are easier to see, then study them to find out what they show.</li><li><strong>Conclusion</strong>: The conclusion states whether the results support the hypothesis. If they do not, the scientist has still learned something and may form a new hypothesis. Conclusions are shared so others can check and repeat the work.</li></ul><h3>Variables in an experiment</h3><p>A variable is any factor that can change in an experiment. A fair experiment controls its variables carefully.</p><ul><li><strong>Independent variable</strong>: The factor the scientist changes on purpose. In the plant experiment, this is the amount of sunlight.</li><li><strong>Dependent variable</strong>: The factor that is measured to see the effect. In the plant experiment, this is the height of the plant.</li><li><strong>Controlled variables</strong>: The factors kept the same so they do not affect the result, such as the type of plant, the amount of water, and the kind of soil.</li></ul><h3>The plant experiment, step by step</h3><table><thead><tr><th>Step</th><th>Example</th></tr></thead><tbody><tr><td>Observation</td><td>Plants near the window are taller.</td></tr><tr><td>Question</td><td>Does sunlight affect plant height?</td></tr><tr><td>Hypothesis</td><td>If a plant gets more sunlight, then it will grow taller.</td></tr><tr><td>Experiment</td><td>Two identical plants: one by the window, one in a dark cabinet, with the same water and soil.</td></tr><tr><td>Data</td><td>Measure both plants every day for two weeks.</td></tr><tr><td>Conclusion</td><td>The plant in sunlight grew taller, so the hypothesis is supported.</td></tr></tbody></table><h3>Quick check</h3><ol><li>Why must a hypothesis be testable?</li><li>In an experiment on how salt affects how fast ice melts, what is the independent variable?</li><li>What should a scientist do if the results do not support the hypothesis?</li></ol><details><summary>Show answers</summary><ol><li>So it can be checked through an experiment.</li><li>The amount of salt.</li><li>Accept the result, then form and test a new hypothesis.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Solutions', m.description = 'Uniform mixtures, their parts, and the factors that affect dissolving.', m.content = '<p>When you stir sugar into a glass of water, the sugar seems to disappear, but the water now tastes sweet. The sugar did not vanish; it spread evenly throughout the water. This kind of mixture is called a solution.</p><p>In this module, you will learn the parts of a solution, the kinds of solutions, and what makes substances dissolve faster.</p><h3>Mixtures and solutions</h3><ul><li><strong>Mixture</strong>: A mixture is a combination of two or more substances that are not chemically joined. Each substance keeps its own properties, and the parts can often be separated by physical means.</li><li><strong>Solution</strong>: A solution is a homogeneous, or uniform, mixture. It looks the same throughout, and you cannot see the separate parts even with a magnifying glass. Saltwater, vinegar, and air are examples of solutions.</li><li><strong>Suspension</strong>: Unlike a solution, a suspension has particles large enough to settle at the bottom when left standing, such as muddy water. This is one way to tell a solution from other mixtures.</li></ul><h3>Parts of a solution</h3><ul><li><strong>Solute</strong>: The solute is the substance that is dissolved. It is usually present in the smaller amount. In sugar water, sugar is the solute.</li><li><strong>Solvent</strong>: The solvent is the substance that does the dissolving, usually present in the larger amount. Water is called the universal solvent because it can dissolve more substances than any other liquid.</li></ul><p>Solutions are not always liquid. Air is a gas solution, with oxygen and other gases dissolved in nitrogen. Brass is a solid solution of zinc in copper.</p><h3>Concentration</h3><ul><li><strong>Dilute solution</strong>: A dilute solution has only a small amount of solute. A glass of juice with a lot of water added is dilute.</li><li><strong>Concentrated solution</strong>: A concentrated solution has a large amount of solute. Undiluted juice concentrate is very concentrated.</li><li><strong>Saturated solution</strong>: A saturated solution holds the maximum amount of solute that can dissolve at a given temperature. If you add more, it will just settle at the bottom.</li></ul><h3>Factors that affect dissolving</h3><ul><li><strong>Temperature</strong>: Most solids dissolve faster in hot solvents because the particles move faster. This is why sugar dissolves quickly in hot coffee.</li><li><strong>Stirring</strong>: Stirring brings fresh solvent into contact with the solute, speeding up dissolving.</li><li><strong>Particle size</strong>: Smaller pieces dissolve faster than large chunks because more surface is exposed to the solvent. Powdered sugar dissolves faster than a sugar cube.</li></ul><h3>Examples of solutions</h3><table><thead><tr><th>Solution</th><th>Solute</th><th>Solvent</th></tr></thead><tbody><tr><td>Saltwater</td><td>Salt</td><td>Water</td></tr><tr><td>Sugar water</td><td>Sugar</td><td>Water</td></tr><tr><td>Vinegar</td><td>Acetic acid</td><td>Water</td></tr><tr><td>Air</td><td>Oxygen and other gases</td><td>Nitrogen</td></tr></tbody></table><h3>Quick check</h3><ol><li>How can you tell a solution from a suspension?</li><li>Why is water called the universal solvent?</li><li>Give two ways to make sugar dissolve faster.</li></ol><details><summary>Show answers</summary><ol><li>A solution is uniform and does not settle; particles in a suspension settle when left standing.</li><li>It can dissolve more substances than any other liquid.</li><li>Any two: heat the water, stir it, use smaller pieces of sugar.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-SCI' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Solutions', 'Uniform mixtures, their parts, and the factors that affect dissolving.', '<p>When you stir sugar into a glass of water, the sugar seems to disappear, but the water now tastes sweet. The sugar did not vanish; it spread evenly throughout the water. This kind of mixture is called a solution.</p><p>In this module, you will learn the parts of a solution, the kinds of solutions, and what makes substances dissolve faster.</p><h3>Mixtures and solutions</h3><ul><li><strong>Mixture</strong>: A mixture is a combination of two or more substances that are not chemically joined. Each substance keeps its own properties, and the parts can often be separated by physical means.</li><li><strong>Solution</strong>: A solution is a homogeneous, or uniform, mixture. It looks the same throughout, and you cannot see the separate parts even with a magnifying glass. Saltwater, vinegar, and air are examples of solutions.</li><li><strong>Suspension</strong>: Unlike a solution, a suspension has particles large enough to settle at the bottom when left standing, such as muddy water. This is one way to tell a solution from other mixtures.</li></ul><h3>Parts of a solution</h3><ul><li><strong>Solute</strong>: The solute is the substance that is dissolved. It is usually present in the smaller amount. In sugar water, sugar is the solute.</li><li><strong>Solvent</strong>: The solvent is the substance that does the dissolving, usually present in the larger amount. Water is called the universal solvent because it can dissolve more substances than any other liquid.</li></ul><p>Solutions are not always liquid. Air is a gas solution, with oxygen and other gases dissolved in nitrogen. Brass is a solid solution of zinc in copper.</p><h3>Concentration</h3><ul><li><strong>Dilute solution</strong>: A dilute solution has only a small amount of solute. A glass of juice with a lot of water added is dilute.</li><li><strong>Concentrated solution</strong>: A concentrated solution has a large amount of solute. Undiluted juice concentrate is very concentrated.</li><li><strong>Saturated solution</strong>: A saturated solution holds the maximum amount of solute that can dissolve at a given temperature. If you add more, it will just settle at the bottom.</li></ul><h3>Factors that affect dissolving</h3><ul><li><strong>Temperature</strong>: Most solids dissolve faster in hot solvents because the particles move faster. This is why sugar dissolves quickly in hot coffee.</li><li><strong>Stirring</strong>: Stirring brings fresh solvent into contact with the solute, speeding up dissolving.</li><li><strong>Particle size</strong>: Smaller pieces dissolve faster than large chunks because more surface is exposed to the solvent. Powdered sugar dissolves faster than a sugar cube.</li></ul><h3>Examples of solutions</h3><table><thead><tr><th>Solution</th><th>Solute</th><th>Solvent</th></tr></thead><tbody><tr><td>Saltwater</td><td>Salt</td><td>Water</td></tr><tr><td>Sugar water</td><td>Sugar</td><td>Water</td></tr><tr><td>Vinegar</td><td>Acetic acid</td><td>Water</td></tr><tr><td>Air</td><td>Oxygen and other gases</td><td>Nitrogen</td></tr></tbody></table><h3>Quick check</h3><ol><li>How can you tell a solution from a suspension?</li><li>Why is water called the universal solvent?</li><li>Give two ways to make sugar dissolve faster.</li></ol><details><summary>Show answers</summary><ol><li>A solution is uniform and does not settle; particles in a suspension settle when left standing.</li><li>It can dissolve more substances than any other liquid.</li><li>Any two: heat the water, stir it, use smaller pieces of sugar.</li></ol></details>', 1 FROM courses c
