UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Heograpiya ng Asya', m.description = 'Ang lokasyon, laki, mga rehiyon, at anyong-lupa at anyong-tubig ng Asya.', m.content = '<p>Ang Asya ang ating kontinente. Dito matatagpuan ang Pilipinas at ang mga bansang may malaking ambag sa kasaysayan ng daigdig. Upang maunawaan ang buhay ng mga Asyano, kailangan munang kilalanin ang lupain at karagatang kanilang tinitirhan.</p><p>Sa modyul na ito, pag-aaralan mo ang lokasyon, laki, at mga rehiyon ng Asya, pati ang mahahalagang anyong-lupa at anyong-tubig nito.</p><h3>Mahahalagang konsepto</h3><ul><li><strong>Heograpiya</strong>: Ang heograpiya ay pag-aaral ng katangiang pisikal ng daigdig, gaya ng lupa, tubig, at klima, at ng ugnayan ng mga ito sa tao. Ipinapaliwanag nito kung bakit magkakaiba ang pamumuhay ng mga tao sa iba''t ibang lugar.</li><li><strong>Kontinente</strong>: Ang kontinente ay malaking masa ng lupa. Pito ang kontinente sa daigdig, at ang Asya ang pinakamalaki sa lawak at sa dami ng tao. Halos one-third ng kabuuang lupain ng mundo ay sakop ng Asya.</li><li><strong>Lokasyon</strong>: Ang lokasyong absolute ay tiyak na kinaroroonan gamit ang latitude at longitude. Ang lokasyong relatibo naman ay paglalarawan batay sa mga katabing lugar. Halimbawa, ang Asya ay napapaligiran ng Karagatang Pasipiko sa silangan, Karagatang Indian sa timog, at Karagatang Arctic sa hilaga.</li></ul><h3>Limang rehiyon ng Asya</h3><p>Hinahati ang Asya sa limang rehiyon batay sa lokasyon, kultura, at katangiang pisikal.</p><ul><li><strong>Hilagang Asya</strong>: Malawak at malamig na rehiyon na kinabibilangan ng Siberia at mga bansang tulad ng Kazakhstan at Mongolia.</li><li><strong>Kanlurang Asya</strong>: Kilala rin bilang Gitnang Silangan; mayaman sa langis at pinagmulan ng tatlong malalaking relihiyon. Kabilang dito ang Saudi Arabia at Iran.</li><li><strong>Timog Asya</strong>: Kinabibilangan ng India, Pakistan, at Bangladesh; dito matatagpuan ang Himalayas.</li><li><strong>Silangang Asya</strong>: Kinabibilangan ng China, Japan, at South Korea; kilala sa mabilis na pag-unlad ng ekonomiya.</li><li><strong>Timog-Silangang Asya</strong>: Kinabibilangan ng Pilipinas, Indonesia, Thailand, at Vietnam; maraming kapuluan at tropikal ang klima.</li></ul><h3>Anyong-lupa at anyong-tubig</h3><ul><li><strong>Bundok at kabundukan</strong>: Nasa Asya ang Mt. Everest, ang pinakamataas na bundok sa mundo, na bahagi ng Himalayas. Ang mga kabundukan ay nagsisilbing likas na hangganan ng mga bansa.</li><li><strong>Kapatagan at lambak</strong>: Ang matatabang kapatagan sa tabi ng mga ilog ang naging tirahan ng maraming tao at pinagmulan ng mga sinaunang kabihasnan.</li><li><strong>Ilog</strong>: Mahahalagang ilog ang Huang Ho at Yangtze sa China, ang Indus at Ganges sa Timog Asya, at ang Tigris at Euphrates sa Kanlurang Asya. Pinagkukunan ang mga ito ng tubig, pagkain, at daanan ng kalakalan.</li></ul><h3>Buod ng mga rehiyon</h3><table><thead><tr><th>Rehiyon</th><th>Halimbawang bansa</th><th>Katangian</th></tr></thead><tbody><tr><td>Hilaga</td><td>Mongolia, Kazakhstan</td><td>Malamig at malawak</td></tr><tr><td>Kanluran</td><td>Saudi Arabia, Iran</td><td>Mayaman sa langis</td></tr><tr><td>Timog</td><td>India, Pakistan</td><td>Kinaroroonan ng Himalayas</td></tr><tr><td>Silangan</td><td>China, Japan</td><td>Mauunlad na ekonomiya</td></tr><tr><td>Timog-Silangan</td><td>Pilipinas, Indonesia</td><td>Kapuluan at tropikal</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng lokasyong absolute at relatibo?</li><li>Saang rehiyon kabilang ang Pilipinas?</li><li>Bakit sa tabi ng ilog umusbong ang maraming pamayanan?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang absolute ay gumagamit ng latitude at longitude; ang relatibo ay batay sa mga katabing lugar.</li><li>Timog-Silangang Asya</li><li>Dahil may tubig, matabang lupa, at daanan ng kalakalan.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-AP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Heograpiya ng Asya', 'Ang lokasyon, laki, mga rehiyon, at anyong-lupa at anyong-tubig ng Asya.', '<p>Ang Asya ang ating kontinente. Dito matatagpuan ang Pilipinas at ang mga bansang may malaking ambag sa kasaysayan ng daigdig. Upang maunawaan ang buhay ng mga Asyano, kailangan munang kilalanin ang lupain at karagatang kanilang tinitirhan.</p><p>Sa modyul na ito, pag-aaralan mo ang lokasyon, laki, at mga rehiyon ng Asya, pati ang mahahalagang anyong-lupa at anyong-tubig nito.</p><h3>Mahahalagang konsepto</h3><ul><li><strong>Heograpiya</strong>: Ang heograpiya ay pag-aaral ng katangiang pisikal ng daigdig, gaya ng lupa, tubig, at klima, at ng ugnayan ng mga ito sa tao. Ipinapaliwanag nito kung bakit magkakaiba ang pamumuhay ng mga tao sa iba''t ibang lugar.</li><li><strong>Kontinente</strong>: Ang kontinente ay malaking masa ng lupa. Pito ang kontinente sa daigdig, at ang Asya ang pinakamalaki sa lawak at sa dami ng tao. Halos one-third ng kabuuang lupain ng mundo ay sakop ng Asya.</li><li><strong>Lokasyon</strong>: Ang lokasyong absolute ay tiyak na kinaroroonan gamit ang latitude at longitude. Ang lokasyong relatibo naman ay paglalarawan batay sa mga katabing lugar. Halimbawa, ang Asya ay napapaligiran ng Karagatang Pasipiko sa silangan, Karagatang Indian sa timog, at Karagatang Arctic sa hilaga.</li></ul><h3>Limang rehiyon ng Asya</h3><p>Hinahati ang Asya sa limang rehiyon batay sa lokasyon, kultura, at katangiang pisikal.</p><ul><li><strong>Hilagang Asya</strong>: Malawak at malamig na rehiyon na kinabibilangan ng Siberia at mga bansang tulad ng Kazakhstan at Mongolia.</li><li><strong>Kanlurang Asya</strong>: Kilala rin bilang Gitnang Silangan; mayaman sa langis at pinagmulan ng tatlong malalaking relihiyon. Kabilang dito ang Saudi Arabia at Iran.</li><li><strong>Timog Asya</strong>: Kinabibilangan ng India, Pakistan, at Bangladesh; dito matatagpuan ang Himalayas.</li><li><strong>Silangang Asya</strong>: Kinabibilangan ng China, Japan, at South Korea; kilala sa mabilis na pag-unlad ng ekonomiya.</li><li><strong>Timog-Silangang Asya</strong>: Kinabibilangan ng Pilipinas, Indonesia, Thailand, at Vietnam; maraming kapuluan at tropikal ang klima.</li></ul><h3>Anyong-lupa at anyong-tubig</h3><ul><li><strong>Bundok at kabundukan</strong>: Nasa Asya ang Mt. Everest, ang pinakamataas na bundok sa mundo, na bahagi ng Himalayas. Ang mga kabundukan ay nagsisilbing likas na hangganan ng mga bansa.</li><li><strong>Kapatagan at lambak</strong>: Ang matatabang kapatagan sa tabi ng mga ilog ang naging tirahan ng maraming tao at pinagmulan ng mga sinaunang kabihasnan.</li><li><strong>Ilog</strong>: Mahahalagang ilog ang Huang Ho at Yangtze sa China, ang Indus at Ganges sa Timog Asya, at ang Tigris at Euphrates sa Kanlurang Asya. Pinagkukunan ang mga ito ng tubig, pagkain, at daanan ng kalakalan.</li></ul><h3>Buod ng mga rehiyon</h3><table><thead><tr><th>Rehiyon</th><th>Halimbawang bansa</th><th>Katangian</th></tr></thead><tbody><tr><td>Hilaga</td><td>Mongolia, Kazakhstan</td><td>Malamig at malawak</td></tr><tr><td>Kanluran</td><td>Saudi Arabia, Iran</td><td>Mayaman sa langis</td></tr><tr><td>Timog</td><td>India, Pakistan</td><td>Kinaroroonan ng Himalayas</td></tr><tr><td>Silangan</td><td>China, Japan</td><td>Mauunlad na ekonomiya</td></tr><tr><td>Timog-Silangan</td><td>Pilipinas, Indonesia</td><td>Kapuluan at tropikal</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng lokasyong absolute at relatibo?</li><li>Saang rehiyon kabilang ang Pilipinas?</li><li>Bakit sa tabi ng ilog umusbong ang maraming pamayanan?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang absolute ay gumagamit ng latitude at longitude; ang relatibo ay batay sa mga katabing lugar.</li><li>Timog-Silangang Asya</li><li>Dahil may tubig, matabang lupa, at daanan ng kalakalan.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Likas na Yaman ng Asya', m.description = 'Ang mga uri ng likas na yaman ng Asya at ang wastong paggamit nito.', m.content = '<p>Mula sa palay na kinakain natin hanggang sa langis na nagpapatakbo ng sasakyan, maraming bagay ang nagmumula sa kalikasan. Mayaman ang Asya sa ganitong mga yaman, at ito ang pinagkukunan ng kabuhayan ng milyon-milyong tao.</p><p>Sa modyul na ito, kikilalanin mo ang mga uri ng likas na yaman, kung saan ito matatagpuan sa Asya, at kung bakit kailangan itong pangalagaan.</p><h3>Mga uri ng likas na yaman</h3><ul><li><strong>Yamang-lupa</strong>: Kabilang dito ang lupang taniman, kagubatan, at pastulan. Ang malalawak na kapatagan ng Timog at Timog-Silangang Asya ay ginagamit sa pagtatanim ng palay, na pangunahing pagkain ng mga Asyano.</li><li><strong>Yamang-tubig</strong>: Kabilang dito ang isda, korales, perlas, at iba pang galing sa dagat, ilog, at lawa. Ang Pilipinas at Indonesia ay may malalawak na karagatan na mayaman sa yamang-dagat.</li><li><strong>Yamang-mineral</strong>: Kabilang dito ang langis, natural gas, ginto, tanso, at karbon. Ang Kanlurang Asya ay may isa sa pinakamalalaking reserba ng langis sa mundo.</li><li><strong>Yamang-gubat</strong>: Kabilang dito ang troso, rattan, kawayan, at mga halamang gamot. Nagbibigay rin ang kagubatan ng tirahan sa maraming hayop.</li></ul><h3>Kahalagahan ng likas na yaman</h3><ul><li>Pinagkukunan ito ng pagkain, tubig, at tirahan.</li><li>Pinagmumulan ito ng hanapbuhay gaya ng pagsasaka, pangingisda, at pagmimina.</li><li>Nagdadala ito ng kita sa bansa sa pamamagitan ng pagluluwas ng produkto.</li></ul><h3>Mga suliranin at pangangalaga</h3><ul><li><strong>Pagkaubos ng yaman</strong>: Kapag labis ang paggamit, nauubos ang yaman nang mas mabilis kaysa sa kakayahan nitong mapalitan. Halimbawa, ang labis na pagputol ng puno ay nagdudulot ng pagguho ng lupa at pagbaha.</li><li><strong>Konserbasyon</strong>: Ang konserbasyon ay matalino at matipid na paggamit ng likas na yaman upang may matira pa para sa susunod na henerasyon. Halimbawa nito ang reforestation, o muling pagtatanim ng puno.</li><li><strong>Sustainable development</strong>: Ito ay pag-unlad na tumutugon sa pangangailangan ngayon nang hindi isinasakripisyo ang pangangailangan ng hinaharap. Layunin nitong balansehin ang kabuhayan at ang kalikasan.</li></ul><h3>Likas na yaman ayon sa rehiyon</h3><table><thead><tr><th>Rehiyon</th><th>Pangunahing likas na yaman</th></tr></thead><tbody><tr><td>Kanlurang Asya</td><td>Langis at natural gas</td></tr><tr><td>Timog Asya</td><td>Palay, trigo, at bulak</td></tr><tr><td>Silangang Asya</td><td>Karbon at yamang-dagat</td></tr><tr><td>Timog-Silangang Asya</td><td>Palay, troso, at yamang-dagat</td></tr><tr><td>Hilagang Asya</td><td>Troso at mineral</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang yamang-mineral? Magbigay ng halimbawa.</li><li>Ano ang konserbasyon?</li><li>Ano ang maaaring mangyari kapag labis ang pagputol ng puno?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Mga mineral mula sa lupa, gaya ng langis, ginto, at tanso.</li><li>Matalino at matipid na paggamit ng likas na yaman upang may matira para sa hinaharap.</li><li>Pagguho ng lupa at pagbaha.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-AP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Likas na Yaman ng Asya', 'Ang mga uri ng likas na yaman ng Asya at ang wastong paggamit nito.', '<p>Mula sa palay na kinakain natin hanggang sa langis na nagpapatakbo ng sasakyan, maraming bagay ang nagmumula sa kalikasan. Mayaman ang Asya sa ganitong mga yaman, at ito ang pinagkukunan ng kabuhayan ng milyon-milyong tao.</p><p>Sa modyul na ito, kikilalanin mo ang mga uri ng likas na yaman, kung saan ito matatagpuan sa Asya, at kung bakit kailangan itong pangalagaan.</p><h3>Mga uri ng likas na yaman</h3><ul><li><strong>Yamang-lupa</strong>: Kabilang dito ang lupang taniman, kagubatan, at pastulan. Ang malalawak na kapatagan ng Timog at Timog-Silangang Asya ay ginagamit sa pagtatanim ng palay, na pangunahing pagkain ng mga Asyano.</li><li><strong>Yamang-tubig</strong>: Kabilang dito ang isda, korales, perlas, at iba pang galing sa dagat, ilog, at lawa. Ang Pilipinas at Indonesia ay may malalawak na karagatan na mayaman sa yamang-dagat.</li><li><strong>Yamang-mineral</strong>: Kabilang dito ang langis, natural gas, ginto, tanso, at karbon. Ang Kanlurang Asya ay may isa sa pinakamalalaking reserba ng langis sa mundo.</li><li><strong>Yamang-gubat</strong>: Kabilang dito ang troso, rattan, kawayan, at mga halamang gamot. Nagbibigay rin ang kagubatan ng tirahan sa maraming hayop.</li></ul><h3>Kahalagahan ng likas na yaman</h3><ul><li>Pinagkukunan ito ng pagkain, tubig, at tirahan.</li><li>Pinagmumulan ito ng hanapbuhay gaya ng pagsasaka, pangingisda, at pagmimina.</li><li>Nagdadala ito ng kita sa bansa sa pamamagitan ng pagluluwas ng produkto.</li></ul><h3>Mga suliranin at pangangalaga</h3><ul><li><strong>Pagkaubos ng yaman</strong>: Kapag labis ang paggamit, nauubos ang yaman nang mas mabilis kaysa sa kakayahan nitong mapalitan. Halimbawa, ang labis na pagputol ng puno ay nagdudulot ng pagguho ng lupa at pagbaha.</li><li><strong>Konserbasyon</strong>: Ang konserbasyon ay matalino at matipid na paggamit ng likas na yaman upang may matira pa para sa susunod na henerasyon. Halimbawa nito ang reforestation, o muling pagtatanim ng puno.</li><li><strong>Sustainable development</strong>: Ito ay pag-unlad na tumutugon sa pangangailangan ngayon nang hindi isinasakripisyo ang pangangailangan ng hinaharap. Layunin nitong balansehin ang kabuhayan at ang kalikasan.</li></ul><h3>Likas na yaman ayon sa rehiyon</h3><table><thead><tr><th>Rehiyon</th><th>Pangunahing likas na yaman</th></tr></thead><tbody><tr><td>Kanlurang Asya</td><td>Langis at natural gas</td></tr><tr><td>Timog Asya</td><td>Palay, trigo, at bulak</td></tr><tr><td>Silangang Asya</td><td>Karbon at yamang-dagat</td></tr><tr><td>Timog-Silangang Asya</td><td>Palay, troso, at yamang-dagat</td></tr><tr><td>Hilagang Asya</td><td>Troso at mineral</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang yamang-mineral? Magbigay ng halimbawa.</li><li>Ano ang konserbasyon?</li><li>Ano ang maaaring mangyari kapag labis ang pagputol ng puno?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Mga mineral mula sa lupa, gaya ng langis, ginto, at tanso.</li><li>Matalino at matipid na paggamit ng likas na yaman upang may matira para sa hinaharap.</li><li>Pagguho ng lupa at pagbaha.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Pagkilala sa Sarili', m.description = 'Ang pag-unawa sa sariling katangian at sa mga pagbabago sa pagdadalaga at pagbibinata.', m.content = '<p>Sa yugtong ito ng iyong buhay, maraming nagbabago: ang iyong katawan, ang iyong mga kaibigan, at ang paraan ng iyong pag-iisip. Ang pagkilala sa sarili ang tutulong sa iyo upang harapin ang mga pagbabagong ito nang may tiwala.</p><p>Sa modyul na ito, pag-aaralan mo kung ano ang pagkilala sa sarili, ang mga pagbabago sa pagdadalaga at pagbibinata, at kung paano mo mapapaunlad ang iyong sarili.</p><h3>Ano ang pagkilala sa sarili?</h3><ul><li><strong>Pagkilala sa sarili</strong>: Ito ay ang pag-alam sa iyong mga katangian, damdamin, hilig, at pinahahalagahan. Kapag kilala mo ang iyong sarili, mas madali kang makagagawa ng tamang pasya at mas maayos mong mapakikitunguhan ang iba.</li><li><strong>Kalakasan</strong>: Ito ang mga bagay na mahusay mong ginagawa, gaya ng pagguhit, pakikinig sa kaibigan, o paglutas ng math problem. Ang pagkilala sa kalakasan ay nagbibigay ng tiwala sa sarili.</li><li><strong>Kahinaan</strong>: Ito ang mga bagay na kailangan mo pang paunlarin. Hindi ito dapat ikahiya; bahagi ito ng pagiging tao. Ang mahalaga ay kilalanin ito at gumawa ng hakbang upang mapabuti.</li></ul><h3>Mga pagbabago sa pagdadalaga at pagbibinata</h3><p>Ang pagdadalaga at pagbibinata ay ang yugto ng paglipat mula sa pagkabata tungo sa pagiging ganap na tao. Normal at inaasahan ang mga pagbabagong kaakibat nito.</p><ul><li><strong>Pisikal</strong>: Mabilis na paglaki ng katawan at iba pang pagbabago na dulot ng paglaki.</li><li><strong>Pangkaisipan</strong>: Mas malalim na pag-iisip, pagtatanong, at pagbuo ng sariling opinyon.</li><li><strong>Pandamdamin</strong>: Mas matinding damdamin at mabilis na pagbabago ng emosyon.</li><li><strong>Panlipunan</strong>: Mas lumalalim na pakikipagkaibigan at pagnanais na matanggap ng kapwa.</li></ul><h3>Mga paraan upang lalong makilala ang sarili</h3><ul><li>Magnilay o sumulat sa journal tungkol sa iyong mga karanasan at damdamin.</li><li>Humingi ng puna sa pinagkakatiwalaang tao, gaya ng magulang, guro, o kaibigan.</li><li>Subukan ang mga bagong gawain upang matuklasan ang iyong hilig at galing.</li><li>Magtakda ng maliit na layunin upang mapaunlad ang isang kahinaan.</li></ul><h3>Halimbawa: Ang pagkilala ni Leo sa sarili</h3><table><thead><tr><th>Aspekto</th><th>Paglalarawan</th></tr></thead><tbody><tr><td>Kalakasan</td><td>Magaling gumuhit at malikhain</td></tr><tr><td>Kahinaan</td><td>Nahihiyang magsalita sa harap ng klase</td></tr><tr><td>Hakbang</td><td>Sumali sa art club at nagsanay mag-report sa maliit na grupo</td></tr><tr><td>Resulta</td><td>Unti-unting lumakas ang loob niyang magsalita</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkilala sa sarili?</li><li>Normal ba ang mga pagbabago sa pagdadalaga at pagbibinata?</li><li>Magbigay ng isang paraan upang lalong makilala ang sarili.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pag-alam sa sariling katangian, damdamin, hilig, at pinahahalagahan.</li><li>Oo, bahagi ito ng paglaki.</li><li>Halimbawa: pagsusulat sa journal, paghingi ng puna, pagsubok ng bagong gawain.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-ESP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Pagkilala sa Sarili', 'Ang pag-unawa sa sariling katangian at sa mga pagbabago sa pagdadalaga at pagbibinata.', '<p>Sa yugtong ito ng iyong buhay, maraming nagbabago: ang iyong katawan, ang iyong mga kaibigan, at ang paraan ng iyong pag-iisip. Ang pagkilala sa sarili ang tutulong sa iyo upang harapin ang mga pagbabagong ito nang may tiwala.</p><p>Sa modyul na ito, pag-aaralan mo kung ano ang pagkilala sa sarili, ang mga pagbabago sa pagdadalaga at pagbibinata, at kung paano mo mapapaunlad ang iyong sarili.</p><h3>Ano ang pagkilala sa sarili?</h3><ul><li><strong>Pagkilala sa sarili</strong>: Ito ay ang pag-alam sa iyong mga katangian, damdamin, hilig, at pinahahalagahan. Kapag kilala mo ang iyong sarili, mas madali kang makagagawa ng tamang pasya at mas maayos mong mapakikitunguhan ang iba.</li><li><strong>Kalakasan</strong>: Ito ang mga bagay na mahusay mong ginagawa, gaya ng pagguhit, pakikinig sa kaibigan, o paglutas ng math problem. Ang pagkilala sa kalakasan ay nagbibigay ng tiwala sa sarili.</li><li><strong>Kahinaan</strong>: Ito ang mga bagay na kailangan mo pang paunlarin. Hindi ito dapat ikahiya; bahagi ito ng pagiging tao. Ang mahalaga ay kilalanin ito at gumawa ng hakbang upang mapabuti.</li></ul><h3>Mga pagbabago sa pagdadalaga at pagbibinata</h3><p>Ang pagdadalaga at pagbibinata ay ang yugto ng paglipat mula sa pagkabata tungo sa pagiging ganap na tao. Normal at inaasahan ang mga pagbabagong kaakibat nito.</p><ul><li><strong>Pisikal</strong>: Mabilis na paglaki ng katawan at iba pang pagbabago na dulot ng paglaki.</li><li><strong>Pangkaisipan</strong>: Mas malalim na pag-iisip, pagtatanong, at pagbuo ng sariling opinyon.</li><li><strong>Pandamdamin</strong>: Mas matinding damdamin at mabilis na pagbabago ng emosyon.</li><li><strong>Panlipunan</strong>: Mas lumalalim na pakikipagkaibigan at pagnanais na matanggap ng kapwa.</li></ul><h3>Mga paraan upang lalong makilala ang sarili</h3><ul><li>Magnilay o sumulat sa journal tungkol sa iyong m