UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Introduction to TLE', m.description = 'What Technology and Livelihood Education covers and why its skills matter.', m.content = '<p>Technology and Livelihood Education, or TLE, teaches practical skills you can use at home, in business, and in future work. Unlike many subjects that focus on ideas, TLE focuses on doing: cooking, building, repairing, growing, and using technology.</p><p>In this module, you will learn the four main areas of TLE, the skills each develops, and how these skills connect to jobs and livelihood.</p><h3>What is TLE?</h3><ul><li><strong>Technology and Livelihood Education</strong>: TLE is a learning area that develops practical knowledge and work skills. It prepares students for everyday tasks, for small business, and for further training in technical-vocational fields.</li><li><strong>Livelihood</strong>: Livelihood is the means by which a person earns a living. Skills learned in TLE, such as baking or electrical wiring, can become a source of income.</li><li><strong>Exploratory courses</strong>: In Grades 7 and 8, students take exploratory courses to try different TLE areas. This helps them discover what they enjoy and are good at before choosing a specialization in Grade 9.</li></ul><h3>The four areas of TLE</h3><ul><li><strong>Home Economics</strong>: Covers skills for the home and service industries, such as cookery, dressmaking, caregiving, and beauty care. These skills support businesses like food stalls and tailoring shops.</li><li><strong>Industrial Arts</strong>: Covers technical and construction skills, such as carpentry, masonry, plumbing, and electrical installation. These skills are needed in building and maintaining homes and structures.</li><li><strong>Agri-Fishery Arts</strong>: Covers farming, gardening, animal raising, and fishing. These skills support food production, an important industry in the Philippines.</li><li><strong>Information and Communications Technology (ICT)</strong>: Covers computer skills such as basic computer operations, computer hardware servicing, and creating digital content.</li></ul><h3>Why TLE skills matter</h3><ul><li>They make you more independent and helpful at home.</li><li>They can be used to start a small business.</li><li>They can lead to TESDA certification and employment.</li><li>They develop good work habits like safety, accuracy, and responsibility.</li></ul><h3>TLE areas and sample careers</h3><table><thead><tr><th>Area</th><th>Sample skill</th><th>Sample career</th></tr></thead><tbody><tr><td>Home Economics</td><td>Cookery</td><td>Cook, caterer</td></tr><tr><td>Industrial Arts</td><td>Electrical installation</td><td>Electrician</td></tr><tr><td>Agri-Fishery Arts</td><td>Crop production</td><td>Farmer, agriculturist</td></tr><tr><td>ICT</td><td>Computer servicing</td><td>Computer technician</td></tr></tbody></table><h3>Quick check</h3><ol><li>What does TLE stand for?</li><li>Which TLE area includes carpentry and plumbing?</li><li>Why do Grades 7 and 8 take exploratory courses?</li></ol><details><summary>Show answers</summary><ol><li>Technology and Livelihood Education</li><li>Industrial Arts</li><li>To try different TLE areas before choosing a specialization.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-TLE' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
