UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Workplace Safety', m.description = 'Hazards, protective equipment, and safety rules in the TLE workplace.', m.content = '<p>Working with knives, stoves, electricity, and tools can be dangerous if we are careless. Most accidents can be prevented by following simple safety rules. Safety protects not only you but also the people working around you.</p><p>In this module, you will learn about hazards, personal protective equipment, and basic safety practices in the TLE workplace.</p><h3>Understanding hazards and risks</h3><ul><li><strong>Hazard</strong>: A hazard is anything that can cause harm, such as a sharp knife, a wet floor, an exposed wire, or a strong chemical. Recognizing hazards is the first step to preventing accidents.</li><li><strong>Risk</strong>: Risk is the chance that a hazard will actually cause harm. A sharp knife stored properly has low risk; the same knife left on the edge of a table has high risk.</li><li><strong>Accident</strong>: An accident is an unplanned event that causes injury or damage. Most accidents happen because of unsafe actions, unsafe conditions, or both.</li></ul><h3>Personal protective equipment (PPE)</h3><p>PPE is gear worn to protect the body from hazards. The right PPE depends on the task.</p><ul><li><strong>Apron</strong>: Protects clothing and skin from spills and stains in cooking.</li><li><strong>Gloves</strong>: Protect hands from cuts, heat, and chemicals.</li><li><strong>Safety goggles</strong>: Protect the eyes from flying particles and splashes.</li><li><strong>Closed shoes</strong>: Protect the feet from falling objects and sharp items.</li><li><strong>Face mask</strong>: Protects against dust and fumes.</li></ul><h3>Basic safety rules</h3><ul><li>Keep the work area clean, dry, and organized.</li><li>Use each tool only for its intended purpose, and inspect it before use.</li><li>Never touch electrical outlets or switches with wet hands.</li><li>Report broken tools and unsafe conditions to the teacher right away.</li><li>Know where the first aid kit and fire extinguisher are kept.</li></ul><h3>First aid</h3><ul><li><strong>First aid</strong>: First aid is the immediate care given to an injured person before professional help arrives. For a minor cut, wash the wound with clean water, apply pressure to stop bleeding, and cover it with a clean bandage. For a minor burn, cool the area under running water.</li></ul><h3>Hazards and how to prevent them</h3><table><thead><tr><th>Hazard</th><th>Possible injury</th><th>Prevention</th></tr></thead><tbody><tr><td>Wet floor</td><td>Slipping</td><td>Wipe spills immediately</td></tr><tr><td>Sharp knife</td><td>Cuts</td><td>Cut away from the body; store properly</td></tr><tr><td>Exposed wire</td><td>Electric shock</td><td>Report it; do not touch</td></tr><tr><td>Hot pan</td><td>Burns</td><td>Use pot holders or gloves</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is the difference between a hazard and a risk?</li><li>What does PPE stand for?</li><li>What should you do first for a minor burn?</li></ol><details><summary>Show answers</summary><ol><li>A hazard can cause harm; risk is the chance that it will.</li><li>Personal Protective Equipment</li><li>Cool the area under running water.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-TLE' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
