UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Karunungang-bayan', m.description = 'Mga pahayag ng ating mga ninuno na puno ng aral at talino.', m.content = '<p>Bago pa magkaroon ng paaralan, itinuturo na ng ating mga ninuno ang aral sa pamamagitan ng maiikling pahayag.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Karunungang-bayan</strong> – mga pahayag na nagmula sa ating mga ninuno at nagtataglay ng aral.</li><li><strong>Salawikain</strong> – pahayag na may malalim na aral tungkol sa buhay.</li><li><strong>Sawikain</strong> – idyoma o pahayag na hindi tuwiran ang kahulugan.</li><li><strong>Bugtong</strong> – palaisipang may nakatagong sagot.</li></ul><h3>Halimbawa</h3><blockquote><p>Salawikain: &quot;Kung ano ang itinanim, siya ring aanihin.&quot; Sawikain: &quot;Makapal ang mukha&quot; (walang hiya). Bugtong: &quot;Isang prinsesa, nakaupo sa tasa.&quot; Sagot: kasoy.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang salawikain?</li><li>Ano ang ibig sabihin ng sawikaing &quot;Makapal ang mukha&quot;?</li><li>Ano ang bugtong?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pahayag na may malalim na aral tungkol sa buhay.</li><li>Walang hiya</li><li>Palaisipang may nakatagong sagot.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-FIL' AND m.module_number = 1 AND m.updated_by IS NULL;
