SELECT c.id, 1, 'Karunungang-bayan', 'Mga pahayag ng ating mga ninuno na puno ng aral at talino.', '<p>Bago pa magkaroon ng paaralan, itinuturo na ng ating mga ninuno ang aral sa pamamagitan ng maiikling pahayag.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Karunungang-bayan</strong> – mga pahayag na nagmula sa ating mga ninuno at nagtataglay ng aral.</li><li><strong>Salawikain</strong> – pahayag na may malalim na aral tungkol sa buhay.</li><li><strong>Sawikain</strong> – idyoma o pahayag na hindi tuwiran ang kahulugan.</li><li><strong>Bugtong</strong> – palaisipang may nakatagong sagot.</li></ul><h3>Halimbawa</h3><blockquote><p>Salawikain: &quot;Kung ano ang itinanim, siya ring aanihin.&quot; Sawikain: &quot;Makapal ang mukha&quot; (walang hiya). Bugtong: &quot;Isang prinsesa, nakaupo sa tasa.&quot; Sagot: kasoy.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang salawikain?</li><li>Ano ang ibig sabihin ng sawikaing &quot;Makapal ang mukha&quot;?</li><li>Ano ang bugtong?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pahayag na may malalim na aral tungkol sa buhay.</li><li>Walang hiya</li><li>Palaisipang may nakatagong sagot.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Florante at Laura: Kaligiran ng Akda', m.description = 'Ang may-akda at ang kasaysayan ng obra maestra ni Balagtas.', m.content = '<p>Ang Florante at Laura ay isa sa pinakamahahalagang akda sa panitikang Pilipino.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Francisco Balagtas</strong> – ang sumulat ng Florante at Laura, kilala bilang &quot;Prinsipe ng Makatang Tagalog.&quot;</li><li><strong>Awit</strong> – tulang may labindalawang pantig bawat taludtod.</li><li><strong>Tagpuan</strong> – ang Albanya, isang kaharian sa Europa.</li><li><strong>Alegorya</strong> – akdang may nakatagong kahulugan sa likod ng kuwento.</li></ul><h3>Halimbawa</h3><blockquote><p>Itinakda ni Balagtas ang kuwento sa Albanya upang maitago ang kanyang puna sa pang-aabuso ng mga Kastila sa Pilipinas.</p></blockquote><h3>Pagsusulit</h3><ol><li>Sino ang sumulat ng Florante at Laura?</li><li>Ilang pantig mayroon ang bawat taludtod ng awit?</li><li>Bakit sa Albanya itinakda ang kuwento?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Francisco Balagtas</li><li>Labindalawa</li><li>Upang maitago ang puna sa pamahalaang Kastila.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-FIL' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Florante at Laura: Kaligiran ng Akda', 'Ang may-akda at ang kasaysayan ng obra maestra ni Balagtas.', '<p>Ang Florante at Laura ay isa sa pinakamahahalagang akda sa panitikang Pilipino.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Francisco Balagtas</strong> – ang sumulat ng Florante at Laura, kilala bilang &quot;Prinsipe ng Makatang Tagalog.&quot;</li><li><strong>Awit</strong> – tulang may labindalawang pantig bawat taludtod.</li><li><strong>Tagpuan</strong> – ang Albanya, isang kaharian sa Europa.</li><li><strong>Alegorya</strong> – akdang may nakatagong kahulugan sa likod ng kuwento.</li></ul><h3>Halimbawa</h3><blockquote><p>Itinakda ni Balagtas ang kuwento sa Albanya upang maitago ang kanyang puna sa pang-aabuso ng mga Kastila sa Pilipinas.</p></blockquote><h3>Pagsusulit</h3><ol><li>Sino ang sumulat ng Florante at Laura?</li><li>Ilang pantig mayroon ang bawat taludtod ng awit?</li><li>Bakit sa Albanya itinakda ang kuwento?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Francisco Balagtas</li><li>Labindalawa</li><li>Upang maitago ang puna sa pamahalaang Kastila.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Afro-Asian Literature', m.description = 'Stories and poems from the cultures of Africa and Asia.', m.content = '<p>Africa and Asia have rich literary traditions that show values like respect for elders, family, and nature.</p><h3>Key terms</h3><ul><li><strong>Afro-Asian literature</strong> – literary works from Africa and Asia.</li><li><strong>Haiku</strong> – a Japanese poem of three lines with 5, 7, and 5 syllables.</li><li><strong>Fable</strong> – a short story, often with animals, that teaches a lesson.</li><li><strong>Epic</strong> – a long poem about the adventures of a hero.</li></ul><h3>Example</h3><blockquote><p>A haiku: &quot;Rain on the tin roof / the old cat curls by the stove / waiting for the sun.&quot; It has 5, 7, and 5 syllables.</p></blockquote><h3>Quick check</h3><ol><li>What is a haiku?</li><li>What is an epic?</li><li>Name one value often seen in Afro-Asian literature.</li></ol><details><summary>Show answers</summary><ol><li>A Japanese poem of three lines with 5, 7, and 5 syllables.</li><li>A long poem about the adventures of a hero.</li><li>Any one: respect for elders, family, nature</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-ENGLISH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Afro-Asian Literature', 'Stories and poems from the cultures of Africa and Asia.', '<p>Africa and Asia have rich literary traditions that show values like respect for elders, family, and nature.</p><h3>Key terms</h3><ul><li><strong>Afro-Asian literature</strong> – literary works from Africa and Asia.</li><li><strong>Haiku</strong> – a Japanese poem of three lines with 5, 7, and 5 syllables.</li><li><strong>Fable</strong> – a short story, often with animals, that teaches a lesson.</li><li><strong>Epic</strong> – a long poem about the adventures of a hero.</li></ul><h3>Example</h3><blockquote><p>A haiku: &quot;Rain on the tin roof / the old cat curls by the stove / waiting for the sun.&quot; It has 5, 7, and 5 syllables.</p></blockquote><h3>Quick check</h3><ol><li>What is a haiku?</li><li>What is an epic?</li><li>Name one value often seen in Afro-Asian literature.</li></ol><details><summary>Show answers</summary><ol><li>A Japanese poem of three lines with 5, 7, and 5 syllables.</li><li>A long poem about the adventures of a hero.</li><li>Any one: respect for elders, family, nature</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Context Clues', m.description = 'Using nearby words to understand unfamiliar words.', m.content = '<p>You do not always need a dictionary. The words around an unfamiliar word can give you hints.</p><h3>Key terms</h3><ul><li><strong>Context clues</strong> – hints in a sentence that help explain the meaning of a word.</li><li><strong>Definition clue</strong> – the meaning is given directly.</li><li><strong>Synonym clue</strong> – a word with a similar meaning is nearby.</li><li><strong>Antonym clue</strong> – a word with the opposite meaning is nearby.</li><li><strong>Example clue</strong> – examples show the meaning.</li></ul><h3>Example</h3><blockquote><p>&quot;The house was immaculate, so clean that not a speck of dust could be found.&quot; The phrase &quot;so clean&quot; tells us immaculate means very clean.</p></blockquote><h3>Quick check</h3><ol><li>What are context clues?</li><li>In &quot;He was timid, not brave like his brother,&quot; what does timid mean?</li><li>What type of clue gives the meaning directly?</li></ol><details><summary>Show answers</summary><ol><li>Hints in a sentence that help explain a word&#x27;s meaning.</li><li>Shy or not brave (antonym clue)</li><li>Definition clue</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-ENGLISH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Context Clues', 'Using nearby words to understand unfamiliar words.', '<p>You do not always need a dictionary. The words around an unfamiliar word can give you hints.</p><h3>Key terms</h3><ul><li><strong>Context clues</strong> – hints in a sentence that help explain the meaning of a word.</li><li><strong>Definition clue</strong> – the meaning is given directly.</li><li><strong>Synonym clue</strong> – a word with a similar meaning is nearby.</li><li><strong>Antonym clue</strong> – a word with the opposite meaning is nearby.</li><li><strong>Example clue</strong> – examples show the meaning.</li></ul><h3>Example</h3><blockquote><p>&quot;The house was immaculate, so clean that not a speck of dust could be found.&quot; The phrase &quot;so clean&quot; tells us immaculate means very clean.</p></blockquote><h3>Quick check</h3><ol><li>What are context clues?</li><li>In &quot;He was timid, not brave like his brother,&quot; what does timid mean?</li><li>What type of clue gives the meaning directly?</li></ol><details><summary>Show answers</summary><ol><li>Hints in a sentence that help explain a word&#x27;s meaning.</li><li>Shy or not brave (antonym clue)</li><li>Definition clue</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Factoring Polynomials', m.description = 'Writing a polynomial as a product of simpler factors.', m.content = '<p>Factoring is the reverse of multiplying. It breaks an expression into parts that multiply to give it.</p><h3>Key terms</h3><ul><li><strong>Polynomial</strong> – an expression with one or more terms, like x² + 5x + 6.</li><li><strong>Factor</strong> – an expression that divides another evenly.</li><li><strong>Greatest common factor (GCF)</strong> – the largest factor shared by all terms.</li><li><strong>Difference of two squares</strong> – a² − b² = (a + b)(a − b).</li></ul><h3>Example</h3><blockquote><p>GCF: 6x + 9 = 3(2x + 3). Difference of squares: x² − 25 = (x + 5)(x − 5). Trinomial: x² + 5x + 6 = (x + 2)(x + 3), because 2 × 3 = 6 and 2 + 3 = 5.</p></blockquote><h3>Quick check</h3><ol><li>Factor 4x + 12.</li><li>Factor x² − 16.</li><li>Factor x² + 7x + 10.</li></ol><details><summary>Show answers</summary><ol><li>4(x + 3)</li><li>(x + 4)(x − 4)</li><li>(x + 2)(x + 5)</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-MATH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Factoring Polynomials', 'Writing a polynomial as a product of simpler factors.', '<p>Factoring is the reverse of multiplying. It breaks an expression into parts that multiply to give it.</p><h3>Key terms</h3><ul><li><strong>Polynomial</strong> – an expression with one or more terms, like x² + 5x + 6.</li><li><strong>Factor</strong> – an expression that divides another evenly.</li><li><strong>Greatest common factor (GCF)</strong> – the largest factor shared by all terms.</li><li><strong>Difference of two squares</strong> – a² − b² = (a + b)(a − b).</li></ul><h3>Example</h3><blockquote><p>GCF: 6x + 9 = 3(2x + 3). Difference of squares: x² − 25 = (x + 5)(x − 5). Trinomial: x² + 5x + 6 = (x + 2)(x + 3), because 2 × 3 = 6 and 2 + 3 = 5.</p></blockquote><h3>Quick check</h3><ol><li>Factor 4x + 12.</li><li>Factor x² − 16.</li><li>Factor x² + 7x + 10.</li></ol><details><summary>Show answers</summary><ol><li>4(x + 3)</li><li>(x + 4)(x − 4)</li><li>(x + 2)(x + 5)</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Rational Algebraic Expressions', m.description = 'Fractions with polynomials, and how to simplify them.', m.content = '<p>Just like fractions with numbers, we can have fractions with variables.</p><p>To simplify, factor the numerator and denominator, then cancel common factors.</p><h3>Key terms</h3><ul><li><strong>Rational algebraic expression</strong> – a fraction whose numerator and denominator are polynomials.</li><li><strong>Simplest form</strong> – when the numerator and denominator have no common factor.</li><li><strong>Restriction</strong> – a value that makes the denominator zero, which is not allowed.</li></ul><h3>Example</h3><blockquote><p>(x² − 9) / (x + 3) = (x + 3)(x − 3) / (x + 3) = x − 3, where x ≠ −3.</p></blockquote><h3>Quick check</h3><ol><li>What is a rational algebraic expression?</li><li>Simplify (2x + 4) / 2.</li><li>Why can&#x27;t the denominator be zero?</li></ol><details><summary>Show answers</summary><ol><li>A fraction whose numerator and denominator are polynomials.</li><li>x + 2</li><li>Division by zero is undefined.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-MATH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Rational Algebraic Expressions', 'Fractions with polynomials, and how to simplify them.', '<p>Just like fractions with numbers, we can have fractions with variables.</p><p>To simplify, factor the numerator and denominator, then cancel common factors.</p><h3>Key terms</h3><ul><li><strong>Rational algebraic expression</strong> – a fraction whose numerator and denominator are polynomials.</li><li><strong>Simplest form</strong> – when the numerator and denominator have no common factor.</li><li><strong>Restriction</strong> – a value that makes the denominator zero, which is not allowed.</li></ul><h3>Example</h3><blockquote><p>(x² − 9) / (x + 3) = (x + 3)(x − 3) / (x + 3) = x − 3, where x ≠ −3.</p></blockquote><h3>Quick check</h3><ol><li>What is a rational algebraic expression?</li><li>Simplify (2x + 4) / 2.</li><li>Why can&#x27;t the denominator be zero?</li></ol><details><summary>Show answers</summary><ol><li>A fraction whose numerator and denominator are polynomials.</li><li>x + 2</li><li>Division by zero is undefined.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Forces and Newton''s Laws', m.description = 'How forces change the motion of objects.', m.content = '<p>Every push or pull you make is a force. Newton&#x27;s three laws explain how forces affect motion.</p><h3>Key terms</h3><ul><li><strong>Force</strong> – a push or pull, measured in newtons (N).</li><li><strong>Inertia</strong> – the tendency of an object to resist change in its motion.</li><li><strong>First law</strong> – an object stays at rest or in motion unless a force acts on it.</li><li><strong>Second law</strong> – force = mass × acceleration (F = ma).</li><li><strong>Third law</strong> – for every action, there is an equal and opposite reaction.</li></ul><h3>Example</h3><blockquote><p>Passengers lurch forward when a jeepney stops suddenly (first law). A rocket pushes gas down, and the gas pushes the rocket up (third law).</p></blockquote><h3>Quick check</h3><ol><li>What is inertia?</li><li>What is the formula of the second law?</li><li>Which law explains a rocket launch?</li></ol><details><summary>Show answers</summary><ol><li>The tendency of an object to resist change in motion.</li><li>F = ma</li><li>Third law</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-SCI' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Forces and Newton''s Laws', 'How forces change the motion of objects.', '<p>Every push or pull you make is a force. Newton&#x27;s three laws explain how forces affect motion.</p><h3>Key terms</h3><ul><li><strong>Force</strong> – a push or pull, measured in newtons (N).</li><li><strong>Inertia</strong> – the tendency of an object to resist change in its motion.</li><li><strong>First law</strong> – an object stays at rest or in motion unless a force acts on it.</li><li><strong>Second law</strong> – force = mass × acceleration (F = ma).</li><li><strong>Third law</strong> – for every action, there is an equal and opposite reaction.</li></ul><h3>Example</h3><blockquote><p>Passengers lurch forward when a jeepney stops suddenly (first law). A rocket pushes gas down, and the gas pushes the rocket up (third law).</p></blockquote><h3>Quick check</h3><ol><li>What is inertia?</li><li>What is the formula of the second law?</li><li>Which law explains a rocket launch?</li></ol><details><summary>Show answers</summary><ol><li>The tendency of an object to resist change in motion.</li><li>F = ma</li><li>Third law</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Work, Power, and Energy', m.description = 'How force moves objects and how energy changes form.', m.content = '<p>When you lift your bag, you do work and use energy. These ideas are connected.</p><h3>Key terms</h3><ul><li><strong>Work</strong> – done when a force moves an object; work = force × distance, measured in joules (J).</li><li><strong>Energy</strong> – the ability to do work.</li><li><strong>Kinetic energy</strong> – energy of a moving object.</li><li><strong>Potential energy</strong> – stored energy, such as an object held high.</li><li><strong>Power</strong> – how fast work is done; power = work ÷ time, measured in watts (W).</li></ul><h3>Example</h3><blockquote><p>Lifting a 20 N box up 2 m does 20 × 2 = 40 J of work. If it takes 4 seconds, power = 40 ÷ 4 = 10 W.</p></blockquote><h3>Quick check</h3><ol><li>What is energy?</li><li>A ball rolling down a hill has what kind of energy?</li><li>Pushing with 10 N for 3 m does how much work?</li></ol><details><summary>Show answers</summary><ol><li>The ability to do work.</li><li>Kinetic energy</li><li>30 J</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-SCI' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Work, Power, and Energy', 'How force moves objects and how energy changes form.', '<p>When you lift your bag, you do work and use energy. These ideas are connected.</p><h3>Key terms</h3><ul><li><strong>Work</strong> – done when a force moves an object; work = force × distance, measured in joules (J).</li><li><strong>Energy</strong> – the ability to do work.</li><li><strong>Kinetic energy</strong> – energy of a moving object.</li><li><strong>Potential energy</strong> – stored energy, such as an object held high.</li><li><strong>Power</strong> – how fast work is done; power = work ÷ time, measured in watts (W).</li></ul><h3>Example</h3><blockquote><p>Lifting a 20 N box up 2 m does 20 × 2 = 40 J of work. If it takes 4 seconds, power = 40 ÷ 4 = 10 W.</p></blockquote><h3>Quick check</h3><ol><li>What is energy?</li><li>A ball rolling down a hill has what kind of energy?</li><li>Pushing with 10 N for 3 m does how much work?</li></ol><details><summary>Show answers</summary><ol><li>The ability to do work.</li><li>Kinetic energy</li><li>30 J</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Heograpiya ng Daigdig', m.description = 'Ang mga katangiang pisikal ng mundo at kung paano ito nakaaapekto sa tao.', m.content = '<p>Upang maunawaan ang kasaysayan ng daigdig, kailangan munang kilalanin ang mundong pinangyarihan nito.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Kontinente</strong> – malaking masa ng lupa; may pito sa daigdig.</li><li><strong>Karagatan</strong> – malaking anyong-tubig; may lima sa daigdig.</li><li><strong>Latitude</strong> – guhit na pahalang na sumusukat ng layo mula sa ekwador.</li><li><strong>Longitude</strong> – guhit na patayong sumusukat ng layo mula sa Prime Meridian.</li><li><strong>Klima</strong> – karaniwang kalagayan ng panahon sa isang lugar sa mahabang panahon.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang Pilipinas ay malapit sa ekwador kaya tropikal ang klima nito: mainit at may tag-ulan at tag-araw.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ilan ang kontinente sa daigdig?</li><li>Ano ang sinusukat ng latitude?</li><li>Bakit tropikal ang klima ng Pilipinas?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pito</li><li>Layo mula sa ekwador</li><li>Dahil malapit ito sa ekwador.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-AP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Heograpiya ng Daigdig', 'Ang mga katangiang pisikal ng mundo at kung paano ito nakaaapekto sa tao.', '<p>Upang maunawaan ang kasaysayan ng daigdig, kailangan munang kilalanin ang mundong pinangyarihan nito.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Kontinente</strong> – malaking masa ng lupa; may pito sa daigdig.</li><li><strong>Karagatan</strong> – malaking anyong-tubig; may lima sa daigdig.</li><li><strong>Latitude</strong> – guhit na pahalang na sumusukat ng layo mula sa ekwador.</li><li><strong>Longitude</strong> – guhit na patayong sumusukat ng layo mula sa Prime Meridian.</li><li><strong>Klima</strong> – karaniwang kalagayan ng panahon sa isang lugar sa mahabang panahon.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang Pilipinas ay malapit sa ekwador kaya tropikal ang klima nito: mainit at may tag-ulan at tag-araw.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ilan ang kontinente sa daigdig?</li><li>Ano ang sinusukat ng latitude?</li><li>Bakit tropikal ang klima ng Pilipinas?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pito</li><li>Layo mula sa ekwador</li><li>Dahil malapit ito sa ekwador.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Mga Sinaunang Kabihasnan', m.description = 'Ang mga unang kabihasnang umusbong sa daigdig.', m.content = '<p>Ang mga unang kabihasnan ay nagsimula malapit sa mga ilog kung saan may tubig at matabang lupa.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Kabihasnan</strong> – maunlad na pamumuhay na may pamahalaan, relihiyon, sistema ng pagsulat, at lungsod.</li><li><strong>Mesopotamia</strong> – &quot;lupain sa pagitan ng dalawang ilog,&quot; ang Tigris at Euphrates.</li><li><strong>Ehipto</strong> – kabihasnang umusbong sa tabi ng Ilog Nile; kilala sa mga piramide.</li><li><strong>Gresya</strong> – pinagmulan ng demokrasya at pilosopiya.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang Ilog Nile ay bumabaha taon-taon at nag-iiwan ng matabang lupa, kaya naging masagana ang pagsasaka ng mga Ehipsiyo.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang kabihasnan?</li><li>Saan umusbong ang kabihasnang Ehipto?</li><li>Ano ang naging ambag ng Gresya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Maunlad na pamumuhay na may pamahalaan, relihiyon, pagsulat, at lungsod.</li><li>Sa tabi ng Ilog Nile</li><li>Demokrasya at pilosopiya</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-AP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Mga Sinaunang Kabihasnan', 'Ang mga unang kabihasnang umusbong sa daigdig.', '<p>Ang mga unang kabihasnan ay nagsimula malapit sa mga ilog kung saan may tubig at matabang lupa.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Kabihasnan</strong> – maunlad na pamumuhay na may pamahalaan, relihiyon, sistema ng pagsulat, at lungsod.</li><li><strong>Mesopotamia</strong> – &quot;lupain sa pagitan ng dalawang ilog,&quot; ang Tigris at Euphrates.</li><li><strong>Ehipto</strong> – kabihasnang umusbong sa tabi ng Ilog Nile; kilala sa mga piramide.</li><li><strong>Gresya</strong> – pinagmulan ng demokrasya at pilosopiya.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang Ilog Nile ay bumabaha taon-taon at nag-iiwan ng matabang lupa, kaya naging masagana ang pagsasaka ng mga Ehipsiyo.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang kabihasnan?</li><li>Saan umusbong ang kabihasnang Ehipto?</li><li>Ano ang naging ambag ng Gresya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Maunlad na pamumuhay na may pamahalaan, relihiyon, pagsulat, at lungsod.</li><li>Sa tabi ng Ilog Nile</li><li>Demokrasya at pilosopiya</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS8-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Ang Pamilya', m.description = 'Ang pinakaunang paaralan ng pagmamahal at pagpapahalaga.', m.content = '<p>Sa pamilya tayo unang natututong magmahal, gumalang, at magtulungan.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Pamilya</strong> – ang pinakamaliit at pinakapangunahing yunit ng lipunan.</li><li><strong>Pagpapahalaga</strong> – mga paniniwalang itinuturing na mahalaga, gaya ng katapatan at paggalang.</li><li><strong>Tungkulin</strong> – mga gawaing inaasahan sa bawat kasapi ng pamilya.</li></ul><h3>Halimbawa</h3><blockquote><p>Tinuturuan ng magulang ang anak na magsabi ng &quot;po&quot; at &quot;opo.&quot; Ang anak naman ay tumutulong sa gawaing-bahay bilang kanyang tungkulin.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang pamilya?</li><li>Magbigay ng isang pagpapahalagang natutunan sa pamilya.</li><li>Ano ang isang tungkulin ng anak sa pamilya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang pinakamaliit at pinakapangunahing yunit ng lipunan.</li><li>Halimbawa: paggalang, katapatan, pagtutulungan</li><li>Halimbawa: tumulong sa gawaing-bahay, mag-aral nang mabuti</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-ESP' AND m.module_number = 1 AND m.updated_by IS NULL;
