SELECT c.id, 1, 'Ang Pamilya', 'Ang pinakaunang paaralan ng pagmamahal at pagpapahalaga.', '<p>Sa pamilya tayo unang natututong magmahal, gumalang, at magtulungan.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Pamilya</strong> – ang pinakamaliit at pinakapangunahing yunit ng lipunan.</li><li><strong>Pagpapahalaga</strong> – mga paniniwalang itinuturing na mahalaga, gaya ng katapatan at paggalang.</li><li><strong>Tungkulin</strong> – mga gawaing inaasahan sa bawat kasapi ng pamilya.</li></ul><h3>Halimbawa</h3><blockquote><p>Tinuturuan ng magulang ang anak na magsabi ng &quot;po&quot; at &quot;opo.&quot; Ang anak naman ay tumutulong sa gawaing-bahay bilang kanyang tungkulin.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang pamilya?</li><li>Magbigay ng isang pagpapahalagang natutunan sa pamilya.</li><li>Ano ang isang tungkulin ng anak sa pamilya?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang pinakamaliit at pinakapangunahing yunit ng lipunan.</li><li>Halimbawa: paggalang, katapatan, pagtutulungan</li><li>Halimbawa: tumulong sa gawaing-bahay, mag-aral nang mabuti</li></ol></details>', 1 FROM courses c
