UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Komunikasyon sa Pamilya', m.description = 'Ang maayos na pag-uusap bilang susi sa matatag na pamilya.', m.content = '<p>Maraming hindi pagkakaunawaan sa pamilya ang naiiwasan kung maayos ang pag-uusap.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Komunikasyon</strong> – pagpapalitan ng mensahe, ideya, at damdamin.</li><li><strong>Aktibong pakikinig</strong> – pakikinig nang buong atensyon at pag-unawa.</li><li><strong>Pasalitang komunikasyon</strong> – gamit ang salita.</li><li><strong>Di-pasalitang komunikasyon</strong> – gamit ang kilos, ekspresyon ng mukha, at tono.</li></ul><h3>Halimbawa</h3><blockquote><p>Sa halip na sumigaw kapag naiinis, mahinahong sinabi ni Ben sa kanyang kapatid: &quot;Nalulungkot ako kapag ginagamit mo ang gamit ko nang hindi nagpapaalam.&quot;</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang komunikasyon?</li><li>Ano ang aktibong pakikinig?</li><li>Magbigay ng halimbawa ng di-pasalitang komunikasyon.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pagpapalitan ng mensahe, ideya, at damdamin.</li><li>Pakikinig nang buong atensyon at pag-unawa.</li><li>Halimbawa: pagngiti, pagsimangot, pagtango</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS8-ESP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Komunikasyon sa Pamilya', 'Ang maayos na pag-uusap bilang susi sa matatag na pamilya.', '<p>Maraming hindi pagkakaunawaan sa pamilya ang naiiwasan kung maayos ang pag-uusap.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Komunikasyon</strong> – pagpapalitan ng mensahe, ideya, at damdamin.</li><li><strong>Aktibong pakikinig</strong> – pakikinig nang buong atensyon at pag-unawa.</li><li><strong>Pasalitang komunikasyon</strong> – gamit ang salita.</li><li><strong>Di-pasalitang komunikasyon</strong> – gamit ang kilos, ekspresyon ng mukha, at tono.</li></ul><h3>Halimbawa</h3><blockquote><p>Sa halip na sumigaw kapag naiinis, mahinahong sinabi ni Ben sa kanyang kapatid: &quot;Nalulungkot ako kapag ginagamit mo ang gamit ko nang hindi nagpapaalam.&quot;</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang komunikasyon?</li><li>Ano ang aktibong pakikinig?</li><li>Magbigay ng halimbawa ng di-pasalitang komunikasyon.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pagpapalitan ng mensahe, ideya, at damdamin.</li><li>Pakikinig nang buong atensyon at pag-unawa.</li><li>Halimbawa: pagngiti, pagsimangot, pagtango</li></ol></details>', 1 FROM courses c
