UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Panitikang Asyano', m.description = 'Mga akdang pampanitikan mula sa iba''t ibang bansa sa Asya.', m.content = '<p>Ang mga bansa sa Asya ay may kani-kaniyang panitikan na nagpapakita ng kanilang kultura at pinahahalagahan.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Panitikang Asyano</strong> – mga akdang pampanitikan mula sa mga bansa sa Asya.</li><li><strong>Tanka</strong> – tulang Hapon na may limang taludtod at 31 pantig (5-7-5-7-7).</li><li><strong>Haiku</strong> – tulang Hapon na may tatlong taludtod at 17 pantig (5-7-5).</li><li><strong>Sanaysay</strong> – akdang naglalahad ng sariling kuro-kuro o pananaw.</li></ul><h3>Halimbawa</h3><blockquote><p><strong>Halimbawa ng haiku</strong></p><p>&quot;Ulan sa bubong / Ang pusa&#x27;y natutulog / Hintay ang araw.&quot; Mayroon itong 5, 7, at 5 na pantig.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ilang pantig mayroon ang haiku?</li><li>Saang bansa nagmula ang tanka at haiku?</li><li>Ano ang sanaysay?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>17 (5-7-5)</li><li>Japan (Hapon)</li><li>Akdang naglalahad ng sariling kuro-kuro o pananaw.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-FIL' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Panitikang Asyano', 'Mga akdang pampanitikan mula sa iba''t ibang bansa sa Asya.', '<p>Ang mga bansa sa Asya ay may kani-kaniyang panitikan na nagpapakita ng kanilang kultura at pinahahalagahan.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Panitikang Asyano</strong> – mga akdang pampanitikan mula sa mga bansa sa Asya.</li><li><strong>Tanka</strong> – tulang Hapon na may limang taludtod at 31 pantig (5-7-5-7-7).</li><li><strong>Haiku</strong> – tulang Hapon na may tatlong taludtod at 17 pantig (5-7-5).</li><li><strong>Sanaysay</strong> – akdang naglalahad ng sariling kuro-kuro o pananaw.</li></ul><h3>Halimbawa</h3><blockquote><p><strong>Halimbawa ng haiku</strong></p><p>&quot;Ulan sa bubong / Ang pusa&#x27;y natutulog / Hintay ang araw.&quot; Mayroon itong 5, 7, at 5 na pantig.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ilang pantig mayroon ang haiku?</li><li>Saang bansa nagmula ang tanka at haiku?</li><li>Ano ang sanaysay?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>17 (5-7-5)</li><li>Japan (Hapon)</li><li>Akdang naglalahad ng sariling kuro-kuro o pananaw.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Noli Me Tangere: Kaligiran ng Akda', m.description = 'Ang unang nobela ni Rizal at ang layunin nito.', m.content = '<p>Isinulat ni Dr. Jose Rizal ang Noli Me Tangere upang ipakita ang kalagayan ng Pilipinas sa ilalim ng Espanya.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Noli Me Tangere</strong> – unang nobela ni Rizal, nalathala noong 1887 sa Berlin, Alemanya.</li><li><strong>Kahulugan ng pamagat</strong> – salitang Latin na nangangahulugang &quot;Huwag Mo Akong Salingin.&quot;</li><li><strong>Nobela</strong> – mahabang akdang piksiyon na may maraming kabanata at tauhan.</li><li><strong>Kanser ng lipunan</strong> – tawag ni Rizal sa mga suliranin at pang-aabuso sa lipunan.</li></ul><h3>Halimbawa</h3><blockquote><p>Inialay ni Rizal ang nobela sa Inang Bayan. Naging inspirasyon niya ang nobelang Uncle Tom&#x27;s Cabin, na naglantad ng pang-aalipin sa Amerika.</p></blockquote><h3>Pagsusulit</h3><ol><li>Kailan nalathala ang Noli Me Tangere?</li><li>Ano ang ibig sabihin ng &quot;Noli Me Tangere&quot;?</li><li>Kanino inialay ni Rizal ang nobela?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>1887</li><li>Huwag Mo Akong Salingin</li><li>Sa Inang Bayan</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-FIL' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Noli Me Tangere: Kaligiran ng Akda', 'Ang unang nobela ni Rizal at ang layunin nito.', '<p>Isinulat ni Dr. Jose Rizal ang Noli Me Tangere upang ipakita ang kalagayan ng Pilipinas sa ilalim ng Espanya.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Noli Me Tangere</strong> – unang nobela ni Rizal, nalathala noong 1887 sa Berlin, Alemanya.</li><li><strong>Kahulugan ng pamagat</strong> – salitang Latin na nangangahulugang &quot;Huwag Mo Akong Salingin.&quot;</li><li><strong>Nobela</strong> – mahabang akdang piksiyon na may maraming kabanata at tauhan.</li><li><strong>Kanser ng lipunan</strong> – tawag ni Rizal sa mga suliranin at pang-aabuso sa lipunan.</li></ul><h3>Halimbawa</h3><blockquote><p>Inialay ni Rizal ang nobela sa Inang Bayan. Naging inspirasyon niya ang nobelang Uncle Tom&#x27;s Cabin, na naglantad ng pang-aalipin sa Amerika.</p></blockquote><h3>Pagsusulit</h3><ol><li>Kailan nalathala ang Noli Me Tangere?</li><li>Ano ang ibig sabihin ng &quot;Noli Me Tangere&quot;?</li><li>Kanino inialay ni Rizal ang nobela?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>1887</li><li>Huwag Mo Akong Salingin</li><li>Sa Inang Bayan</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Anglo-American Literature', m.description = 'Works from Britain and the United States.', m.content = '<p>Many famous poems, plays, and stories in English come from Britain and America.</p><h3>Key terms</h3><ul><li><strong>Anglo-American literature</strong> – literature from Britain (Anglo) and the United States (American).</li><li><strong>Poetry</strong> – writing that uses rhythm, imagery, and sound to express ideas and feelings.</li><li><strong>Sonnet</strong> – a poem of 14 lines, often about love.</li><li><strong>Short story</strong> – a brief work of fiction that can be read in one sitting.</li></ul><h3>Example</h3><blockquote><p>William Shakespeare wrote many sonnets and plays. Robert Frost, an American poet, wrote &quot;The Road Not Taken,&quot; about making choices in life.</p></blockquote><h3>Quick check</h3><ol><li>What does &quot;Anglo&quot; refer to?</li><li>How many lines does a sonnet have?</li><li>Who wrote &quot;The Road Not Taken&quot;?</li></ol><details><summary>Show answers</summary><ol><li>Britain or England</li><li>14</li><li>Robert Frost</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-ENGLISH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Anglo-American Literature', 'Works from Britain and the United States.', '<p>Many famous poems, plays, and stories in English come from Britain and America.</p><h3>Key terms</h3><ul><li><strong>Anglo-American literature</strong> – literature from Britain (Anglo) and the United States (American).</li><li><strong>Poetry</strong> – writing that uses rhythm, imagery, and sound to express ideas and feelings.</li><li><strong>Sonnet</strong> – a poem of 14 lines, often about love.</li><li><strong>Short story</strong> – a brief work of fiction that can be read in one sitting.</li></ul><h3>Example</h3><blockquote><p>William Shakespeare wrote many sonnets and plays. Robert Frost, an American poet, wrote &quot;The Road Not Taken,&quot; about making choices in life.</p></blockquote><h3>Quick check</h3><ol><li>What does &quot;Anglo&quot; refer to?</li><li>How many lines does a sonnet have?</li><li>Who wrote &quot;The Road Not Taken&quot;?</li></ol><details><summary>Show answers</summary><ol><li>Britain or England</li><li>14</li><li>Robert Frost</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Elements of Drama', m.description = 'The parts that make up a play.', m.content = '<p>A drama, or play, is a story written to be acted out on stage.</p><h3>Key terms</h3><ul><li><strong>Drama</strong> – a story told through dialogue and action, meant to be performed.</li><li><strong>Dialogue</strong> – the words spoken by the characters.</li><li><strong>Stage directions</strong> – notes that tell actors how to move or speak.</li><li><strong>Act and scene</strong> – the main parts (acts) and smaller parts (scenes) of a play.</li><li><strong>Conflict</strong> – the problem or struggle in the story.</li></ul><h3>Example</h3><blockquote><p>MARIA (looking out the window): &quot;Is it still raining?&quot; — The words in parentheses are stage directions; the line after the colon is dialogue.</p></blockquote><h3>Quick check</h3><ol><li>What is dialogue?</li><li>What do stage directions tell actors?</li><li>What is the conflict in a story?</li></ol><details><summary>Show answers</summary><ol><li>The words spoken by the characters.</li><li>How to move or speak.</li><li>The problem or struggle.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-ENGLISH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Elements of Drama', 'The parts that make up a play.', '<p>A drama, or play, is a story written to be acted out on stage.</p><h3>Key terms</h3><ul><li><strong>Drama</strong> – a story told through dialogue and action, meant to be performed.</li><li><strong>Dialogue</strong> – the words spoken by the characters.</li><li><strong>Stage directions</strong> – notes that tell actors how to move or speak.</li><li><strong>Act and scene</strong> – the main parts (acts) and smaller parts (scenes) of a play.</li><li><strong>Conflict</strong> – the problem or struggle in the story.</li></ul><h3>Example</h3><blockquote><p>MARIA (looking out the window): &quot;Is it still raining?&quot; — The words in parentheses are stage directions; the line after the colon is dialogue.</p></blockquote><h3>Quick check</h3><ol><li>What is dialogue?</li><li>What do stage directions tell actors?</li><li>What is the conflict in a story?</li></ol><details><summary>Show answers</summary><ol><li>The words spoken by the characters.</li><li>How to move or speak.</li><li>The problem or struggle.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Quadratic Equations', m.description = 'Equations where the highest power of the variable is 2.', m.content = '<p>When a ball is thrown or a garden&#x27;s area is computed, quadratic equations often appear.</p><h3>Key terms</h3><ul><li><strong>Quadratic equation</strong> – an equation in the form ax² + bx + c = 0, where a ≠ 0.</li><li><strong>Roots</strong> – the values of x that make the equation true.</li><li><strong>Factoring method</strong> – solving by writing the equation as a product equal to zero.</li><li><strong>Quadratic formula</strong> – x = [−b ± √(b² − 4ac)] / 2a.</li></ul><h3>Example</h3><blockquote><p>Solve x² − 5x + 6 = 0. Factor: (x − 2)(x − 3) = 0. So x = 2 or x = 3.</p></blockquote><h3>Quick check</h3><ol><li>Is x² + 3x − 4 = 0 a quadratic equation?</li><li>Solve x² − 9 = 0.</li><li>In 2x² + 3x − 5 = 0, what are a, b, and c?</li></ol><details><summary>Show answers</summary><ol><li>Yes</li><li>x = 3 or x = −3</li><li>a = 2, b = 3, c = −5</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-MATH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Quadratic Equations', 'Equations where the highest power of the variable is 2.', '<p>When a ball is thrown or a garden&#x27;s area is computed, quadratic equations often appear.</p><h3>Key terms</h3><ul><li><strong>Quadratic equation</strong> – an equation in the form ax² + bx + c = 0, where a ≠ 0.</li><li><strong>Roots</strong> – the values of x that make the equation true.</li><li><strong>Factoring method</strong> – solving by writing the equation as a product equal to zero.</li><li><strong>Quadratic formula</strong> – x = [−b ± √(b² − 4ac)] / 2a.</li></ul><h3>Example</h3><blockquote><p>Solve x² − 5x + 6 = 0. Factor: (x − 2)(x − 3) = 0. So x = 2 or x = 3.</p></blockquote><h3>Quick check</h3><ol><li>Is x² + 3x − 4 = 0 a quadratic equation?</li><li>Solve x² − 9 = 0.</li><li>In 2x² + 3x − 5 = 0, what are a, b, and c?</li></ol><details><summary>Show answers</summary><ol><li>Yes</li><li>x = 3 or x = −3</li><li>a = 2, b = 3, c = −5</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Quadratic Functions', m.description = 'Functions whose graph is a parabola.', m.content = '<p>The path of a basketball shot forms a curve called a parabola, which is the graph of a quadratic function.</p><p>If a is positive, the parabola opens upward. If a is negative, it opens downward.</p><h3>Key terms</h3><ul><li><strong>Quadratic function</strong> – a function in the form y = ax² + bx + c, where a ≠ 0.</li><li><strong>Parabola</strong> – the U-shaped graph of a quadratic function.</li><li><strong>Vertex</strong> – the highest or lowest point of the parabola.</li><li><strong>Axis of symmetry</strong> – the vertical line through the vertex that divides the parabola into two equal halves.</li></ul><h3>Example</h3><blockquote><p>y = x² opens upward and its vertex is (0, 0). y = −x² + 4 opens downward and its vertex is (0, 4).</p></blockquote><h3>Quick check</h3><ol><li>What is the graph of a quadratic function called?</li><li>Does y = −2x² open upward or downward?</li><li>What is the vertex of y = x² + 3?</li></ol><details><summary>Show answers</summary><ol><li>Parabola</li><li>Downward</li><li>(0, 3)</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-MATH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Quadratic Functions', 'Functions whose graph is a parabola.', '<p>The path of a basketball shot forms a curve called a parabola, which is the graph of a quadratic function.</p><p>If a is positive, the parabola opens upward. If a is negative, it opens downward.</p><h3>Key terms</h3><ul><li><strong>Quadratic function</strong> – a function in the form y = ax² + bx + c, where a ≠ 0.</li><li><strong>Parabola</strong> – the U-shaped graph of a quadratic function.</li><li><strong>Vertex</strong> – the highest or lowest point of the parabola.</li><li><strong>Axis of symmetry</strong> – the vertical line through the vertex that divides the parabola into two equal halves.</li></ul><h3>Example</h3><blockquote><p>y = x² opens upward and its vertex is (0, 0). y = −x² + 4 opens downward and its vertex is (0, 4).</p></blockquote><h3>Quick check</h3><ol><li>What is the graph of a quadratic function called?</li><li>Does y = −2x² open upward or downward?</li><li>What is the vertex of y = x² + 3?</li></ol><details><summary>Show answers</summary><ol><li>Parabola</li><li>Downward</li><li>(0, 3)</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Respiratory and Circulatory Systems', m.description = 'How the body takes in oxygen and moves blood.', m.content = '<p>Every cell in your body needs oxygen. Two body systems work together to deliver it.</p><h3>Key terms</h3><ul><li><strong>Respiratory system</strong> – takes in oxygen and releases carbon dioxide; includes the nose, trachea, and lungs.</li><li><strong>Circulatory system</strong> – moves blood around the body; includes the heart, blood, and blood vessels.</li><li><strong>Alveoli</strong> – tiny air sacs in the lungs where oxygen enters the blood.</li><li><strong>Arteries and veins</strong> – arteries carry blood away from the heart; veins carry blood back to the heart.</li></ul><h3>Example</h3><blockquote><p>When you run, you breathe faster to take in more oxygen, and your heart beats faster to deliver it to your muscles.</p></blockquote><h3>Quick check</h3><ol><li>Where does oxygen enter the blood?</li><li>What do arteries do?</li><li>Why does your heart beat faster when you exercise?</li></ol><details><summary>Show answers</summary><ol><li>In the alveoli of the lungs</li><li>Carry blood away from the heart.</li><li>To deliver more oxygen to the muscles.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-SCI' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Respiratory and Circulatory Systems', 'How the body takes in oxygen and moves blood.', '<p>Every cell in your body needs oxygen. Two body systems work together to deliver it.</p><h3>Key terms</h3><ul><li><strong>Respiratory system</strong> – takes in oxygen and releases carbon dioxide; includes the nose, trachea, and lungs.</li><li><strong>Circulatory system</strong> – moves blood around the body; includes the heart, blood, and blood vessels.</li><li><strong>Alveoli</strong> – tiny air sacs in the lungs where oxygen enters the blood.</li><li><strong>Arteries and veins</strong> – arteries carry blood away from the heart; veins carry blood back to the heart.</li></ul><h3>Example</h3><blockquote><p>When you run, you breathe faster to take in more oxygen, and your heart beats faster to deliver it to your muscles.</p></blockquote><h3>Quick check</h3><ol><li>Where does oxygen enter the blood?</li><li>What do arteries do?</li><li>Why does your heart beat faster when you exercise?</li></ol><details><summary>Show answers</summary><ol><li>In the alveoli of the lungs</li><li>Carry blood away from the heart.</li><li>To deliver more oxygen to the muscles.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Heredity', m.description = 'How traits are passed from parents to children.', m.content = '<p>You may have your mother&#x27;s eyes or your father&#x27;s height. These traits are passed on through heredity.</p><h3>Key terms</h3><ul><li><strong>Heredity</strong> – the passing of traits from parents to offspring.</li><li><strong>Gene</strong> – a part of DNA that carries a trait.</li><li><strong>Dominant trait</strong> – a trait that shows even if only one parent passes it.</li><li><strong>Recessive trait</strong> – a trait that shows only if both parents pass it.</li><li><strong>Gregor Mendel</strong> – known as the &quot;Father of Genetics&quot; for his experiments with pea plants.</li></ul><h3>Example</h3><blockquote><p>T = tall (dominant), t = short (recessive). A plant with Tt is tall. Only a plant with tt is short.</p></blockquote><h3>Quick check</h3><ol><li>What is heredity?</li><li>Who is the Father of Genetics?</li><li>Is a plant with Tt tall or short?</li></ol><details><summary>Show answers</summary><ol><li>The passing of traits from parents to offspring.</li><li>Gregor Mendel</li><li>Tall</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-SCI' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Heredity', 'How traits are passed from parents to children.', '<p>You may have your mother&#x27;s eyes or your father&#x27;s height. These traits are passed on through heredity.</p><h3>Key terms</h3><ul><li><strong>Heredity</strong> – the passing of traits from parents to offspring.</li><li><strong>Gene</strong> – a part of DNA that carries a trait.</li><li><strong>Dominant trait</strong> – a trait that shows even if only one parent passes it.</li><li><strong>Recessive trait</strong> – a trait that shows only if both parents pass it.</li><li><strong>Gregor Mendel</strong> – known as the &quot;Father of Genetics&quot; for his experiments with pea plants.</li></ul><h3>Example</h3><blockquote><p>T = tall (dominant), t = short (recessive). A plant with Tt is tall. Only a plant with tt is short.</p></blockquote><h3>Quick check</h3><ol><li>What is heredity?</li><li>Who is the Father of Genetics?</li><li>Is a plant with Tt tall or short?</li></ol><details><summary>Show answers</summary><ol><li>The passing of traits from parents to offspring.</li><li>Gregor Mendel</li><li>Tall</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Kahulugan ng Ekonomiks', m.description = 'Ang pag-aaral ng matalinong paggamit ng limitadong yaman.', m.content = '<p>Hindi lahat ng gusto natin ay makukuha natin. Dito pumapasok ang ekonomiks.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Ekonomiks</strong> – pag-aaral kung paano ginagamit ang limitadong yaman upang matugunan ang pangangailangan ng tao.</li><li><strong>Kakapusan</strong> – kakulangan ng yaman kumpara sa walang hanggang pangangailangan.</li><li><strong>Opportunity cost</strong> – ang halaga ng bagay na isinakripisyo kapalit ng pinili.</li><li><strong>Trade-off</strong> – pagpili ng isang bagay kapalit ng iba.</li></ul><h3>Halimbawa</h3><blockquote><p>May ₱100 si Carlo. Pinili niyang bumili ng libro kaysa manood ng sine. Ang opportunity cost ay ang panonood ng sine.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang ekonomiks?</li><li>Ano ang pangunahing suliranin ng ekonomiks?</li><li>Ano ang opportunity cost?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pag-aaral kung paano ginagamit ang limitadong yaman.</li><li>Kakapusan</li><li>Ang halaga ng bagay na isinakripisyo kapalit ng pinili.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-AP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Kahulugan ng Ekonomiks', 'Ang pag-aaral ng matalinong paggamit ng limitadong yaman.', '<p>Hindi lahat ng gusto natin ay makukuha natin. Dito pumapasok ang ekonomiks.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Ekonomiks</strong> – pag-aaral kung paano ginagamit ang limitadong yaman upang matugunan ang pangangailangan ng tao.</li><li><strong>Kakapusan</strong> – kakulangan ng yaman kumpara sa walang hanggang pangangailangan.</li><li><strong>Opportunity cost</strong> – ang halaga ng bagay na isinakripisyo kapalit ng pinili.</li><li><strong>Trade-off</strong> – pagpili ng isang bagay kapalit ng iba.</li></ul><h3>Halimbawa</h3><blockquote><p>May ₱100 si Carlo. Pinili niyang bumili ng libro kaysa manood ng sine. Ang opportunity cost ay ang panonood ng sine.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang ekonomiks?</li><li>Ano ang pangunahing suliranin ng ekonomiks?</li><li>Ano ang opportunity cost?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pag-aaral kung paano ginagamit ang limitadong yaman.</li><li>Kakapusan</li><li>Ang halaga ng bagay na isinakripisyo kapalit ng pinili.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Pangangailangan at Kagustuhan', m.description = 'Ang pagkakaiba ng kailangan at ng gusto lamang.', m.content = '<p>Mahalagang matutong pumili sa pagitan ng kailangan at gusto upang hindi masayang ang pera.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Pangangailangan</strong> – mga bagay na kailangan upang mabuhay, gaya ng pagkain, tubig, damit, at tirahan.</li><li><strong>Kagustuhan</strong> – mga bagay na nagbibigay-ginhawa ngunit hindi kailangan upang mabuhay.</li><li><strong>Hirarkiya ng Pangangailangan</strong> – teorya ni Abraham Maslow na nag-aayos ng pangangailangan mula pinakamahalaga.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang bigas ay pangangailangan. Ang bagong cellphone kahit gumagana pa ang luma ay kagustuhan.</p></blockquote><h3>Pagsusulit</h3><ol><li>Magbigay ng isang pangangailangan.</li><li>Ano ang kagustuhan?</li><li>Sino ang bumuo ng Hirarkiya ng Pangangailangan?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Halimbawa: pagkain, tubig, damit, tirahan</li><li>Mga bagay na nagbibigay-ginhawa ngunit hindi kailangan upang mabuhay.</li><li>Abraham Maslow</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-AP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Pangangailangan at Kagustuhan', 'Ang pagkakaiba ng kailangan at ng gusto lamang.', '<p>Mahalagang matutong pumili sa pagitan ng kailangan at gusto upang hindi masayang ang pera.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Pangangailangan</strong> – mga bagay na kailangan upang mabuhay, gaya ng pagkain, tubig, damit, at tirahan.</li><li><strong>Kagustuhan</strong> – mga bagay na nagbibigay-ginhawa ngunit hindi kailangan upang mabuhay.</li><li><strong>Hirarkiya ng Pangangailangan</strong> – teorya ni Abraham Maslow na nag-aayos ng pangangailangan mula pinakamahalaga.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang bigas ay pangangailangan. Ang bagong cellphone kahit gumagana pa ang luma ay kagustuhan.</p></blockquote><h3>Pagsusulit</h3><ol><li>Magbigay ng isang pangangailangan.</li><li>Ano ang kagustuhan?</li><li>Sino ang bumuo ng Hirarkiya ng Pangangailangan?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Halimbawa: pagkain, tubig, damit, tirahan</li><li>Mga bagay na nagbibigay-ginhawa ngunit hindi kailangan upang mabuhay.</li><li>Abraham Maslow</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Lipunan at Kabutihang Panlahat', m.description = 'Ang layunin ng lipunan at ang kabutihang para sa lahat.', m.content = '<p>Hindi tayo nabubuhay nang mag-isa. Kasapi tayo ng lipunan na may iisang layunin.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Lipunan</strong> – pangkat ng mga taong may iisang layunin at magkakaugnay.</li><li><strong>Kabutihang panlahat</strong> – kabutihang nakatutulong sa lahat ng kasapi ng lipunan.</li><li><strong>Pakikilahok</strong> – aktibong pagsali sa gawain ng komunidad.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang paglilinis ng barangay tuwing Sabado ay nakatutulong sa kalusugan ng lahat, hindi lang ng iilan.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang lipunan?</li><li>Ano ang kabutihang panlahat?</li><li>Magbigay ng isang paraan ng pakikilahok sa komunidad.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pangkat ng mga taong may iisang layunin at magkakaugnay.</li><li>Kabutihang nakatutulong sa lahat ng kasapi ng lipunan.</li><li>Halimbawa: clean-up drive, pagboboluntaryo</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-ESP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Lipunan at Kabutihang Panlahat', 'Ang layunin ng lipunan at ang kabutihang para sa lahat.', '<p>Hindi tayo nabubuhay nang mag-isa. Kasapi tayo ng lipunan na may iisang layunin.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Lipunan</strong> – pangkat ng mga taong may iisang layunin at magkakaugnay.</li><li><strong>Kabutihang panlahat</strong> – kabutihang nakatutulong sa lahat ng kasapi ng lipunan.</li><li><strong>Pakikilahok</strong> – aktibong pagsali sa gawain ng komunidad.</li></ul><h3>Halimbawa</h3><blockquote><p>Ang paglilinis ng barangay tuwing Sabado ay nakatutulong sa kalusugan ng lahat, hindi lang ng iilan.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang lipunan?</li><li>Ano ang kabutihang panlahat?</li><li>Magbigay ng isang paraan ng pakikilahok sa komunidad.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Pangkat ng mga taong may iisang layunin at magkakaugnay.</li><li>Kabutihang nakatutulong sa lahat ng kasapi ng lipunan.</li><li>Halimbawa: clean-up drive, pagboboluntaryo</li></ol></details>', 1 FROM courses c
