UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Karapatan at Tungkulin', m.description = 'Ang bawat karapatan ay may kaakibat na tungkulin.', m.content = '<p>Bilang tao at mamamayan, may mga karapatan tayo. Ngunit kasama nito ang mga tungkuling dapat gampanan.</p><h3>Mahahalagang Kahulugan</h3><ul><li><strong>Karapatan</strong> – kapangyarihang moral na gawin o tamasahin ang isang bagay.</li><li><strong>Tungkulin</strong> – obligasyong moral na dapat gawin.</li><li><strong>Paggalang</strong> – pagkilala sa karapatan ng iba.</li></ul><h3>Halimbawa</h3><blockquote><p>Karapatan ng mag-aaral na matuto; tungkulin niyang mag-aral nang mabuti at igalang ang guro at kaklase.</p></blockquote><h3>Pagsusulit</h3><ol><li>Ano ang karapatan?</li><li>Ano ang kaakibat ng bawat karapatan?</li><li>Kung karapatan mo ang malayang pagpapahayag, ano ang iyong tungkulin?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Kapangyarihang moral na gawin o tamasahin ang isang bagay.</li><li>Tungkulin</li><li>Magsalita nang may katotohanan at paggalang.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-ESP' AND m.module_number = 2 AND m.updated_by IS NULL;
