WHERE c.course_code = 'HS9-ESP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Music of the Medieval to Classical Periods', m.description = 'How Western music developed over time.', m.content = '<p>Western music changed a lot from the songs of medieval churches to the symphonies of the Classical period.</p><h3>Key terms</h3><ul><li><strong>Medieval period</strong> – the time of Gregorian chant, simple religious songs sung in unison.</li><li><strong>Renaissance</strong> – music with richer harmony and many voice parts.</li><li><strong>Baroque period</strong> – music with lots of ornaments; composers include Bach and Vivaldi.</li><li><strong>Classical period</strong> – music with balance and clarity; composers include Mozart and Haydn.</li></ul><h3>Example</h3><blockquote><p>Vivaldi&#x27;s &quot;The Four Seasons&quot; (Baroque) describes spring, summer, autumn, and winter through music.</p></blockquote><h3>Quick check</h3><ol><li>What is Gregorian chant?</li><li>Name a Baroque composer.</li><li>What is Classical music known for?</li></ol><details><summary>Show answers</summary><ol><li>Simple religious songs sung in unison in the Medieval period.</li><li>Any one: Bach, Vivaldi, Handel</li><li>Balance and clarity</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-MAPEH' AND m.module_number = 1 AND m.updated_by IS NULL;
