SELECT c.id, 1, 'Music of the Medieval to Classical Periods', 'How Western music developed over time.', '<p>Western music changed a lot from the songs of medieval churches to the symphonies of the Classical period.</p><h3>Key terms</h3><ul><li><strong>Medieval period</strong> – the time of Gregorian chant, simple religious songs sung in unison.</li><li><strong>Renaissance</strong> – music with richer harmony and many voice parts.</li><li><strong>Baroque period</strong> – music with lots of ornaments; composers include Bach and Vivaldi.</li><li><strong>Classical period</strong> – music with balance and clarity; composers include Mozart and Haydn.</li></ul><h3>Example</h3><blockquote><p>Vivaldi&#x27;s &quot;The Four Seasons&quot; (Baroque) describes spring, summer, autumn, and winter through music.</p></blockquote><h3>Quick check</h3><ol><li>What is Gregorian chant?</li><li>Name a Baroque composer.</li><li>What is Classical music known for?</li></ol><details><summary>Show answers</summary><ol><li>Simple religious songs sung in unison in the Medieval period.</li><li>Any one: Bach, Vivaldi, Handel</li><li>Balance and clarity</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-MAPEH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Western Classical Art', m.description = 'Major art periods from the Renaissance onward.', m.content = '<p>European art went through periods with different styles and goals.</p><h3>Key terms</h3><ul><li><strong>Renaissance art</strong> – realistic art that used perspective; artists include Leonardo da Vinci and Michelangelo.</li><li><strong>Perspective</strong> – a technique that makes a flat picture look three-dimensional.</li><li><strong>Baroque art</strong> – dramatic art with strong contrasts of light and dark.</li><li><strong>Fresco</strong> – painting on wet plaster on walls or ceilings.</li></ul><h3>Example</h3><blockquote><p>Michelangelo painted the ceiling of the Sistine Chapel as a fresco. Leonardo da Vinci painted the Mona Lisa.</p></blockquote><h3>Quick check</h3><ol><li>Who painted the Mona Lisa?</li><li>What is a fresco?</li><li>What does perspective do in a painting?</li></ol><details><summary>Show answers</summary><ol><li>Leonardo da Vinci</li><li>Painting on wet plaster on walls or ceilings.</li><li>Makes a flat picture look three-dimensional.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-MAPEH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Western Classical Art', 'Major art periods from the Renaissance onward.', '<p>European art went through periods with different styles and goals.</p><h3>Key terms</h3><ul><li><strong>Renaissance art</strong> – realistic art that used perspective; artists include Leonardo da Vinci and Michelangelo.</li><li><strong>Perspective</strong> – a technique that makes a flat picture look three-dimensional.</li><li><strong>Baroque art</strong> – dramatic art with strong contrasts of light and dark.</li><li><strong>Fresco</strong> – painting on wet plaster on walls or ceilings.</li></ul><h3>Example</h3><blockquote><p>Michelangelo painted the ceiling of the Sistine Chapel as a fresco. Leonardo da Vinci painted the Mona Lisa.</p></blockquote><h3>Quick check</h3><ol><li>Who painted the Mona Lisa?</li><li>What is a fresco?</li><li>What does perspective do in a painting?</li></ol><details><summary>Show answers</summary><ol><li>Leonardo da Vinci</li><li>Painting on wet plaster on walls or ceilings.</li><li>Makes a flat picture look three-dimensional.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-MAPEH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Choosing a TLE Specialization', m.description = 'Picking one skill area to study in depth.', m.content = '<p>In Grade 9, students focus on one TLE area to build deeper skills.</p><h3>Key terms</h3><ul><li><strong>Specialization</strong> – one area of TLE studied in depth, such as Cookery or Computer Systems Servicing.</li><li><strong>Competency</strong> – a skill a worker must be able to do.</li><li><strong>TESDA</strong> – Technical Education and Skills Development Authority, which sets skill standards.</li><li><strong>National Certificate (NC)</strong> – a TESDA certification showing a person has the required skills.</li></ul><h3>Example</h3><blockquote><p>A student who likes fixing computers chooses Computer Systems Servicing and later takes the NC II assessment.</p></blockquote><h3>Quick check</h3><ol><li>What does TESDA stand for?</li><li>What is a competency?</li><li>What does an NC show?</li></ol><details><summary>Show answers</summary><ol><li>Technical Education and Skills Development Authority</li><li>A skill a worker must be able to do.</li><li>That a person has the required skills.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-TLE' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Choosing a TLE Specialization', 'Picking one skill area to study in depth.', '<p>In Grade 9, students focus on one TLE area to build deeper skills.</p><h3>Key terms</h3><ul><li><strong>Specialization</strong> – one area of TLE studied in depth, such as Cookery or Computer Systems Servicing.</li><li><strong>Competency</strong> – a skill a worker must be able to do.</li><li><strong>TESDA</strong> – Technical Education and Skills Development Authority, which sets skill standards.</li><li><strong>National Certificate (NC)</strong> – a TESDA certification showing a person has the required skills.</li></ul><h3>Example</h3><blockquote><p>A student who likes fixing computers chooses Computer Systems Servicing and later takes the NC II assessment.</p></blockquote><h3>Quick check</h3><ol><li>What does TESDA stand for?</li><li>What is a competency?</li><li>What does an NC show?</li></ol><details><summary>Show answers</summary><ol><li>Technical Education and Skills Development Authority</li><li>A skill a worker must be able to do.</li><li>That a person has the required skills.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-TLE' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Occupational Health and Safety', m.description = 'Protecting workers from hazards at work.', m.content = '<p>Every job has risks. Occupational health and safety helps prevent injuries and illness.</p><h3>Key terms</h3><ul><li><strong>Occupational health and safety (OHS)</strong> – practices that protect workers&#x27; health and safety.</li><li><strong>Physical hazard</strong> – things like noise, heat, and sharp objects.</li><li><strong>Chemical hazard</strong> – harmful substances like cleaning chemicals.</li><li><strong>Ergonomic hazard</strong> – poor posture or repetitive movements that strain the body.</li></ul><h3>Example</h3><blockquote><p>A computer technician uses an anti-static wrist strap and sits with proper posture to avoid electrical and ergonomic hazards.</p></blockquote><h3>Quick check</h3><ol><li>What is OHS?</li><li>Give one example of a chemical hazard.</li><li>Bad posture while using a computer is what type of hazard?</li></ol><details><summary>Show answers</summary><ol><li>Practices that protect workers&#x27; health and safety.</li><li>Any one: cleaning chemicals, paint, pesticides</li><li>Ergonomic hazard</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS9-TLE' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Occupational Health and Safety', 'Protecting workers from hazards at work.', '<p>Every job has risks. Occupational health and safety helps prevent injuries and illness.</p><h3>Key terms</h3><ul><li><strong>Occupational health and safety (OHS)</strong> – practices that protect workers&#x27; health and safety.</li><li><strong>Physical hazard</strong> – things like noise, heat, and sharp objects.</li><li><strong>Chemical hazard</strong> – harmful substances like cleaning chemicals.</li><li><strong>Ergonomic hazard</strong> – poor posture or repetitive movements that strain the body.</li></ul><h3>Example</h3><blockquote><p>A computer technician uses an anti-static wrist strap and sits with proper posture to avoid electrical and ergonomic hazards.</p></blockquote><h3>Quick check</h3><ol><li>What is OHS?</li><li>Give one example of a chemical hazard.</li><li>Bad posture while using a computer is what type of hazard?</li></ol><details><summary>Show answers</summary><ol><li>Practices that protect workers&#x27; health and safety.</li><li>Any one: cleaning chemicals, paint, pesticides</li><li>Ergonomic hazard</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS9-TLE' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

