SET NAMES utf8mb4;

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Mitolohiya', m.description = 'Mga kuwento ng mga diyos at bayani na nagpapaliwanag sa pinagmulan ng daigdig.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag kung ano ang mitolohiya at ang layunin nito</li><li>Tukuyin ang mga elemento ng mitolohiya</li><li>Paghambingin ang mitolohiyang Griyego at mitolohiyang Pilipino</li></ul></blockquote><p>Bago pa umusbong ang agham, sinikap na ng mga sinaunang tao na ipaliwanag ang mga bagay na nakikita nila: bakit kumikidlat, saan nagmula ang tao, at bakit nagbabago ang panahon. Ang mga sagot nila ay isinalaysay sa anyo ng mga kuwento. Ito ang tinatawag nating <strong>mitolohiya</strong>.</p><h3>Ano ang mitolohiya?</h3><p>Ang mitolohiya ay kalipunan ng mga mito. Ang <strong>mito</strong> ay kuwentong may kinalaman sa mga diyos, diyosa, at bayani, at karaniwang nagpapaliwanag ng pinagmulan ng daigdig, ng tao, o ng mga pangyayari sa kalikasan. Itinuturing itong banal o totoo ng mga taong naniniwala rito noong unang panahon.</p><h3>Mga elemento ng mitolohiya</h3><ol><li><strong>Tauhan</strong> – mga diyos, diyosa, at bayaning may di-pangkaraniwang kapangyarihan.</li><li><strong>Tagpuan</strong> – karaniwang sinaunang panahon, sa langit, dagat, o ilalim ng lupa.</li><li><strong>Banghay</strong> – maaaring tungkol sa paglikha, pakikipagsapalaran, o parusa ng mga diyos.</li><li><strong>Tema</strong> – nagpapaliwanag ng pinagmulan ng isang bagay o nagtuturo ng aral tungkol sa ugali ng tao.</li></ol><h3>Mitolohiyang Griyego at Romano</h3><p>Ang mga Griyego ay may labindalawang pangunahing diyos na nakatira sa Bundok Olympus. Nang sakupin ng mga Romano ang Gresya, inangkin nila ang mga diyos na ito ngunit pinalitan ang pangalan.</p><table><thead><tr><th>Griyego</th><th>Romano</th><th>Kapangyarihan</th></tr></thead><tbody><tr><td>Zeus</td><td>Jupiter</td><td>Hari ng mga diyos, diyos ng langit at kidlat</td></tr><tr><td>Poseidon</td><td>Neptune</td><td>Diyos ng dagat</td></tr><tr><td>Hades</td><td>Pluto</td><td>Diyos ng ilalim ng lupa</td></tr><tr><td>Athena</td><td>Minerva</td><td>Diyosa ng karunungan</td></tr><tr><td>Aphrodite</td><td>Venus</td><td>Diyosa ng pag-ibig at kagandahan</td></tr></tbody></table><h3>Mitolohiyang Pilipino</h3><p>May sariling mitolohiya rin ang mga Pilipino bago pa dumating ang mga Espanyol. Sa mga Tagalog, si <strong>Bathala</strong> ang pinakamakapangyarihang diyos at lumikha ng daigdig. Kilala rin ang kuwento nina <strong>Malakas at Maganda</strong>, ang unang lalaki at babae na lumabas mula sa isang biyas ng kawayan.</p><blockquote><p><strong>Halimbawa ng pagsusuri</strong></p><p>Sa kuwento nina Malakas at Maganda, ipinapakita ang paniniwalang magkapantay ang babae at lalaki dahil sabay silang lumabas mula sa iisang kawayan. Ipinapaliwanag din nito ang pinagmulan ng tao gamit ang isang bagay na pamilyar sa mga Pilipino.</p></blockquote><h3>Bakit mahalaga ang mitolohiya?</h3><ul><li>Ipinapakita nito ang kultura at paniniwala ng sinaunang tao.</li><li>Pinagmulan ito ng maraming salita at simbolo ngayon, gaya ng "Achilles'' heel" at ng pangalan ng mga planeta.</li><li>Nagtuturo ito ng aral tungkol sa kayabangan, katapangan, at katapatan.</li></ul><h3>Gawain</h3><p>Pumili ng isang diyos o diyosa mula sa mitolohiyang Griyego at isang diyos mula sa mitolohiyang Pilipino. Gumawa ng maikling paghahambing (5–7 pangungusap) tungkol sa kanilang kapangyarihan at kung ano ang ipinapakita nito tungkol sa paniniwala ng mga taong lumikha ng kuwento.</p><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng mito at mitolohiya?</li><li>Ano ang Romanong pangalan ni Zeus?</li><li>Saan lumabas sina Malakas at Maganda?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang mito ay isang kuwento; ang mitolohiya ay kalipunan ng mga mito.</li><li>Jupiter</li><li>Sa isang biyas ng kawayan</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-FIL' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Mitolohiya', 'Mga kuwento ng mga diyos at bayani na nagpapaliwanag sa pinagmulan ng daigdig.', '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag kung ano ang mitolohiya at ang layunin nito</li><li>Tukuyin ang mga elemento ng mitolohiya</li><li>Paghambingin ang mitolohiyang Griyego at mitolohiyang Pilipino</li></ul></blockquote><p>Bago pa umusbong ang agham, sinikap na ng mga sinaunang tao na ipaliwanag ang mga bagay na nakikita nila: bakit kumikidlat, saan nagmula ang tao, at bakit nagbabago ang panahon. Ang mga sagot nila ay isinalaysay sa anyo ng mga kuwento. Ito ang tinatawag nating <strong>mitolohiya</strong>.</p><h3>Ano ang mitolohiya?</h3><p>Ang mitolohiya ay kalipunan ng mga mito. Ang <strong>mito</strong> ay kuwentong may kinalaman sa mga diyos, diyosa, at bayani, at karaniwang nagpapaliwanag ng pinagmulan ng daigdig, ng tao, o ng mga pangyayari sa kalikasan. Itinuturing itong banal o totoo ng mga taong naniniwala rito noong unang panahon.</p><h3>Mga elemento ng mitolohiya</h3><ol><li><strong>Tauhan</strong> – mga diyos, diyosa, at bayaning may di-pangkaraniwang kapangyarihan.</li><li><strong>Tagpuan</strong> – karaniwang sinaunang panahon, sa langit, dagat, o ilalim ng lupa.</li><li><strong>Banghay</strong> – maaaring tungkol sa paglikha, pakikipagsapalaran, o parusa ng mga diyos.</li><li><strong>Tema</strong> – nagpapaliwanag ng pinagmulan ng isang bagay o nagtuturo ng aral tungkol sa ugali ng tao.</li></ol><h3>Mitolohiyang Griyego at Romano</h3><p>Ang mga Griyego ay may labindalawang pangunahing diyos na nakatira sa Bundok Olympus. Nang sakupin ng mga Romano ang Gresya, inangkin nila ang mga diyos na ito ngunit pinalitan ang pangalan.</p><table><thead><tr><th>Griyego</th><th>Romano</th><th>Kapangyarihan</th></tr></thead><tbody><tr><td>Zeus</td><td>Jupiter</td><td>Hari ng mga diyos, diyos ng langit at kidlat</td></tr><tr><td>Poseidon</td><td>Neptune</td><td>Diyos ng dagat</td></tr><tr><td>Hades</td><td>Pluto</td><td>Diyos ng ilalim ng lupa</td></tr><tr><td>Athena</td><td>Minerva</td><td>Diyosa ng karunungan</td></tr><tr><td>Aphrodite</td><td>Venus</td><td>Diyosa ng pag-ibig at kagandahan</td></tr></tbody></table><h3>Mitolohiyang Pilipino</h3><p>May sariling mitolohiya rin ang mga Pilipino bago pa dumating ang mga Espanyol. Sa mga Tagalog, si <strong>Bathala</strong> ang pinakamakapangyarihang diyos at lumikha ng daigdig. Kilala rin ang kuwento nina <strong>Malakas at Maganda</strong>, ang unang lalaki at babae na lumabas mula sa isang biyas ng kawayan.</p><blockquote><p><strong>Halimbawa ng pagsusuri</strong></p><p>Sa kuwento nina Malakas at Maganda, ipinapakita ang paniniwalang magkapantay ang babae at lalaki dahil sabay silang lumabas mula sa iisang kawayan. Ipinapaliwanag din nito ang pinagmulan ng tao gamit ang isang bagay na pamilyar sa mga Pilipino.</p></blockquote><h3>Bakit mahalaga ang mitolohiya?</h3><ul><li>Ipinapakita nito ang kultura at paniniwala ng sinaunang tao.</li><li>Pinagmulan ito ng maraming salita at simbolo ngayon, gaya ng "Achilles'' heel" at ng pangalan ng mga planeta.</li><li>Nagtuturo ito ng aral tungkol sa kayabangan, katapangan, at katapatan.</li></ul><h3>Gawain</h3><p>Pumili ng isang diyos o diyosa mula sa mitolohiyang Griyego at isang diyos mula sa mitolohiyang Pilipino. Gumawa ng maikling paghahambing (5–7 pangungusap) tungkol sa kanilang kapangyarihan at kung ano ang ipinapakita nito tungkol sa paniniwala ng mga taong lumikha ng kuwento.</p><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng mito at mitolohiya?</li><li>Ano ang Romanong pangalan ni Zeus?</li><li>Saan lumabas sina Malakas at Maganda?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang mito ay isang kuwento; ang mitolohiya ay kalipunan ng mga mito.</li><li>Jupiter</li><li>Sa isang biyas ng kawayan</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Parabula', m.description = 'Maikling kuwentong may aral na naghahatid ng katotohanang moral sa pamamagitan ng paghahambing.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang katangian ng parabula</li><li>Tukuyin ang talinghaga at aral ng isang parabula</li><li>Iugnay ang aral ng parabula sa sariling karanasan</li></ul></blockquote><p>Kung minsan, mas madaling maintindihan ang isang aral kapag isinalaysay ito bilang kuwento. Ganito ang ginagawa ng <strong>parabula</strong>.</p><h3>Ano ang parabula?</h3><p>Ang parabula ay maikling salaysay na naghahatid ng <strong>aral na moral o espiritwal</strong>. Hango ito sa salitang Griyego na <em>parabole</em>, na nangangahulugang "paghahambing." Karaniwang hango ang mga kilalang parabula sa Bibliya.</p><h3>Mga katangian ng parabula</h3><ol><li><strong>Payak na kuwento</strong> – simple ang mga pangyayari at kakaunti ang tauhan.</li><li><strong>Tao ang tauhan</strong> – hindi tulad ng pabula na hayop ang tauhan.</li><li><strong>May talinghaga</strong> – may nakatagong kahulugan sa likod ng mga pangyayari.</li><li><strong>Malinaw na aral</strong> – nagtuturo kung paano dapat mamuhay ang tao.</li></ol><h3>Halimbawa: Ang Alibughang Anak</h3><blockquote><p>Hiningi ng bunsong anak ang kanyang mana sa ama at nilustay ito sa malayong lugar. Nang maubos ang pera at dumating ang taggutom, nag-alaga siya ng baboy at nagutom. Nagpasya siyang umuwi at humingi ng tawad. Sinalubong siya ng ama nang may yakap at handaan. Nagtampo ang panganay na anak, ngunit sinabi ng ama na dapat silang magsaya dahil "ang nawala ay natagpuan."</p></blockquote><table><thead><tr><th>Bahagi ng kuwento</th><th>Talinghaga (nakatagong kahulugan)</th></tr></thead><tbody><tr><td>Ang ama</td><td>Ang Diyos o ang mapagmahal na magulang</td></tr><tr><td>Ang bunsong anak</td><td>Taong nagkasala ngunit nagsisi</td></tr><tr><td>Ang handaan</td><td>Kagalakan sa pagbabalik-loob</td></tr><tr><td>Ang panganay na anak</td><td>Taong nahihirapang magpatawad</td></tr></tbody></table><h3>Paano suriin ang parabula</h3><ul><li>Alamin kung sino ang mga tauhan at ano ang ginawa nila.</li><li>Hanapin ang talinghaga: ano ang kinakatawan ng bawat tauhan o bagay?</li><li>Itanong: anong aral ang nais iparating ng kuwento?</li><li>Iugnay ang aral sa tunay na buhay.</li></ul><h3>Gawain</h3><p>Sumulat ng sariling maikling parabula (isang talata) na nagtuturo ng aral tungkol sa katapatan. Gumamit ng tauhang tao at tagpuang pamilyar sa iyo, gaya ng paaralan o palengke. Sa dulo, isulat sa isang pangungusap ang aral nito.</p><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng salitang Griyego na <em>parabole</em>?</li><li>Ano ang pagkakaiba ng parabula at pabula?</li><li>Sa "Alibughang Anak," ano ang aral tungkol sa pagpapatawad?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Paghahambing</li><li>Tao ang tauhan sa parabula; hayop ang tauhan sa pabula.</li><li>Dapat tanggapin at patawarin ang taong tunay na nagsisisi.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-FIL' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Parabula', 'Maikling kuwentong may aral na naghahatid ng katotohanang moral sa pamamagitan ng paghahambing.', '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang katangian ng parabula</li><li>Tukuyin ang talinghaga at aral ng isang parabula</li><li>Iugnay ang aral ng parabula sa sariling karanasan</li></ul></blockquote><p>Kung minsan, mas madaling maintindihan ang isang aral kapag isinalaysay ito bilang kuwento. Ganito ang ginagawa ng <strong>parabula</strong>.</p><h3>Ano ang parabula?</h3><p>Ang parabula ay maikling salaysay na naghahatid ng <strong>aral na moral o espiritwal</strong>. Hango ito sa salitang Griyego na <em>parabole</em>, na nangangahulugang "paghahambing." Karaniwang hango ang mga kilalang parabula sa Bibliya.</p><h3>Mga katangian ng parabula</h3><ol><li><strong>Payak na kuwento</strong> – simple ang mga pangyayari at kakaunti ang tauhan.</li><li><strong>Tao ang tauhan</strong> – hindi tulad ng pabula na hayop ang tauhan.</li><li><strong>May talinghaga</strong> – may nakatagong kahulugan sa likod ng mga pangyayari.</li><li><strong>Malinaw na aral</strong> – nagtuturo kung paano dapat mamuhay ang tao.</li></ol><h3>Halimbawa: Ang Alibughang Anak</h3><blockquote><p>Hiningi ng bunsong anak ang kanyang mana sa ama at nilustay ito sa malayong lugar. Nang maubos ang pera at dumating ang taggutom, nag-alaga siya ng baboy at nagutom. Nagpasya siyang umuwi at humingi ng tawad. Sinalubong siya ng ama nang may yakap at handaan. Nagtampo ang panganay na anak, ngunit sinabi ng ama na dapat silang magsaya dahil "ang nawala ay natagpuan."</p></blockquote><table><thead><tr><th>Bahagi ng kuwento</th><th>Talinghaga (nakatagong kahulugan)</th></tr></thead><tbody><tr><td>Ang ama</td><td>Ang Diyos o ang mapagmahal na magulang</td></tr><tr><td>Ang bunsong anak</td><td>Taong nagkasala ngunit nagsisi</td></tr><tr><td>Ang handaan</td><td>Kagalakan sa pagbabalik-loob</td></tr><tr><td>Ang panganay na anak</td><td>Taong nahihirapang magpatawad</td></tr></tbody></table><h3>Paano suriin ang parabula</h3><ul><li>Alamin kung sino ang mga tauhan at ano ang ginawa nila.</li><li>Hanapin ang talinghaga: ano ang kinakatawan ng bawat tauhan o bagay?</li><li>Itanong: anong aral ang nais iparating ng kuwento?</li><li>Iugnay ang aral sa tunay na buhay.</li></ul><h3>Gawain</h3><p>Sumulat ng sariling maikling parabula (isang talata) na nagtuturo ng aral tungkol sa katapatan. Gumamit ng tauhang tao at tagpuang pamilyar sa iyo, gaya ng paaralan o palengke. Sa dulo, isulat sa isang pangungusap ang aral nito.</p><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng salitang Griyego na <em>parabole</em>?</li><li>Ano ang pagkakaiba ng parabula at pabula?</li><li>Sa "Alibughang Anak," ano ang aral tungkol sa pagpapatawad?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Paghahambing</li><li>Tao ang tauhan sa parabula; hayop ang tauhan sa pabula.</li><li>Dapat tanggapin at patawarin ang taong tunay na nagsisisi.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-FIL' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Reading World Literature', m.description = 'How literature from many countries reveals shared human experiences.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Explain what world literature is and why we read it</li><li>Identify the theme of a literary work</li><li>Connect a work to its cultural and historical context</li></ul></blockquote><p>A story written centuries ago in Greece, Japan, or Nigeria can still make a Filipino student feel something today. That is the power of <strong>world literature</strong>: works from many cultures that speak to experiences all people share.</p><h3>What is world literature?</h3><p>World literature includes poems, stories, plays, and novels from different countries that are read beyond their place of origin, often in translation. Examples include Greek myths, the Japanese haiku, African folktales, and Latin American short stories.</p><h3>Finding the theme</h3><p>The <strong>theme</strong> is the central message or insight about life that a work expresses. It is not the topic. The topic is a word or phrase; the theme is a complete idea.</p><table><thead><tr><th>Topic</th><th>Possible theme</th></tr></thead><tbody><tr><td>Pride</td><td>Excessive pride can lead to a person''s downfall.</td></tr><tr><td>Family</td><td>Love within a family can survive great hardship.</td></tr><tr><td>Freedom</td><td>True freedom requires courage and sacrifice.</td></tr></tbody></table><blockquote><p><strong>Example</strong></p><p>In the Greek myth of Icarus, a boy flies too close to the sun with wings of wax and falls into the sea. Topic: ambition. Theme: ignoring wise advice out of overconfidence can lead to disaster.</p></blockquote><h3>Reading in context</h3><p>Every work comes from a specific time and culture. Knowing the context helps you understand choices the writer made.</p><ul><li><strong>Historical context</strong> – events happening when the work was written, such as war or colonization.</li><li><strong>Cultural context</strong> – beliefs, values, and customs of the people in the work.</li><li><strong>Author''s background</strong> – the writer''s own experiences that shaped the work.</li></ul><h3>Universal themes</h3><p>Some themes appear in literature everywhere: love, loss, courage, justice, identity, and the struggle between good and evil. When you notice the same theme in a Filipino story and a foreign one, you are seeing what connects all people.</p><h3>Activity</h3><p>Choose any story, myth, or poem from another country that you have read or heard. In one paragraph, state its topic, its theme as a complete sentence, and one detail from the work that supports the theme.</p><h3>Quick check</h3><ol><li>What is the difference between a topic and a theme?</li><li>Name two kinds of context that help readers understand a work.</li><li>Give one universal theme.</li></ol><details><summary>Show answers</summary><ol><li>A topic is a word or phrase; a theme is a complete statement about life.</li><li>Any two: historical, cultural, author''s background.</li><li>Any one: love, loss, courage, justice, identity, good versus evil.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-ENGLISH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Reading World Literature', 'How literature from many countries reveals shared human experiences.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Explain what world literature is and why we read it</li><li>Identify the theme of a literary work</li><li>Connect a work to its cultural and historical context</li></ul></blockquote><p>A story written centuries ago in Greece, Japan, or Nigeria can still make a Filipino student feel something today. That is the power of <strong>world literature</strong>: works from many cultures that speak to experiences all people share.</p><h3>What is world literature?</h3><p>World literature includes poems, stories, plays, and novels from different countries that are read beyond their place of origin, often in translation. Examples include Greek myths, the Japanese haiku, African folktales, and Latin American short stories.</p><h3>Finding the theme</h3><p>The <strong>theme</strong> is the central message or insight about life that a work expresses. It is not the topic. The topic is a word or phrase; the theme is a complete idea.</p><table><thead><tr><th>Topic</th><th>Possible theme</th></tr></thead><tbody><tr><td>Pride</td><td>Excessive pride can lead to a person''s downfall.</td></tr><tr><td>Family</td><td>Love within a family can survive great hardship.</td></tr><tr><td>Freedom</td><td>True freedom requires courage and sacrifice.</td></tr></tbody></table><blockquote><p><strong>Example</strong></p><p>In the Greek myth of Icarus, a boy flies too close to the sun with wings of wax and falls into the sea. Topic: ambition. Theme: ignoring wise advice out of overconfidence can lead to disaster.</p></blockquote><h3>Reading in context</h3><p>Every work comes from a specific time and culture. Knowing the context helps you understand choices the writer made.</p><ul><li><strong>Historical context</strong> – events happening when the work was written, such as war or colonization.</li><li><strong>Cultural context</strong> – beliefs, values, and customs of the people in the work.</li><li><strong>Author''s background</strong> – the writer''s own experiences that shaped the work.</li></ul><h3>Universal themes</h3><p>Some themes appear in literature everywhere: love, loss, courage, justice, identity, and the struggle between good and evil. When you notice the same theme in a Filipino story and a foreign one, you are seeing what connects all people.</p><h3>Activity</h3><p>Choose any story, myth, or poem from another country that you have read or heard. In one paragraph, state its topic, its theme as a complete sentence, and one detail from the work that supports the theme.</p><h3>Quick check</h3><ol><li>What is the difference between a topic and a theme?</li><li>Name two kinds of context that help readers understand a work.</li><li>Give one universal theme.</li></ol><details><summary>Show answers</summary><ol><li>A topic is a word or phrase; a theme is a complete statement about life.</li><li>Any two: historical, cultural, author''s background.</li><li>Any one: love, loss, courage, justice, identity, good versus evil.</li></ol></details>', 1 FROM courses c
