UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Writing an Argumentative Essay', m.description = 'Taking a clear position and supporting it with reasons and evidence.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Write a clear claim on an issue</li><li>Support the claim with reasons and evidence</li><li>Address the opposing view in a respectful way</li></ul></blockquote><p>When you convince your parents to extend your curfew or explain to a teacher why a deadline should move, you are arguing. An <strong>argumentative essay</strong> does the same thing in writing, using logic and evidence instead of emotion alone.</p><h3>Parts of an argument</h3><ol><li><strong>Claim</strong> – your position on the issue, stated in one clear sentence.</li><li><strong>Reasons</strong> – why you believe the claim is true.</li><li><strong>Evidence</strong> – facts, statistics, examples, or expert opinions that support each reason.</li><li><strong>Counterclaim</strong> – the opposing view.</li><li><strong>Rebuttal</strong> – your response showing why the opposing view is weaker.</li></ol><blockquote><p><strong>Example</strong></p><p><strong>Claim:</strong> Schools should allow students to use phones for learning during class.<br><strong>Reason:</strong> Phones give quick access to dictionaries, research, and learning apps.<br><strong>Evidence:</strong> A class survey shows most students use their phones to look up unfamiliar words.<br><strong>Counterclaim:</strong> Phones distract students from the lesson.<br><strong>Rebuttal:</strong> Clear rules, such as using phones only for assigned tasks, can reduce distraction while keeping the benefits.</p></blockquote><h3>Writing a strong claim</h3><ul><li>Take a side; avoid "maybe" or "it depends."</li><li>Make it debatable; facts like "Manila is the capital" are not arguments.</li><li>Keep it specific.</li></ul><table><thead><tr><th>Weak claim</th><th>Strong claim</th></tr></thead><tbody><tr><td>Uniforms have good and bad sides.</td><td>Public high schools should keep school uniforms to reduce pressure over clothing.</td></tr></tbody></table><h3>Essay structure</h3><ul><li><strong>Introduction</strong> – hook the reader, give background, state your claim.</li><li><strong>Body paragraphs</strong> – one reason per paragraph with evidence.</li><li><strong>Counterargument paragraph</strong> – present and answer the opposing view.</li><li><strong>Conclusion</strong> – restate the claim and leave a final thought or call to action.</li></ul><h3>Useful transitions</h3><p>To add a reason: <em>furthermore, in addition</em>. To give evidence: <em>for example, according to</em>. To address the other side: <em>some may argue, however</em>. To conclude: <em>therefore, in conclusion</em>.</p><h3>Activity</h3><p>Write a five-paragraph argumentative essay on this question: <em>Should senior high students be required to do community service?</em> Include a claim, two reasons with evidence, a counterclaim with rebuttal, and a conclusion.</p><h3>Quick check</h3><ol><li>What is a rebuttal?</li><li>Why is "Water boils at 100°C" not a good claim?</li><li>Give two transitions used to present evidence.</li></ol><details><summary>Show answers</summary><ol><li>Your response explaining why the opposing view is weaker.</li><li>It is a fact, not a debatable position.</li><li>Any two: for example, for instance, according to, research shows.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-ENGLISH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Writing an Argumentative Essay', 'Taking a clear position and supporting it with reasons and evidence.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Write a clear claim on an issue</li><li>Support the claim with reasons and evidence</li><li>Address the opposing view in a respectful way</li></ul></blockquote><p>When you convince your parents to extend your curfew or explain to a teacher why a deadline should move, you are arguing. An <strong>argumentative essay</strong> does the same thing in writing, using logic and evidence instead of emotion alone.</p><h3>Parts of an argument</h3><ol><li><strong>Claim</strong> – your position on the issue, stated in one clear sentence.</li><li><strong>Reasons</strong> – why you believe the claim is true.</li><li><strong>Evidence</strong> – facts, statistics, examples, or expert opinions that support each reason.</li><li><strong>Counterclaim</strong> – the opposing view.</li><li><strong>Rebuttal</strong> – your response showing why the opposing view is weaker.</li></ol><blockquote><p><strong>Example</strong></p><p><strong>Claim:</strong> Schools should allow students to use phones for learning during class.<br><strong>Reason:</strong> Phones give quick access to dictionaries, research, and learning apps.<br><strong>Evidence:</strong> A class survey shows most students use their phones to look up unfamiliar words.<br><strong>Counterclaim:</strong> Phones distract students from the lesson.<br><strong>Rebuttal:</strong> Clear rules, such as using phones only for assigned tasks, can reduce distraction while keeping the benefits.</p></blockquote><h3>Writing a strong claim</h3><ul><li>Take a side; avoid "maybe" or "it depends."</li><li>Make it debatable; facts like "Manila is the capital" are not arguments.</li><li>Keep it specific.</li></ul><table><thead><tr><th>Weak claim</th><th>Strong claim</th></tr></thead><tbody><tr><td>Uniforms have good and bad sides.</td><td>Public high schools should keep school uniforms to reduce pressure over clothing.</td></tr></tbody></table><h3>Essay structure</h3><ul><li><strong>Introduction</strong> – hook the reader, give background, state your claim.</li><li><strong>Body paragraphs</strong> – one reason per paragraph with evidence.</li><li><strong>Counterargument paragraph</strong> – present and answer the opposing view.</li><li><strong>Conclusion</strong> – restate the claim and leave a final thought or call to action.</li></ul><h3>Useful transitions</h3><p>To add a reason: <em>furthermore, in addition</em>. To give evidence: <em>for example, according to</em>. To address the other side: <em>some may argue, however</em>. To conclude: <em>therefore, in conclusion</em>.</p><h3>Activity</h3><p>Write a five-paragraph argumentative essay on this question: <em>Should senior high students be required to do community service?</em> Include a claim, two reasons with evidence, a counterclaim with rebuttal, and a conclusion.</p><h3>Quick check</h3><ol><li>What is a rebuttal?</li><li>Why is "Water boils at 100°C" not a good claim?</li><li>Give two transitions used to present evidence.</li></ol><details><summary>Show answers</summary><ol><li>Your response explaining why the opposing view is weaker.</li><li>It is a fact, not a debatable position.</li><li>Any two: for example, for instance, according to, research shows.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-ENGLISH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Arithmetic Sequences and Series', m.description = 'Patterns that grow by adding the same number each time, and how to find their sums.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify an arithmetic sequence and its common difference</li><li>Find any term using the nth-term formula</li><li>Find the sum of the first n terms</li></ul></blockquote><p>If you save ₱20 on the first day, ₱25 on the second, ₱30 on the third, and so on, your daily savings form a pattern. Patterns like this are called <strong>sequences</strong>.</p><h3>What is an arithmetic sequence?</h3><p>An <strong>arithmetic sequence</strong> is a list of numbers where the same number is added to get the next term. That number is the <strong>common difference</strong>, <em>d</em>.</p><blockquote><p><strong>Example 1</strong></p><p>3, 7, 11, 15, … has d = 7 − 3 = 4. It is arithmetic.<br>2, 4, 8, 16, … is not arithmetic, because 4 − 2 = 2 but 8 − 4 = 4.</p></blockquote><h3>Finding the nth term</h3><p>Formula: <strong>aₙ = a₁ + (n − 1)d</strong>, where a₁ is the first term, n is the term number, and d is the common difference.</p><blockquote><p><strong>Example 2</strong></p><p>Find the 20th term of 5, 8, 11, 14, …<br>a₁ = 5, d = 3, n = 20<br>a₂₀ = 5 + (20 − 1)(3) = 5 + 57 = <strong>62</strong></p></blockquote><blockquote><p><strong>Example 3</strong></p><p>Which term of 4, 10, 16, … is 100?<br>100 = 4 + (n − 1)(6) → 96 = 6(n − 1) → n − 1 = 16 → <strong>n = 17</strong></p></blockquote><h3>Arithmetic series</h3><p>A <strong>series</strong> is the sum of the terms. The sum of the first n terms is:</p><p><strong>Sₙ = n/2 (a₁ + aₙ)</strong> &nbsp;or&nbsp; <strong>Sₙ = n/2 [2a₁ + (n − 1)d]</strong></p><blockquote><p><strong>Example 4</strong></p><p>Back to the savings: ₱20, ₱25, ₱30, … How much is saved in 30 days?<br>a₁ = 20, d = 5, n = 30<br>S₃₀ = 30/2 [2(20) + (29)(5)] = 15 [40 + 145] = 15(185) = <strong>₱2,775</strong></p></blockquote><h3>Common mistakes</h3><ul><li>Using n instead of (n − 1) in the nth-term formula.</li><li>Getting d backwards: always subtract a term from the term after it.</li><li>Forgetting that d can be negative, as in 50, 46, 42, … where d = −4.</li></ul><h3>Activity</h3><p>A theater has 18 seats in the first row, and each row after has 3 more seats than the row before. There are 25 rows. Find the number of seats in the last row and the total number of seats.</p><h3>Quick check</h3><ol><li>Find d in 12, 9, 6, 3, …</li><li>Find the 15th term of 2, 9, 16, …</li><li>Find the sum of the first 10 terms of 1, 4, 7, …</li></ol><details><summary>Show answers</summary><ol><li>d = −3</li><li>a₁₅ = 2 + 14(7) = 100</li><li>S₁₀ = 5 [2 + 27] = 145</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-MATH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Arithmetic Sequences and Series', 'Patterns that grow by adding the same number each time, and how to find their sums.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify an arithmetic sequence and its common difference</li><li>Find any term using the nth-term formula</li><li>Find the sum of the first n terms</li></ul></blockquote><p>If you save ₱20 on the first day, ₱25 on the second, ₱30 on the third, and so on, your daily savings form a pattern. Patterns like this are called <strong>sequences</strong>.</p><h3>What is an arithmetic sequence?</h3><p>An <strong>arithmetic sequence</strong> is a list of numbers where the same number is added to get the next term. That number is the <strong>common difference</strong>, <em>d</em>.</p><blockquote><p><strong>Example 1</strong></p><p>3, 7, 11, 15, … has d = 7 − 3 = 4. It is arithmetic.<br>2, 4, 8, 16, … is not arithmetic, because 4 − 2 = 2 but 8 − 4 = 4.</p></blockquote><h3>Finding the nth term</h3><p>Formula: <strong>aₙ = a₁ + (n − 1)d</strong>, where a₁ is the first term, n is the term number, and d is the common difference.</p><blockquote><p><strong>Example 2</strong></p><p>Find the 20th term of 5, 8, 11, 14, …<br>a₁ = 5, d = 3, n = 20<br>a₂₀ = 5 + (20 − 1)(3) = 5 + 57 = <strong>62</strong></p></blockquote><blockquote><p><strong>Example 3</strong></p><p>Which term of 4, 10, 16, … is 100?<br>100 = 4 + (n − 1)(6) → 96 = 6(n − 1) → n − 1 = 16 → <strong>n = 17</strong></p></blockquote><h3>Arithmetic series</h3><p>A <strong>series</strong> is the sum of the terms. The sum of the first n terms is:</p><p><strong>Sₙ = n/2 (a₁ + aₙ)</strong> &nbsp;or&nbsp; <strong>Sₙ = n/2 [2a₁ + (n − 1)d]</strong></p><blockquote><p><strong>Example 4</strong></p><p>Back to the savings: ₱20, ₱25, ₱30, … How much is saved in 30 days?<br>a₁ = 20, d = 5, n = 30<br>S₃₀ = 30/2 [2(20) + (29)(5)] = 15 [40 + 145] = 15(185) = <strong>₱2,775</strong></p></blockquote><h3>Common mistakes</h3><ul><li>Using n instead of (n − 1) in the nth-term formula.</li><li>Getting d backwards: always subtract a term from the term after it.</li><li>Forgetting that d can be negative, as in 50, 46, 42, … where d = −4.</li></ul><h3>Activity</h3><p>A theater has 18 seats in the first row, and each row after has 3 more seats than the row before. There are 25 rows. Find the number of seats in the last row and the total number of seats.</p><h3>Quick check</h3><ol><li>Find d in 12, 9, 6, 3, …</li><li>Find the 15th term of 2, 9, 16, …</li><li>Find the sum of the first 10 terms of 1, 4, 7, …</li></ol><details><summary>Show answers</summary><ol><li>d = −3</li><li>a₁₅ = 2 + 14(7) = 100</li><li>S₁₀ = 5 [2 + 27] = 145</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Geometric Sequences and Series', m.description = 'Patterns that grow by multiplying by the same number, and their sums.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify a geometric sequence and its common ratio</li><li>Find any term using the nth-term formula</li><li>Find the sum of a finite geometric series</li></ul></blockquote><p>When a video gets shared by 3 people, and each of them shares it with 3 more, the number of viewers grows very quickly: 1, 3, 9, 27, 81. This kind of growth is <strong>geometric</strong>.</p><h3>What is a geometric sequence?</h3><p>A <strong>geometric sequence</strong> is a list where each term is found by <strong>multiplying</strong> the previous term by the same number, called the <strong>common ratio</strong>, <em>r</em>.</p><blockquote><p><strong>Example 1</strong></p><p>5, 10, 20, 40, … has r = 10 ÷ 5 = 2.<br>81, 27, 9, 3, … has r = 27 ÷ 81 = 1/3.</p></blockquote><table><thead><tr><th>Arithmetic</th><th>Geometric</th></tr></thead><tbody><tr><td>Add the same number (d)</td><td>Multiply by the same number (r)</td></tr><tr><td>d = a₂ − a₁</td><td>r = a₂ ÷ a₁</td></tr><tr><td>Grows steadily</td><td>Grows or shrinks quickly</td></tr></tbody></table><h3>Finding the nth term</h3><p>Formula: <strong>aₙ = a₁ · rⁿ⁻¹</strong></p><blockquote><p><strong>Example 2</strong></p><p>Find the 8th term of 3, 6, 12, …<br>a₁ = 3, r = 2, n = 8<br>a₈ = 3 · 2⁷ = 3 · 128 = <strong>384</strong></p></blockquote><h3>Geometric series</h3><p>The sum of the first n terms (when r ≠ 1) is: <strong>Sₙ = a₁(1 − rⁿ) / (1 − r)</strong></p><blockquote><p><strong>Example 3</strong></p><p>Find the sum of the first 6 terms of 2, 6, 18, …<br>a₁ = 2, r = 3, n = 6<br>S₆ = 2(1 − 3⁶) / (1 − 3) = 2(1 − 729) / (−2) = 2(−728) / (−2) = <strong>728</strong></p></blockquote><h3>Real-life uses</h3><ul><li>Population growth and the spread of information</li><li>Depreciation, where a gadget loses a fixed percent of its value each year</li><li>Compound interest on savings</li></ul><blockquote><p><strong>Example 4</strong></p><p>A laptop worth ₱40,000 loses 20% of its value each year, so it keeps 80% (r = 0.8). Its value after 3 years is 40,000 · (0.8)³ = 40,000 · 0.512 = <strong>₱20,480</strong>.</p></blockquote><h3>Activity</h3><p>A bacteria culture starts with 50 bacteria and doubles every hour. Make a table of the number of bacteria for hours 0 to 6, then use the formula to find how many there are after 10 hours.</p><h3>Quick check</h3><ol><li>Find r in 64, 16, 4, 1, …</li><li>Find the 6th term of 2, 10, 50, …</li><li>Find the sum of the first 5 terms of 1, 2, 4, …</li></ol><details><summary>Show answers</summary><ol><li>r = 1/4</li><li>a₆ = 2 · 5⁵ = 6,250</li><li>S₅ = (1 − 2⁵)/(1 − 2) = 31</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-MATH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Geometric Sequences and Series', 'Patterns that grow by multiplying by the same number, and their sums.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify a geometric sequence and its common ratio</li><li>Find any term using the nth-term formula</li><li>Find the sum of a finite geometric series</li></ul></blockquote><p>When a video gets shared by 3 people, and each of them shares it with 3 more, the number of viewers grows very quickly: 1, 3, 9, 27, 81. This kind of growth is <strong>geometric</strong>.</p><h3>What is a geometric sequence?</h3><p>A <strong>geometric sequence</strong> is a list where each term is found by <strong>multiplying</strong> the previous term by the same number, called the <strong>common ratio</strong>, <em>r</em>.</p><blockquote><p><strong>Example 1</strong></p><p>5, 10, 20, 40, … has r = 10 ÷ 5 = 2.<br>81, 27, 9, 3, … has r = 27 ÷ 81 = 1/3.</p></blockquote><table><thead><tr><th>Arithmetic</th><th>Geometric</th></tr></thead><tbody><tr><td>Add the same number (d)</td><td>Multiply by the same number (r)</td></tr><tr><td>d = a₂ − a₁</td><td>r = a₂ ÷ a₁</td></tr><tr><td>Grows steadily</td><td>Grows or shrinks quickly</td></tr></tbody></table><h3>Finding the nth term</h3><p>Formula: <strong>aₙ = a₁ · rⁿ⁻¹</strong></p><blockquote><p><strong>Example 2</strong></p><p>Find the 8th term of 3, 6, 12, …<br>a₁ = 3, r = 2, n = 8<br>a₈ = 3 · 2⁷ = 3 · 128 = <strong>384</strong></p></blockquote><h3>Geometric series</h3><p>The sum of the first n terms (when r ≠ 1) is: <strong>Sₙ = a₁(1 − rⁿ) / (1 − r)</strong></p><blockquote><p><strong>Example 3</strong></p><p>Find the sum of the first 6 terms of 2, 6, 18, …<br>a₁ = 2, r = 3, n = 6<br>S₆ = 2(1 − 3⁶) / (1 − 3) = 2(1 − 729) / (−2) = 2(−728) / (−2) = <strong>728</strong></p></blockquote><h3>Real-life uses</h3><ul><li>Population growth and the spread of information</li><li>Depreciation, where a gadget loses a fixed percent of its value each year</li><li>Compound interest on savings</li></ul><blockquote><p><strong>Example 4</strong></p><p>A laptop worth ₱40,000 loses 20% of its value each year, so it keeps 80% (r = 0.8). Its value after 3 years is 40,000 · (0.8)³ = 40,000 · 0.512 = <strong>₱20,480</strong>.</p></blockquote><h3>Activity</h3><p>A bacteria culture starts with 50 bacteria and doubles every hour. Make a table of the number of bacteria for hours 0 to 6, then use the formula to find how many there are after 10 hours.</p><h3>Quick check</h3><ol><li>Find r in 64, 16, 4, 1, …</li><li>Find the 6th term of 2, 10, 50, …</li><li>Find the sum of the first 5 terms of 1, 2, 4, …</li></ol><details><summary>Show answers</summary><ol><li>r = 1/4</li><li>a₆ = 2 · 5⁵ = 6,250</li><li>S₅ = (1 − 2⁵)/(1 − 2) = 31</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-MATH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Plate Tectonics', m.description = 'Earth''s outer layer is made of moving plates, and how they move shapes the planet.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Describe the layers of the Earth</li><li>Explain what tectonic plates are and why they move</li><li>Identify the three types of plate boundaries</li></ul></blockquote><p>The ground beneath you feels still, but it is moving a few centimeters every year, about as fast as your fingernails grow. This slow movement explains earthquakes, volcanoes, and mountains.</p><h3>Layers of the Earth</h3><table><thead><tr><th>Layer</th><th>Description</th></tr></thead><tbody><tr><td>Crust</td><td>Thin, solid outer layer; continental crust is thicker, oceanic crust is denser</td></tr><tr><td>Mantle</td><td>Thick layer of hot rock; the upper part can flow very slowly</td></tr><tr><td>Outer core</td><td>Liquid iron and nickel; its movement creates Earth''s magnetic field</td></tr><tr><td>Inner core</td><td>Solid iron and nickel under extreme pressure</td></tr></tbody></table><p>The crust and the uppermost mantle together form the rigid <strong>lithosphere</strong>, which floats on the softer, flowing <strong>asthenosphere</strong>.</p><h3>What are tectonic plates?</h3><p>The lithosphere is broken into large pieces called <strong>tectonic plates</strong>. Major plates include the Pacific, Eurasian, and Indo-Australian plates. The Philippines sits on the <strong>Philippine Sea Plate</strong> and the <strong>Sunda Plate</strong>, near where several plates meet.</p><h3>Why do plates move?</h3><p>Heat from deep inside the Earth causes <strong>convection currents</strong> in the mantle. Hot rock rises, cools, and sinks again, slowly dragging the plates above it, like objects on top of boiling soup.</p><h3>Types of plate boundaries</h3><ol><li><strong>Divergent</strong> – plates move apart. Magma rises and forms new crust.
<blockquote><p>Example: the Mid-Atlantic Ridge.</p></blockquote></li><li><strong>Convergent</strong> – plates move toward each other. One plate may sink under another (subduction), or both may crumple upward.
<blockquote><p>Example: the Philippine Trench, where the Philippine Sea Plate sinks beneath the Philippine Mobile Belt.</p></blockquote></li><li><strong>Transform</strong> – plates slide past each other sideways.
<blockquote><p>Example: the San Andreas Fault in California.</p></blockquote></li></ol><h3>Evidence for moving plates</h3><ul><li>The coastlines of South America and Africa fit together like puzzle pieces.</li><li>Matching fossils are found on continents now separated by oceans.</li><li>Earthquakes and volcanoes cluster along plate edges.</li></ul><h3>Activity</h3><p>Draw a simple diagram of each type of plate boundary using arrows to show plate movement. Under each drawing, write one landform or event that forms there.</p><h3>Quick check</h3><ol><li>What is the lithosphere made of?</li><li>What causes plates to move?</li><li>What type of boundary forms the Philippine Trench?</li></ol><details><summary>Show answers</summary><ol><li>The crust and the uppermost mantle</li><li>Convection currents in the mantle</li><li>Convergent</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-SCI' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Plate Tectonics', 'Earth''s outer layer is made of moving plates, and how they move shapes the planet.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Describe the layers of the Earth</li><li>Explain what tectonic plates are and why they move</li><li>Identify the three types of plate boundaries</li></ul></blockquote><p>The ground beneath you feels still, but it is moving a few centimeters every year, about as fast as your fingernails grow. This slow movement explains earthquakes, volcanoes, and mountains.</p><h3>Layers of the Earth</h3><table><thead><tr><th>Layer</th><th>Description</th></tr></thead><tbody><tr><td>Crust</td><td>Thin, solid outer layer; continental crust is thicker, oceanic crust is denser</td></tr><tr><td>Mantle</td><td>Thick layer of hot rock; the upper part can flow very slowly</td></tr><tr><td>Outer core</td><td>Liquid iron and nickel; its movement creates Earth''s magnetic field</td></tr><tr><td>Inner core</td><td>Solid iron and nickel under extreme pressure</td></tr></tbody></table><p>The crust and the uppermost mantle together form the rigid <strong>lithosphere</strong>, which floats on the softer, flowing <strong>asthenosphere</strong>.</p><h3>What are tectonic plates?</h3><p>The lithosphere is broken into large pieces called <strong>tectonic plates</strong>. Major plates include the Pacific, Eurasian, and Indo-Australian plates. The Philippines sits on the <strong>Philippine Sea Plate</strong> and the <strong>Sunda Plate</strong>, near where several plates meet.</p><h3>Why do plates move?</h3><p>Heat from deep inside the Earth causes <strong>convection currents</strong> in the mantle. Hot rock rises, cools, and sinks again, slowly dragging the plates above it, like objects on top of boiling soup.</p><h3>Types of plate boundaries</h3><ol><li><strong>Divergent</strong> – plates move apart. Magma rises and forms new crust.
<blockquote><p>Example: the Mid-Atlantic Ridge.</p></blockquote></li><li><strong>Convergent</strong> – plates move toward each other. One plate may sink under another (subduction), or both may crumple upward.
<blockquote><p>Example: the Philippine Trench, where the Philippine Sea Plate sinks beneath the Philippine Mobile Belt.</p></blockquote></li><li><strong>Transform</strong> – plates slide past each other sideways.
<blockquote><p>Example: the San Andreas Fault in California.</p></blockquote></li></ol><h3>Evidence for moving plates</h3><ul><li>The coastlines of South America and Africa fit together like puzzle pieces.</li><li>Matching fossils are found on continents now separated by oceans.</li><li>Earthquakes and volcanoes cluster along plate edges.</li></ul><h3>Activity</h3><p>Draw a simple diagram of each type of plate boundary using arrows to show plate movement. Under each drawing, write one landform or event that forms there.</p><h3>Quick check</h3><ol><li>What is the lithosphere made of?</li><li>What causes plates to move?</li><li>What type of boundary forms the Philippine Trench?</li></ol><details><summary>Show answers</summary><ol><li>The crust and the uppermost mantle</li><li>Convection currents in the mantle</li><li>Convergent</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Earthquakes, Volcanoes, and Mountains', m.description = 'What happens where plates meet, and why the Philippines experiences these events.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Explain how plate movement causes earthquakes, volcanoes, and mountains</li><li>Describe the Pacific Ring of Fire</li><li>Explain why the Philippines has many earthquakes and volcanoes</li></ul></blockquote><p>In the last module you learned that plates move. When they push, pull, and grind against each other, energy and molten rock build up. The results are some of the most powerful events on Earth.</p><h3>Earthquakes</h3><p>Rocks along plate boundaries get stuck while the plates keep moving. Stress builds until the rocks suddenly slip along a <strong>fault</strong>, releasing energy as seismic waves.</p><ul><li><strong>Focus</strong> – the point underground where the slip starts.</li><li><strong>Epicenter</strong> – the point on the surface directly above the focus.</li><li><strong>Magnitude</strong> – the energy released, measured by instruments.</li><li><strong>Intensity</strong> – the effects felt by people and buildings at a location.</li></ul><blockquote><p><strong>Example</strong></p><p>The Philippine Fault Zone runs about 1,200 km through the country. Movement along it has caused strong earthquakes, including the 1990 Luzon earthquake.</p></blockquote><h3>Volcanoes</h3><p>At convergent boundaries where one plate sinks under another, the sinking plate melts deep in the mantle. The magma rises through the crust and erupts, forming <strong>volcanoes</strong>.</p><table><thead><tr><th>Volcano</th><th>Notable fact</th></tr></thead><tbody><tr><td>Mayon (Albay)</td><td>Known for its near-perfect cone; one of the most active in the country</td></tr><tr><td>Taal (Batangas)</td><td>A volcano island in the middle of Taal Lake</td></tr><tr><td>Pinatubo (Zambales)</td><td>Its 1991 eruption was one of the largest of the 20th century</td></tr></tbody></table><h3>Mountains</h3><p>When two continental plates collide, neither sinks easily, so the crust crumples and folds upward to form mountain ranges.</p><blockquote><p><strong>Example</strong></p><p>The Himalayas, home of Mount Everest, formed when the Indian Plate collided with the Eurasian Plate, and they are still rising today.</p></blockquote><h3>The Pacific Ring of Fire</h3><p>The <strong>Ring of Fire</strong> is a horseshoe-shaped belt around the Pacific Ocean where many plates meet. Most of the world''s earthquakes and active volcanoes occur here. The Philippines lies along this belt, which is why we experience frequent earthquakes and have many active volcanoes.</p><h3>Staying safe</h3><ul><li>During an earthquake: Duck, Cover, and Hold.</li><li>Know your community''s evacuation routes for volcanic eruptions.</li><li>Follow PHIVOLCS for official earthquake and volcano bulletins.</li></ul><h3>Activity</h3><p>Make a table with three columns: earthquake, volcano, and mountain range. For each, write the type of plate boundary where it usually forms and one real example from the Philippines or the world.</p><h3>Quick check</h3><ol><li>What is the difference between the focus and the epicenter?</li><li>How do volcanoes form at convergent boundaries?</li><li>Why does the Philippines have many earthquakes?</li></ol><details><summary>Show answers</summary><ol><li>The focus is underground where the slip starts; the epicenter is on the surface directly above it.</li><li>A sinking plate melts, and the magma rises and erupts.</li><li>It lies on the Pacific Ring of Fire, where plates meet.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-SCI' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Earthquakes, Volcanoes, and Mountains', 'What happens where plates meet, and why the Philippines experiences these events.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Explain how plate movement causes earthquakes, volcanoes, and mountains</li><li>Describe the Pacific Ring of Fire</li><li>Explain why the Philippines has many earthquakes and volcanoes</li></ul></blockquote><p>In the last module you learned that plates move. When they push, pull, and grind against each other, energy and molten rock build up. The results are some of the most powerful events on Earth.</p><h3>Earthquakes</h3><p>Rocks along plate boundaries get stuck while the plates keep moving. Stress builds until the rocks suddenly slip along a <strong>fault</strong>, releasing energy as seismic waves.</p><ul><li><strong>Focus</strong> – the point underground where the slip starts.</li><li><strong>Epicenter</strong> – the point on the surface directly above the focus.</li><li><strong>Magnitude</strong> – the energy released, measured by instruments.</li><li><strong>Intensity</strong> – the effects felt by people and buildings at a location.</li></ul><blockquote><p><strong>Example</strong></p><p>The Philippine Fault Zone runs about 1,200 km through the country. Movement along it has caused strong earthquakes, including the 1990 Luzon earthquake.</p></blockquote><h3>Volcanoes</h3><p>At convergent boundaries where one plate sinks under another, the sinking plate melts deep in the mantle. The magma rises through the crust and erupts, forming <strong>volcanoes</strong>.</p><table><thead><tr><th>Volcano</th><th>Notable fact</th></tr></thead><tbody><tr><td>Mayon (Albay)</td><td>Known for its near-perfect cone; one of the most active in the country</td></tr><tr><td>Taal (Batangas)</td><td>A volcano island in the middle of Taal Lake</td></tr><tr><td>Pinatubo (Zambales)</td><td>Its 1991 eruption was one of the largest of the 20th century</td></tr></tbody></table><h3>Mountains</h3><p>When two continental plates collide, neither sinks easily, so the crust crumples and folds upward to form mountain ranges.</p><blockquote><p><strong>Example</strong></p><p>The Himalayas, home of Mount Everest, formed when the Indian Plate collided with the Eurasian Plate, and they are still rising today.</p></blockquote><h3>The Pacific Ring of Fire</h3><p>The <strong>Ring of Fire</strong> is a horseshoe-shaped belt around the Pacific Ocean where many plates meet. Most of the world''s earthquakes and active volcanoes occur here. The Philippines lies along this belt, which is why we experience frequent earthquakes and have many active volcanoes.</p><h3>Staying safe</h3><ul><li>During an earthquake: Duck, Cover, and Hold.</li><li>Know your community''s evacuation routes for volcanic eruptions.</li><li>Follow PHIVOLCS for official earthquake and volcano bulletins.</li></ul><h3>Activity</h3><p>Make a table with three columns: earthquake, volcano, and mountain range. For each, write the type of plate boundary where it usually forms and one real example from the Philippines or the world.</p><h3>Quick check</h3><ol><li>What is the difference between the focus and the epicenter?</li><li>How do volcanoes form at convergent boundaries?</li><li>Why does the Philippines have many earthquakes?</li></ol><details><summary>Show answers</summary><ol><li>The focus is underground where the slip starts; the epicenter is on the surface directly above it.</li><li>A sinking plate melts, and the magma rises and erupts.</li><li>It lies on the Pacific Ring of Fire, where plates meet.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-SCI' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Kontemporaryong Isyu', m.description = 'Kung ano ang kontemporaryong isyu at paano ito masusuri nang may pananagutan.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang kahulugan ng kontemporaryong isyu</li><li>Uriin ang mga isyu ayon sa saklaw nito</li><li>Suriin ang isang isyu gamit ang mapagkakatiwalaang sanggunian</li></ul></blockquote><p>Araw-araw, nakakabasa tayo ng balita tungkol sa pagtaas ng presyo, bagyo, o bagong batas. Ang mga ito ay hindi lang balita; ito ay mga isyung direktang nakaaapekto sa ating buhay.</p><h3>Ano ang kontemporaryong isyu?</h3><p>Ang <strong>kontemporaryong isyu</strong> ay mga pangyayari, suliranin, o paksang napapanahon, pinag-uusapan ng maraming tao, at may epekto sa lipunan. Ang salitang <em>kontemporaryo</em> ay nangangahulugang "kasalukuyan" o "napapanahon."</p><h3>Mga katangian ng kontemporaryong isyu</h3><ul><li>Napapanahon at kasalukuyang nangyayari</li><li>May malaking epekto sa maraming tao</li><li>Maaaring may magkakaibang pananaw ang mga tao tungkol dito</li><li>Nangangailangan ng solusyon o pagkilos</li></ul><h3>Uri ng kontemporaryong isyu</h3><table><thead><tr><th>Uri</th><th>Halimbawa</th></tr></thead><tbody><tr><td>Pangkapaligiran</td><td>Climate change, polusyon sa ilog, pagbaha</td></tr><tr><td>Pang-ekonomiya</td><td>Implasyon, kawalan ng trabaho, migrasyon</td></tr><tr><td>Panlipunan at pampulitika</td><td>Karapatang pantao, korapsyon, halalan</td></tr><tr><td>Pangkalusugan</td><td>Pandemya, malnutrisyon</td></tr></tbody></table><h3>Saklaw ng isyu</h3><p>Maaaring <strong>lokal</strong> (sa barangay o lungsod), <strong>pambansa</strong> (sa buong bansa), o <strong>pandaigdig</strong> (sa maraming bansa) ang isang isyu.</p><blockquote><p><strong>Halimbawa</strong></p><p>Ang pagbaha sa isang barangay tuwing tag-ulan ay lokal na isyu. Ang pagtaas ng presyo ng bigas ay pambansang isyu. Ang climate change ay pandaigdigang isyu na nakaaapekto sa lahat ng bansa.</p></blockquote><h3>Paano suriin ang isang isyu</h3><ol><li><strong>Alamin ang mga datos</strong> – ano, sino, kailan, saan, at bakit.</li><li><strong>Suriin ang sanggunian</strong> – galing ba sa mapagkakatiwalaang ahensya o pahayagan?</li><li><strong>Kilalanin ang magkakaibang pananaw</strong> – ano ang panig ng bawat grupo?</li><li><strong>Tukuyin ang sanhi at bunga</strong> – ano ang pinagmulan at epekto nito?</li><li><strong>Bumuo ng sariling paninindigan</strong> – batay sa ebidensya, hindi sa sabi-sabi.</li></ol><h3>Pag-iwas sa maling impormasyon</h3><ul><li>Huwag agad maniwala sa post na walang malinaw na pinagmulan.</li><li>Ihambing ang balita sa dalawa o higit pang mapagkakatiwalaang sanggunian.</li><li>Tingnan ang petsa; baka luma na ang balita.</li></ul><h3>Gawain</h3><p>Pumili ng isang balita ngayong linggo. Isulat ang (1) uri ng isyu, (2) saklaw nito, (3) dalawang sanggunian na nagbalita nito, at (4) ang iyong paninindigan sa 3–5 pangungusap.</p><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng "kontemporaryo"?</li><li>Anong uri ng isyu ang implasyon?</li><li>Magbigay ng isang paraan upang maiwasan ang maling impormasyon.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Kasalukuyan o napapanahon</li><li>Pang-ekonomiya</li><li>Alinman sa: suriin ang pinagmulan, ihambing sa ibang sanggunian, tingnan ang petsa</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-AP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Kontemporaryong Isyu', 'Kung ano ang kontemporaryong isyu at paano ito masusuri nang may pananagutan.', '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang kahulugan ng kontemporaryong isyu</li><li>Uriin ang mga isyu ayon sa saklaw nito</li><li>Suriin ang isang isyu gamit ang mapagkakatiwalaang sanggunian</li></ul></blockquote><p>Araw-araw, nakakabasa tayo ng balita tungkol sa pagtaas ng presyo, bagyo, o bagong batas. Ang mga ito ay hindi lang balita; ito ay mga isyung direktang nakaaapekto sa ating buhay.</p><h3>Ano ang kontemporaryong isyu?</h3><p>Ang <strong>kontemporaryong isyu</strong> ay mga pangyayari, suliranin, o paksang napapanahon, pinag-uusapan ng maraming tao, at may epekto sa lipunan. Ang salitang <em>kontemporaryo</em> ay nangangahulugang "kasalukuyan" o "napapanahon."</p><h3>Mga katangian ng kontemporaryong isyu</h3><ul><li>Napapanahon at kasalukuyang nangyayari</li><li>May malaking epekto sa maraming tao</li><li>Maaaring may magkakaibang pananaw ang mga tao tungkol dito</li><li>Nangangailangan ng solusyon o pagkilos</li></ul><h3>Uri ng kontemporaryong isyu</h3><table><thead><tr><th>Uri</th><th>Halimbawa</th></tr></thead><tbody><tr><td>Pangkapaligiran</td><td>Climate change, polusyon sa ilog, pagbaha</td></tr><tr><td>Pang-ekonomiya</td><td>Implasyon, kawalan ng trabaho, migrasyon</td></tr><tr><td>Panlipunan at pampulitika</td><td>Karapatang pantao, korapsyon, halalan</td></tr><tr><td>Pangkalusugan</td><td>Pandemya, malnutrisyon</td></tr></tbody></table><h3>Saklaw ng isyu</h3><p>Maaaring <strong>lokal</strong> (sa barangay o lungsod), <strong>pambansa</strong> (sa buong bansa), o <strong>pandaigdig</strong> (sa maraming bansa) ang isang isyu.</p><blockquote><p><strong>Halimbawa</strong></p><p>Ang pagbaha sa isang barangay tuwing tag-ulan ay lokal na isyu. Ang pagtaas ng presyo ng bigas ay pambansang isyu. Ang climate change ay pandaigdigang isyu na nakaaapekto sa lahat ng bansa.</p></blockquote><h3>Paano suriin ang isang isyu</h3><ol><li><strong>Alamin ang mga datos</strong> – ano, sino, kailan, saan, at bakit.</li><li><strong>Suriin ang sanggunian</strong> – galing ba sa mapagkakatiwalaang ahensya o pahayagan?</li><li><strong>Kilalanin ang magkakaibang pananaw</strong> – ano ang panig ng bawat grupo?</li><li><strong>Tukuyin ang sanhi at bunga</strong> – ano ang pinagmulan at epekto nito?</li><li><strong>Bumuo ng sariling paninindigan</strong> – batay sa ebidensya, hindi sa sabi-sabi.</li></ol><h3>Pag-iwas sa maling impormasyon</h3><ul><li>Huwag agad maniwala sa post na walang malinaw na pinagmulan.</li><li>Ihambing ang balita sa dalawa o higit pang mapagkakatiwalaang sanggunian.</li><li>Tingnan ang petsa; baka luma na ang balita.</li></ul><h3>Gawain</h3><p>Pumili ng isang balita ngayong linggo. Isulat ang (1) uri ng isyu, (2) saklaw nito, (3) dalawang sanggunian na nagbalita nito, at (4) ang iyong paninindigan sa 3–5 pangungusap.</p><h3>Pagsusulit</h3><ol><li>Ano ang ibig sabihin ng "kontemporaryo"?</li><li>Anong uri ng isyu ang implasyon?</li><li>Magbigay ng isang paraan upang maiwasan ang maling impormasyon.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Kasalukuyan o napapanahon</li><li>Pang-ekonomiya</li><li>Alinman sa: suriin ang pinagmulan, ihambing sa ibang sanggunian, tingnan ang petsa</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Mga Isyung Pangkapaligiran at Paghahanda sa Kalamidad', m.description = 'Ang mga suliraning pangkapaligiran ng bansa at kung paano maghanda sa kalamidad.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Tukuyin ang mga pangunahing suliraning pangkapaligiran ng Pilipinas</li><li>Ipaliwanag ang konsepto ng disaster risk reduction</li><li>Gumawa ng plano ng paghahanda sa kalamidad</li></ul></blockquote><p>Isa ang Pilipinas sa mga bansang pinakaapektado ng kalamidad sa mundo. Taon-taon, humigit-kumulang dalawampung bagyo ang pumapasok sa ating teritoryo, bukod pa sa lindol at pagputok ng bulkan.</p><h3>Mga suliraning pangkapaligiran</h3><ol><li><strong>Climate change</strong> – pagbabago ng klima na nagdudulot ng mas malalakas na bagyo, tagtuyot, at pagtaas ng dagat.</li><li><strong>Solid waste</strong> – basurang bumabara sa kanal at nagdudulot ng pagbaha.</li><li><strong>Pagkasira ng kagubatan</strong> – nagdudulot ng landslide at pagkawala ng tirahan ng mga hayop.</li><li><strong>Polusyon sa tubig at hangin</strong> – nakasasama sa kalusugan at kabuhayan.</li></ol><h3>Hazard, vulnerability, at disaster</h3><table><thead><tr><th>Konsepto</th><th>Kahulugan</th><th>Halimbawa</th></tr></thead><tbody><tr><td>Hazard</td><td>Banta na maaaring magdulot ng pinsala</td><td>Malakas na bagyo</td></tr><tr><td>Vulnerability</td><td>Kahinaan ng komunidad na harapin ang banta</td><td>Bahay na yari sa magagaang materyales malapit sa ilog</td></tr><tr><td>Disaster</td><td>Malawakang pinsala kapag tinamaan ng hazard ang bulnerableng komunidad</td><td>Pagbaha na sumira sa daan-daang bahay</td></tr></tbody></table><blockquote><p><strong>Tandaan</strong></p><p>Hindi natin mapipigilan ang bagyo, ngunit mababawasan natin ang pinsala nito kung babawasan natin ang ating vulnerability. Ito ang layunin ng <strong>Disaster Risk Reduction and Management (DRRM)</strong>.</p></blockquote><h3>Mga yugto ng DRRM</h3><ol><li><strong>Bago ang kalamidad</strong> – paghahanda: go-bag, evacuation plan, pagsunod sa babala ng PAGASA at PHIVOLCS.</li><li><strong>Habang may kalamidad</strong> – pagtugon: lumikas kung kinakailangan at manatiling ligtas.</li><li><strong>Pagkatapos ng kalamidad</strong> – rehabilitasyon: paglilinis, pagsasaayos, at pagtulong sa kapwa.</li></ol><h3>Laman ng go-bag</h3><ul><li>Tubig at pagkaing hindi madaling masira</li><li>Flashlight, extra baterya, at power bank</li><li>Gamot at first aid kit</li><li>Kopya ng mahahalagang dokumento sa plastic na lalagyan</li><li>Damit at kumot</li></ul><h3>Gawain</h3><p>Gumawa ng <strong>family disaster plan</strong>: (1) mga posibleng hazard sa inyong lugar, (2) pinakamalapit na evacuation center, (3) laman ng inyong go-bag, at (4) kung saan magkikita ang pamilya kung magkahiwa-hiwalay.</p><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng hazard at disaster?</li><li>Anong ahensya ang nagbibigay ng babala tungkol sa bagyo?</li><li>Magbigay ng dalawang laman ng go-bag.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang hazard ay banta; ang disaster ay ang malawakang pinsalang nangyari na.</li><li>PAGASA</li><li>Alinman sa: tubig, pagkain, flashlight, gamot, dokumento, damit</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-AP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Mga Isyung Pangkapaligiran at Paghahanda sa Kalamidad', 'Ang mga suliraning pangkapaligiran ng bansa at kung paano maghanda sa kalamidad.', '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Tukuyin ang mga pangunahing suliraning pangkapaligiran ng Pilipinas</li><li>Ipaliwanag ang konsepto ng disaster risk reduction</li><li>Gumawa ng plano ng paghahanda sa kalamidad</li></ul></blockquote><p>Isa ang Pilipinas sa mga bansang pinakaapektado ng kalamidad sa mundo. Taon-taon, humigit-kumulang dalawampung bagyo ang pumapasok sa ating teritoryo, bukod pa sa lindol at pagputok ng bulkan.</p><h3>Mga suliraning pangkapaligiran</h3><ol><li><strong>Climate change</strong> – pagbabago ng klima na nagdudulot ng mas malalakas na bagyo, tagtuyot, at pagtaas ng dagat.</li><li><strong>Solid waste</strong> – basurang bumabara sa kanal at nagdudulot ng pagbaha.</li><li><strong>Pagkasira ng kagubatan</strong> – nagdudulot ng landslide at pagkawala ng tirahan ng mga hayop.</li><li><strong>Polusyon sa tubig at hangin</strong> – nakasasama sa kalusugan at kabuhayan.</li></ol><h3>Hazard, vulnerability, at disaster</h3><table><thead><tr><th>Konsepto</th><th>Kahulugan</th><th>Halimbawa</th></tr></thead><tbody><tr><td>Hazard</td><td>Banta na maaaring magdulot ng pinsala</td><td>Malakas na bagyo</td></tr><tr><td>Vulnerability</td><td>Kahinaan ng komunidad na harapin ang banta</td><td>Bahay na yari sa magagaang materyales malapit sa ilog</td></tr><tr><td>Disaster</td><td>Malawakang pinsala kapag tinamaan ng hazard ang bulnerableng komunidad</td><td>Pagbaha na sumira sa daan-daang bahay</td></tr></tbody></table><blockquote><p><strong>Tandaan</strong></p><p>Hindi natin mapipigilan ang bagyo, ngunit mababawasan natin ang pinsala nito kung babawasan natin ang ating vulnerability. Ito ang layunin ng <strong>Disaster Risk Reduction and Management (DRRM)</strong>.</p></blockquote><h3>Mga yugto ng DRRM</h3><ol><li><strong>Bago ang kalamidad</strong> – paghahanda: go-bag, evacuation plan, pagsunod sa babala ng PAGASA at PHIVOLCS.</li><li><strong>Habang may kalamidad</strong> – pagtugon: lumikas kung kinakailangan at manatiling ligtas.</li><li><strong>Pagkatapos ng kalamidad</strong> – rehabilitasyon: paglilinis, pagsasaayos, at pagtulong sa kapwa.</li></ol><h3>Laman ng go-bag</h3><ul><li>Tubig at pagkaing hindi madaling masira</li><li>Flashlight, extra baterya, at power bank</li><li>Gamot at first aid kit</li><li>Kopya ng mahahalagang dokumento sa plastic na lalagyan</li><li>Damit at kumot</li></ul><h3>Gawain</h3><p>Gumawa ng <strong>family disaster plan</strong>: (1) mga posibleng hazard sa inyong lugar, (2) pinakamalapit na evacuation center, (3) laman ng inyong go-bag, at (4) kung saan magkikita ang pamilya kung magkahiwa-hiwalay.</p><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng hazard at disaster?</li><li>Anong ahensya ang nagbibigay ng babala tungkol sa bagyo?</li><li>Magbigay ng dalawang laman ng go-bag.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang hazard ay banta; ang disaster ay ang malawakang pinsalang nangyari na.</li><li>PAGASA</li><li>Alinman sa: tubig, pagkain, flashlight, gamot, dokumento, damit</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-AP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Isip at Kilos-loob', m.description = 'Ang dalawang kakayahang nagpapakilala sa tao: ang pag-unawa at ang malayang pagpili.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang gamit ng isip at kilos-loob</li><li>Ipakita kung paano nagtutulungan ang dalawa sa pagpapasya</li><li>Suriin ang sariling pasya batay sa tamang gamit ng isip at kilos-loob</li></ul></blockquote><p>Ano ang pinagkaiba ng tao sa hayop? Parehong kumakain, natutulog, at nararamdaman ang sakit. Ngunit ang tao lamang ang kayang mag-isip kung tama o mali ang isang bagay at pumili kung gagawin ito.</p><h3>Ang isip</h3><p>Ang <strong>isip</strong> ay kakayahan ng tao na <strong>umunawa, magsuri, at maghanap ng katotohanan</strong>. Sa pamamagitan nito, natututo tayo, nakapagtatanong, at nakabubuo ng konklusyon.</p><ul><li>Layunin ng isip: ang <strong>katotohanan</strong></li><li>Gawain: umunawa, maghusga, mangatwiran</li></ul><h3>Ang kilos-loob</h3><p>Ang <strong>kilos-loob</strong> ay kakayahan ng tao na <strong>pumili at kumilos</strong> ayon sa nauunawaan ng isip. Ito ang nagpapasya kung gagawin o hindi ang isang bagay.</p><ul><li>Layunin ng kilos-loob: ang <strong>kabutihan</strong></li><li>Gawain: pumili, magpasya, kumilos</li></ul><table><thead><tr><th></th><th>Isip</th><th>Kilos-loob</th></tr></thead><tbody><tr><td>Kakayahan</td><td>Umunawa</td><td>Pumili</td></tr><tr><td>Hinahanap</td><td>Katotohanan</td><td>Kabutihan</td></tr><tr><td>Tanong na sinasagot</td><td>"Ano ang tama?"</td><td>"Gagawin ko ba ito?"</td></tr></tbody></table><h3>Paano sila nagtutulungan</h3><p>Inaalam ng isip kung ano ang tama; pinipili naman ng kilos-loob kung susundin ito. Hindi sapat na alam mo ang tama; kailangan mo ring piliin ito.</p><blockquote><p><strong>Halimbawa</strong></p><p>Napansin ni Ana na sobra ang sukling ibinigay sa kanya ng tindera. Alam ng kanyang isip na hindi kanya ang sobrang pera (katotohanan). Pinili ng kanyang kilos-loob na ibalik ito (kabutihan). Dito, ginamit niya nang tama ang dalawa.</p></blockquote><h3>Paglinang ng isip at kilos-loob</h3><ul><li><strong>Para sa isip:</strong> magbasa, magtanong, makinig sa iba''t ibang pananaw, at suriin ang impormasyon bago maniwala.</li><li><strong>Para sa kilos-loob:</strong> sanayin ang sarili sa maliliit na mabuting pasya araw-araw, gaya ng pagtupad sa pangako at pag-iwas sa tukso.</li></ul><h3>Gawain</h3><p>Isalaysay ang isang mahirap na pasya na ginawa mo kamakailan. Isulat (1) ano ang naunawaan ng iyong isip tungkol sa sitwasyon, (2) ano ang pinili ng iyong kilos-loob, at (3) kung gagawin mo ba itong muli at bakit.</p><h3>Pagsusulit</h3><ol><li>Ano ang layunin ng isip?</li><li>Ano ang layunin ng kilos-loob?</li><li>Bakit hindi sapat na alam lang ang tama?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Katotohanan</li><li>Kabutihan</li><li>Dahil kailangan pa ring piliin at gawin ng kilos-loob ang tama.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-ESP' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Isip at Kilos-loob', 'Ang dalawang kakayahang nagpapakilala sa tao: ang pag-unawa at ang malayang pagpili.', '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang gamit ng isip at kilos-loob</li><li>Ipakita kung paano nagtutulungan ang dalawa sa pagpapasya</li><li>Suriin ang sariling pasya batay sa tamang gamit ng isip at kilos-loob</li></ul></blockquote><p>Ano ang pinagkaiba ng tao sa hayop? Parehong kumakain, natutulog, at nararamdaman ang sakit. Ngunit ang tao lamang ang kayang mag-isip kung tama o mali ang isang bagay at pumili kung gagawin ito.</p><h3>Ang isip</h3><p>Ang <strong>isip</strong> ay kakayahan ng tao na <strong>umunawa, magsuri, at maghanap ng katotohanan</strong>. Sa pamamagitan nito, natututo tayo, nakapagtatanong, at nakabubuo ng konklusyon.</p><ul><li>Layunin ng isip: ang <strong>katotohanan</strong></li><li>Gawain: umunawa, maghusga, mangatwiran</li></ul><h3>Ang kilos-loob</h3><p>Ang <strong>kilos-loob</strong> ay kakayahan ng tao na <strong>pumili at kumilos</strong> ayon sa nauunawaan ng isip. Ito ang nagpapasya kung gagawin o hindi ang isang bagay.</p><ul><li>Layunin ng kilos-loob: ang <strong>kabutihan</strong></li><li>Gawain: pumili, magpasya, kumilos</li></ul><table><thead><tr><th></th><th>Isip</th><th>Kilos-loob</th></tr></thead><tbody><tr><td>Kakayahan</td><td>Umunawa</td><td>Pumili</td></tr><tr><td>Hinahanap</td><td>Katotohanan</td><td>Kabutihan</td></tr><tr><td>Tanong na sinasagot</td><td>"Ano ang tama?"</td><td>"Gagawin ko ba ito?"</td></tr></tbody></table><h3>Paano sila nagtutulungan</h3><p>Inaalam ng isip kung ano ang tama; pinipili naman ng kilos-loob kung susundin ito. Hindi sapat na alam mo ang tama; kailangan mo ring piliin ito.</p><blockquote><p><strong>Halimbawa</strong></p><p>Napansin ni Ana na sobra ang sukling ibinigay sa kanya ng tindera. Alam ng kanyang isip na hindi kanya ang sobrang pera (katotohanan). Pinili ng kanyang kilos-loob na ibalik ito (kabutihan). Dito, ginamit niya nang tama ang dalawa.</p></blockquote><h3>Paglinang ng isip at kilos-loob</h3><ul><li><strong>Para sa isip:</strong> magbasa, magtanong, makinig sa iba''t ibang pananaw, at suriin ang impormasyon bago maniwala.</li><li><strong>Para sa kilos-loob:</strong> sanayin ang sarili sa maliliit na mabuting pasya araw-araw, gaya ng pagtupad sa pangako at pag-iwas sa tukso.</li></ul><h3>Gawain</h3><p>Isalaysay ang isang mahirap na pasya na ginawa mo kamakailan. Isulat (1) ano ang naunawaan ng iyong isip tungkol sa sitwasyon, (2) ano ang pinili ng iyong kilos-loob, at (3) kung gagawin mo ba itong muli at bakit.</p><h3>Pagsusulit</h3><ol><li>Ano ang layunin ng isip?</li><li>Ano ang layunin ng kilos-loob?</li><li>Bakit hindi sapat na alam lang ang tama?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Katotohanan</li><li>Kabutihan</li><li>Dahil kailangan pa ring piliin at gawin ng kilos-loob ang tama.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-ESP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Konsensya at ang Likas na Batas Moral', m.description = 'Ang panloob na gabay sa tama at mali, at ang batas moral na likas sa lahat ng tao.', m.content = '<blockquote><p><strong>Sa pagtatapos ng modyul na ito, inaasahang kaya mong:</strong></p><ul><li>Ipaliwanag ang konsensya at ang likas na batas moral</li><li>Tukuyin ang mga uri ng konsensya</li><li>Gamitin ang mga hakbang sa paghubog ng tamang konsensya</li></ul></blockquote><p>Naranasan mo na bang makaramdam ng bigat ng loob pagkatapos magsinungaling? Iyan ang tinig ng iyong <strong>konsensya</strong>.</p><h3>Ano ang konsensya?</h3><p>Ang konsensya ay ang <strong>paghuhusga ng isip</strong> kung mabuti o masama ang isang kilos sa isang tiyak na sitwasyon. Ito ay gumagabay bago tayo kumilos at humuhusga pagkatapos nating kumilos.</p><h3>Ang likas na batas moral</h3><p>Ang <strong>likas na batas moral</strong> ay ang pangkalahatang batas na nakaukit sa puso ng bawat tao: <strong>"Gawin ang mabuti, iwasan ang masama."</strong> Hindi ito isinulat ng tao; likas itong alam ng lahat, anuman ang lahi, relihiyon, o panahon.</p><ul><li><strong>Pangkalahatan</strong> – para sa lahat ng tao</li><li><strong>Hindi nagbabago</strong> – pareho noon at ngayon</li><li><strong>Walang hanggan</strong> – hindi nawawala</li></ul><blockquote><p><strong>Halimbawa</strong></p><p>Sa lahat ng kultura, itinuturing na masama ang pagpatay sa inosente at mabuti ang pagtulong sa nangangailangan. Patunay ito na may likas na batas moral na alam ng lahat.</p></blockquote><h3>Mga uri ng konsensya</h3><table><thead><tr><th>Uri</th><th>Paliwanag</th></tr></thead><tbody><tr><td>Tama</td><td>Wastong nakahuhusga ng mabuti at masama</td></tr><tr><td>Mali</td><td>Nagkakamali sa paghuhusga, madalas dahil sa kakulangan ng kaalaman</td></tr><tr><td>Tiyak</td><td>Sigurado sa kanyang paghuhusga</td></tr><tr><td>Nag-aalinlangan</td><td>Hindi sigurado; dapat munang alamin bago kumilos</td></tr></tbody></table><h3>Paghubog ng tamang konsensya</h3><ol><li><strong>Alamin at naisin ang mabuti</strong> – magkaroon ng tamang kaalaman tungkol sa moral na isyu.</li><li><strong>Suriin ang sitwasyon</strong> – tingnan ang lahat ng detalye at posibleng bunga.</li><li><strong>Humingi ng payo</strong> – sa magulang, guro, o taong may malawak na karanasan.</li><li><strong>Magnilay at magpasya</strong> – pumili ng kilos na tugma sa likas na batas moral.</li></ol><blockquote><p><strong>Tandaan</strong></p><p>Kapag nag-aalinlangan ang konsensya, huwag munang kumilos hangga''t hindi malinaw kung tama ang gagawin.</p></blockquote><h3>Gawain</h3><p>Basahin ang sitwasyon: <em>Nakita mong kinokopya ng iyong matalik na kaibigan ang sagot ng iba sa pagsusulit.</em> Gamit ang apat na hakbang sa paghubog ng konsensya, isulat kung ano ang gagawin mo at bakit.</p><h3>Pagsusulit</h3><ol><li>Ano ang pangunahing prinsipyo ng likas na batas moral?</li><li>Ano ang dapat gawin kapag nag-aalinlangan ang konsensya?</li><li>Magbigay ng isang katangian ng likas na batas moral.</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Gawin ang mabuti, iwasan ang masama.</li><li>Huwag munang kumilos; alamin muna ang tama.</li><li>Alinman sa: pangkalahatan, hindi nagbabago, walang hanggan</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-ESP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
