UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Active Recreation and Consumer Health', m.description = 'Staying active through recreation, and making wise choices about health products and services.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Plan safe active recreational activities</li><li>Explain the benefits of active recreation</li><li>Evaluate health products and services as a smart consumer</li></ul></blockquote><h3>Part 1: Physical Education – Active Recreation</h3><p><strong>Active recreation</strong> is any physical activity done during free time for enjoyment, such as hiking, biking, swimming, dancing, or playing sports with friends.</p><h4>Benefits</h4><ul><li><strong>Physical:</strong> improves heart health, strength, and flexibility.</li><li><strong>Mental:</strong> reduces stress and improves mood.</li><li><strong>Social:</strong> builds friendships and teamwork.</li></ul><h4>Planning a safe activity</h4><ol><li>Choose an activity that fits your fitness level.</li><li>Check the weather and the place beforehand.</li><li>Bring water, proper clothing, and a first aid kit.</li><li>Warm up before and cool down after.</li><li>Never go alone; tell someone where you are going.</li><li>Follow "Leave No Trace": bring your trash home.</li></ol><blockquote><p><strong>Example</strong></p><p>For a morning hike, a group starts at 6 a.m. to avoid the midday heat, brings two liters of water each, wears closed shoes, and informs the barangay or park office of their route.</p></blockquote><h3>Part 2: Health – Consumer Health</h3><p><strong>Consumer health</strong> is about choosing health products, services, and information wisely. A smart consumer protects both their health and their money.</p><h4>Reading a product label</h4><table><thead><tr><th>Check</th><th>Why it matters</th></tr></thead><tbody><tr><td>Expiration date</td><td>Expired products may be unsafe</td></tr><tr><td>Ingredients</td><td>Avoid allergens and harmful substances</td></tr><tr><td>Directions and dosage</td><td>Using too much can be dangerous</td></tr><tr><td>FDA registration</td><td>Shows the product passed safety standards in the Philippines</td></tr></tbody></table><h4>Spotting false claims</h4><ul><li>Promises like "cures all diseases" or "lose 10 kg in a week"</li><li>Testimonials only, with no scientific evidence</li><li>Pressure to "buy now" before a deadline</li></ul><blockquote><p><strong>Remember</strong></p><p>Food supplements are not medicine. Products labeled "No approved therapeutic claims" cannot claim to cure or treat illness.</p></blockquote><h3>Activity</h3><p>Part A: Plan a one-day active recreation outing for your family, listing the activity, schedule, things to bring, and safety rules. Part B: Examine one health product at home and record its expiration date, main ingredients, dosage, and whether it has an FDA registration number.</p><h3>Quick check</h3><ol><li>Give one mental benefit of active recreation.</li><li>Why should you check the FDA registration of a product?</li><li>Give one sign of a false health claim.</li></ol><details><summary>Show answers</summary><ol><li>Any one: reduces stress, improves mood.</li><li>It shows the product passed safety standards.</li><li>Any one: promises a cure for everything, unrealistic results, testimonials only, pressure to buy now.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-MAPEH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
